with nuevas(numero,viejo,sec) as (values
(161,'26da5acf19bb05a213ca6b857585a477',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ìká anuncia un hijo y pide ofrendar para que padres e hijo tengan asiento y estabilidad; también habla de proteger los secretos. Un antiguo empleado, una persona cercana o los chismes pueden revelar sus secretos y causarle problemas. Ifá escucha sus ruegos, y lo que pida debe darse el mismo día. Llegará a viejo aunque lo molesten."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa el futuro de un hijo o dónde va a vivir (relato de Ọmotitun).", "Viaja mucho y busca un lugar estable.", "Alguien de confianza puede contar sus secretos (relato de Ayékogbejẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un hijo que tenga un lugar estable en el mundo.", "Que los secretos no salgan a la luz.", "Que Ifá escuche sus súplicas.", "Llegar a viejo sin que lo venzan."]}, {"titulo": "Ibi y advertencias", "puntos": ["Andar errante sin asentarse.", "Un confidente que revela los secretos.", "Vergüenza por lo que se divulga."]}, {"titulo": "Enseñanza principal", "texto": "Por mucho que pisen a la sandalia, sigue hablando y dura hasta vieja. El que ofrenda no se desgasta antes de tiempo."}, {"titulo": "Relatos reunidos", "puntos": ["El recién nacido viajero. Le dijeron a la familia de un recién nacido que de grande le gustaría andar por todo el mundo sin asentarse, y que ofrendaran para que tuviera residencia estable: un caracol, un pangolín, 3,200 cauríes y medicina de Ifá.", "Los secretos revelados. Un confidente estaba revelando los secretos de Ayekogbejẹ. Le pidieron un caracol, aceite de palma, manteca de cacao, una paloma, 6,600 cauríes y medicina de Ifá para no pasar la vergüenza. Ofreció.", "Onílé Orókè y la campana. Onílé Orókè ofreció. '¿Oyen la campana? Sí, la oímos en casa de Onílé Orókè. Ifá escucha nuestra súplica.'", "La sandalia en Lìkì. La sandalia iba a ejercer en la tierra de Lìkì y preguntó si le iría bien. Le dijeron que sí, si ofrendaba. Por más que la pisaban y la arrastraban, seguía sonando 'pèé, pèé'; no la vencieron, y solo la dejaron cuando ya estaba vieja."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El recién nacido: un caracol, un pangolín, 3,200 cauríes y medicina de Ifá.", "Contra la vergüenza: un caracol, aceite de palma, manteca de cacao, una paloma, 6,600 cauríes y medicina de Ifá.", "Lo que Ifá pida, el mismo día."]}, {"titulo": "Relaciones espirituales", "texto": "Las Irúnmọlẹ̀ escuchan la súplica. Ifá oye la voz del babaláwo verdadero."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de jókó-jẹ (Cissampelos owariensis) cocinadas en sopa con carne de pangolín y caracol, y molidas con jabón para baño. Caracol, manteca de cacao."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 161.1 (yorùbá): Ọ̀sá-rin-ka: / a difá fün Ọmotitun, / wọn ni: / Dmotitun yi a feran irinkiri ninu ayé / nigbati o ba dagba. / Wọ̀n ni ki a rúbọ / kloleni ibujoko li ayé; / kiara le rọọ. / Ebọ: Igbin, Aiká, Ọ̀ṣẹ́, / egberindilógún owó / ati ewé Ifá (Jókó-jé)", "Verso 161.2 (yorùbá): Ọrọ-ikoko-gbamgba-ni-mbq: / a daa fún Ayékogbejẹ. / Ẹni ti a ba mulẹni kọkọ / ntumọ ohun tiajoṣe, / wọ̀n niki o wa rúbọ / ki o ma baa ṣe ğràn itiju si ikoko, / ki orẹ ma le tu aṣiri rẹ. / Ẹbọ: İgbin, epo, òrí, eyẹlé, / egbẹ̀talélógbọ̀n owó ati ewé Ifá. / Ó gbọ̀ ó rú.", "REZO: OSA KANI IWANI AUTELE KOLE ADIFAFUN ARITINLO EYUA YOLE ELANYO EYUA AKUKO LEBO, OUNKO LEBO, ORI EBBO, ADIE, EWE TINLO YOKULA UNLO ASHO FUN FUN IKAN LOWA. OSA KA IFA OINA LORDAFUN OMO."]}]$q$::jsonb),
(162,'58b73f3a1603bc879bfc86e46e3f3014',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Òtúrúpọ̀n habla de la infertilidad y de la ofrenda para una vida larga. Es buen momento para ofrendar a Ògún buscando concebir. Pide ofrendar por hijos agradecidos y que la mujer no deje a su esposo para no lamentarlo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea tener hijos o le preocupa su fertilidad (relato de Ọ̀sá Atinuṣojo).", "Quiere asegurar su bienestar a largo plazo.", "En la familia hay tensión entre juntar bienes y cuidar a los hijos (relato de Yèyé Owójùwà y Yèyé Omójùwà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Salud y vida larga, como la piel del animal.", "Hijos que honran a la madre.", "Riqueza, pareja e hijos en la casa de la mujer que se calma."]}, {"titulo": "Ibi y advertencias", "puntos": ["No poder cargar un hijo en la espalda.", "Tener solo dinero y nadie que herede.", "Andar de un lado a otro sin asentarse en la casa."]}, {"titulo": "Enseñanza principal", "texto": "Los hijos valen más que la riqueza. Owójùwà ofrendó solo por dinero y, al morir, otros heredaron; Omọ́jùwà ofrendó por hijos, y sus hijos la enriquecieron y la despidieron con honores."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀sá Atinuṣojo. 'Ella no carga un bebé en la espalda.' A Ọ̀sá Atinuṣojo le pidieron una chiva, una gallina, 16,000 cauríes y medicina de Ifá para tener un hijo. Se negó.", "La piel del animal. A la piel le dijeron que sería salud y vida larga para el cuerpo de cualquier animal, y ofreció una paloma, una carnera, kola y 42,000 cauríes.", "Owójùwà y Omọ́jùwà. Dos mujeres venían del cielo a la tierra. Owójùwà ofrendó solo por la riqueza y llegó a tener dinero sin medida, pero no tuvo hijos; cuando murió le hicieron su ceremonia y todos se fueron, y otros se quedaron con su dinero. Omọ́jùwà ofrendó por los hijos y tuvo muchos; lo que ganaba, los hijos se lo comían, pero con el tiempo ellos la enriquecieron. Cuando murió, sus hijos la enterraron con honores, ensillaron un caballo, bailaron por el pueblo y dispararon al aire, cosa que entonces no se hacía. El rey los llamó, y ellos le dijeron: 'La madre no muere dos veces'. Le cantaron: 'Los hijos valen más que el carácter, hoy y mañana'. El rey reconoció que tenían razón y los dejó seguir bailando.", "La gallina que andaba de un lado a otro. A Olórùbùrekè, la gallina, le dijeron que fuera tranquila y reservada en casa de su esposo. No hizo caso y andaba de un lado a otro. Después ofreció, se calmó, y en su casa no faltó riqueza, pareja ni hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para un hijo: una chiva, una gallina, 16,000 cauríes y medicina de Ifá.", "La piel: una paloma, una carnera, kola y 42,000 cauríes.", "Ofrenda a Ògún para concebir."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún ayuda a concebir. El rey reconoce el valor de los hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Chiva, gallina, carnera, kola. Ante dificultades para concebir, conviene también la consulta médica."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 162.1 (yorùbá): Koromogbepon: / a difá fún Ọ̀sá Atinuṣojo, / Wọn niki o wa rúbọ / nitoripe kiobaa le r'omo bi. / Ebọ: Ewúré, agbebo, egbàájo owó ati ewé Ifá. / Ô gbọ̀ ẹbọ ko rúbọ.", "Verso 162.2 (yorùbá): Ọ̀sá-Òtúrúpọ̀n, / Ọ̀sá-Òtúrúpọ̀n: / a difa fún Awo (eran), / Wọ̀n ni: Ara Awọ a le, / a pe l'ayé ju erankẹran. / Ebọ: eyẹlé, àgùtàn, obi ati ẹgbàá mọ̀kànlélógún owó. / Ô gbọ̀ ó rú.", "REZO: OSA TRUPON ARIBURU TRUPON OSA RULU OTRUPON OM EYELE ELODI ODEFA AB TINSHOMO OLU OD OSA KUNA OTRUPON OM YEL LODI ADAFUN PAKERE, TINSHOMO OLUBO OSA TRUPON OSA LANU.", "REZO: OSA TRUPON ORITUROPON OSA OTRUPA AMEYLE ELADI ODIFA ABA TINCHOMA OLU ODA TRU AN ORI TUROPAN OSA LUNU OTUROPAN OMA EYELE LADI ADAFUN PAQUERE TINCHOMA OLUBO OSA TURUPAN ORI TURUPAN OSA LANU OTURUPAN OMA YEYE GUA OWO EYELE AKUKO LEBO.", "REZO: OSA TRUPON OSA TRUPASA OFORI BERE BERE RILE ENLLANLA OSHUN QUELE QUELE HUO ADIFAFUN ORUNMILA OLUPON TINLO NUMUCODABA NUNU OMI GUADA LLESASI OGUE Y SHANGO.", "REZO: KAFEREFUN SHANGO, YALORDE, OBATALA ALA OGGUN E ILLA.", "REZO: OSA TRUPO BEBEWA OKUN, ADIFAFUN OMO OLOKUN OMI LOSA ARUKO LASHE OKUN ORUN FOSHE, AYEBEWE OKUASUN AGANA ERI OMO OLOKUN OMILONA ORUKO LASHE BOKUN ORUN DOSA FOLOKUN OLONA, ALAYENIFA OMO LA MESAN ADIFAFUN OLOKUN AWONIFA OMO LOSAIN SAIN ORUN, OKANA YEKUABARI OZAIN OMOTOKUN AFEFE LAYRO BROMO, BRONSIA, AFEFE LEKUN ORUN EYA IKU OMO EYA NABEYA OLOKUN AGBA DOA OKUN LAYE IRENIFA OZAIN LODAFUN ORUNMILA."]}]$q$::jsonb),
(163,'0d98203cfb521c9f13d316fc2c055476',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Òtúrá dice que los dioses favorecen a quienes dicen la verdad y están en armonía con el buen carácter de Olódùmarè. La persona debe enfrentar un problema que ha estado evitando. Ifá le desea buena fortuna de pareja y le permite llegar a la raíz de lo que investiga."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está evitando un problema que ya conoce.", "Quiere investigar un asunto para saber qué lo causó.", "La decepción o el enojo le impiden hablar con franqueza (relato de Ọ̀sá Òtúrá preguntando qué es la verdad)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser bendecido por decir la verdad.", "Conseguir pareja con astucia y paciencia.", "Llegar a la raíz de un asunto.", "No ver el mal si ofrenda."]}, {"titulo": "Ibi y advertencias", "puntos": ["La mentira.", "Evitar un problema que hay que enfrentar."]}, {"titulo": "Enseñanza principal", "texto": "La verdad es el buen carácter de Olódùmarè, su palabra que no falla y no se corrompe. 'Habla la verdad, sé justo: al que dice la verdad, Dios lo ayuda.'"}, {"titulo": "Relatos reunidos", "puntos": ["¿Qué es la verdad? Ọ̀sá Òtúrá pregunta qué es la verdad, y Ọ̀rúnmìlà responde: es Olúwa, el Señor de la tierra; es la sabiduría que viene de Olódùmarè; es el buen carácter de Olódùmarè y su palabra infalible, la palabra que no se corrompe. Ifá dijo que las personas del mundo debían ser sinceras.", "Ọ̀rúnmìlà y las tres hijas. Tres muchachas, Somúrógé, hija de Alárá; Sòkùndìgbà, hija de Ajerò; y Somúlùké, hija de Ọwáràngún Àga, decidieron casarse solo con quien supiera sus nombres verdaderos. Ọ̀rúnmìlà preguntó cómo saberlos. Le dijeron que pusiera tres platos de ẹ̀kuru blanco en el camino por donde ellas iban al arroyo y se escondiera. Al ver los platos, se llamaron una a otra por su nombre, y Ọ̀rúnmìlà los memorizó. Comieron y rompieron los platos. Él salió y les reclamó sus platos por nombre. Los padres le ofrecieron veinte, treinta y cincuenta mil, y él dijo que solo una persona entera pagaba sus platos. Cada padre le dijo a su hija: 'Síguelo'. Así se casó con las tres.", "Ọ̀rúnmìlà y el secreto de Olódùmarè. Ọ̀rúnmìlà quería conocer los secretos de todo y le pidieron poner su ofrenda en la playa. Cuando llegó, Olódùmarè se había quitado la ropa: el mar es su parte más grande, y cuando respira, la marea sube y baja. Olódùmarè sospechó y le preguntó si había visto su secreto. Ọ̀rúnmìlà respondió que solo había visto la orilla. Olódùmarè le dijo: 'De ahora en adelante no habrá nada que no sepas'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para ser bendecido: iyẹ̀-ìrosùn marcado con el signo y el rezo, mezclado con ẹ̀kọ para comer, o con aceite de palma para lamer de la mano mientras se canta.", "Para la pareja: tres platos de ẹ̀kuru blanco en el camino del arroyo.", "Para llegar al fondo de las cosas: la ofrenda en la playa."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè es la verdad. Ọ̀rúnmìlà conoce sus secretos. Alárá, Ajerò y Ọwáràngún dan a sus hijas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀kuru blanco, ẹ̀kọ, aceite de palma, iyẹ̀-ìrosùn."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 163.1 (yorùbá): Ọ̀sá Òtúrá I: kinni Òtító? / Emi l: kinni Otító? / Ọ̀rúnmìlà I: / Otító ni Olúwa òrún ti ntọ ayé. / Ọ̀sá Òtúrá I: kinni Òtítọ̀? / Emi I: kinni Otitó? / Ọ̀rúnmìlà 1: / Òtítọ̀ li Éni-airi ti ntọ ayé. / Ọgbọ̀n ti Olódumare nlọ. / Ọgbọ̀n-ńlá. / Ọ̀sá Òtúrá I: kinni Òtitó? / Emi I: kinni Otitó? / Ọ̀rúnmìlà 1: / Otitó ni iwà Olódumare, Otíto. / Ki àwọn omọ aráiyé / le maa mọ Otító / lati inú wa kiosi le rọ wọn lọrùn / lati maaṣe Otító. / Idabo: A le sa idabo rẹ nipa titẹ Odù Ọ̀sá Òtúrá pẹlu iyẹ̀-irosù, / kiape ohun Ifá naa sii kiafifi-ẹkọ mu tabi ki a daa sinu epo fún lila. / Orin Ifá na: / Ṣ’òtítọ́; Ṣ’òtítọ́; / Ṣ' òtító o si tun Ṣ'ódódó! / Éni Ṣ àtítọ̀ ni Imalẹ̀ yoo gbe o!", "REZO: OSA KURE KUYE KURE ADIFAFUN MANGUINI IDOROKO ODE EYELE LEBO, EWE ERI META ENULAGUEGUI LORDAFUN DETISHE OLOKUN ODDAFUN MOYE TINSHOMO OROPOTONIFE MAFEREFUN OBATALA ATI ALAFIA.", "REZO: OSA OTUA (ACUOCUN ESHU) OSA URE FIMI MI CHILLA AGUTAN OFICI CHIO CHIO CHAO ACUOCUN ESHU GUEQUI LODAFUN DETICHOMO OLOKUN ORDAFUN HOYETICHOMO OROPOTO NIFE.", "KAFEREFUN OBATALA Y ALAFIA.", "SUYERE: ASANA OSA NANA OMOLUPAO. EWE MI LERI KE TUTU. EWE OSANA OSA NANA OMOLUPAO. EWE ASANA OSA NANA OMOLUPAO. EWE ASANA OMOLUPAO.", "REZO: OSA URE URE OSA TURA IYA IYALONA OMO MOFE BABA BABA EGGUN O MOMOFE BABA OLORUN IYA ASHEBO ASHETE OBATALA ABATAISA JEKUA OBANIYE LAYE ASHE IYA IRE ASHEGUN OTA.", "REZO: OSA WILLEWE OSA EGGUN AWO KOYESI EGGUN OSHALUFON DEI JEKUA OBARA WILAYE AWA UNLOSA OMO OSA URE OSARA YELEKUN EGGUN AWO OMO ALAWO EGGUN FIEDENO.", "REZO: OSA OTURA ENI EURE OSHANLA JEKUA OGGUN, AÑAKALU OBE ONA OMONI IFA JUNKO ELERIPUIN ASHEGUN OKA IFA KAFEREFUN ELEGBA, OBATALA, OGGUN, ORUNMILA, OMONI IFA RUNKE ORUBO."]}]$q$::jsonb),
(164,'f6b70620af5eacb98ca9157feaeed315',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ìrẹtẹ̀ dice que la única solución a los problemas actuales viene de las deidades. La persona no recibe apoyo moral ni práctico de su pareja. Ifá le promete regalos y vida larga, y le pide ser generoso: las cosas buenas no se alejarán de él."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su pareja no le da apoyo práctico ni moral.", "Se siente solo con una carga pesada (relato del recién llegado al campo vacío).", "Un pleito en casa le impide aprovechar algo bueno.", "Se pregunta si una fortuna que se fue puede volver."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que Dios lo ayude cuando no tiene a nadie.", "Regalos de riqueza, pareja, hijos y casa.", "Que lo bueno regrese a la casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Estar solo con su carga.", "Falta de apoyo de la pareja.", "Que las bendiciones no quieran entrar."]}, {"titulo": "Enseñanza principal", "texto": "El que no tiene a nadie pone su confianza en Dios. El que da de comer en abundancia a todos recibe bendiciones en abundancia."}, {"titulo": "Relatos reunidos", "puntos": ["El forastero y su carga. 'Si el que duerme solo duerme mal, solo Dios puede despertarlo.' Un forastero iba a establecerse en un campo vacío y le pidieron una gallina, 3,200 cauríes y medicina de Ifá para tener quien le ayudara a subirse la carga a la cabeza. Ofreció. Preparó su carga, miró adelante y atrás y no vio a nadie. Dijo: 'Esta carga ahora es la carga de Dios', y le pidió al viento que le ayudara a subirla. 'Los que no tienen a nadie confían en Dios.'", "Olóyàn y el ñame machacado. Olóyàn Gìdìgbí, en la fiesta de su Ifá, preparaba ñame machacado en cantidad y todos iban a comer a su casa; era generoso. Al terminar, rezaban por él: 'Que te vaya bien, que tengas vida larga'. Y le llegaron los regalos de riqueza, pareja, hijos y casa.", "Ọ̀rúnmìlà y la carne de òyà. Las cosas buenas no querían entrar a la casa de Ọ̀rúnmìlà. Le dijeron que todas entrarían si ofrecía carne de òyà, la rata grande del pasto. La ofreció a su Ifá y las fortunas empezaron a volver."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El forastero: una gallina, 3,200 cauríes y medicina de Ifá.", "Mucho ñame machacado para la gente en la fiesta de Ifá.", "Carne de òyà para Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè ayuda al que está solo. Ifá recibe el ñame y la carne de òyà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de olúṣesájú (Petiveria alliacea) en agua con jabón, para baño. Ñame machacado, carne de òyà (rata grande)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 164.1 (yorùbá): Anikansùn, biobasun si aburadi; / Ọlörun nikan nii jii loju oorun: / a daa fún Ajèji / tiolo si ẹluju lọ i duro, / kiobaa leri eni ba òun gbẹ'rù de orí; / wọ̀n niki o rú: / Adiyẹ, ẹgberin-dilógún owó ati ewé Ifá / ọ̀ gbó ó rú. / Ajèji de inú elùjù, / o di erù ka'lẹ, / o wo iwájú kori ẹnikan, / o wo èhin kori enikan. / Ó ni: / Erù yi ma di erù Ọlorun o. / Njẹ Efufulẹlẹ bami gbe erù yi d'ori, / Efufulẹle. / Eyin ko mọ pe: / Eniti ko ni ara, / Ọlorun ni agbojule olúwarẹ?", "REZO: OSA RETE MAFEREFUN ODDUN, OZAIN, ORUN, OLOKUN OSA RETE SIARETE EGGUN BABA PARADO AFEFE IKU ORUN OMOSABI BESHE AFEFE BABA TIMBAYE YE OLOKUN AFEFE LORUN OMA YIBE EGGUN MAYEBE OUMBO ESHISHI INLE MAFUN AWA AWE MAFUN BABA IGI MAFUN MAWA AGBONA BAILORUN EGUN BAILORUN.", "REZO: OSA RETE NIFA INLE OKU FEKUN OSA RETE OLEKUN BABA OLOFIN INLE OKU FOKUN AWO NILAYE AYEGOGO INLE OKU FEKUN DUDU INLE OKU FEKUN OSA RETE PUPUA INLE EWANI IRE OLOFIN IBA IKA ARAN OMI IRE INLE OLU FEKUN OTA IRE.", "REZO: ODIDE AGORONI AYE OKIKIO OTA EYO, EKUTE BOGONI AKERE INTORI EYO LODAFUH ORUMILA.", "REZO: MATARE FUN ODDUN OZAIN ORUN OLOKUN EGGUN BABA PARADO AFEFE IKU ORUN OMO SABI BASHE AFEFE BA TIBAYE YE OLOKUN AFEFE LORUN OMO YIBE OZAIN OMO YIBE EGGUN MAYEBE OWUNKO ESRIBI INLE MEFUN AWA AWENE FUN BABA IGUI MOFUN RAWA AGBONA BAI LORUN EGGUN BAI LORUN."]}]$q$::jsonb),
(165,'55cabae5c3457d18655339b7d42d2ae9',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Ọ̀ṣẹ́ advierte contra las acusaciones falsas. La persona puede tener cambios repentinos en su trabajo. Sus cosas no se echarán a perder. Si tres personas hacen negocio juntas, deben ofrendar juntas. Si es una mujer, no debe dejar a su esposo actual para no desordenar su vida."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay un cambio repentino en el trabajo.", "Sospecha de alguien y podría culparlo sin pruebas (relato de Owa y el inocente).", "Varias personas tratan de colaborar para obtener un beneficio (relato de Olúigbó y Olúodàn)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que todas las bendiciones estén en sus manos.", "Palabra con autoridad, como la riqueza, el rey e Ifá.", "Ganancias en un negocio de tres."]}, {"titulo": "Ibi y advertencias", "puntos": ["Acusar a un inocente o ser acusado falsamente.", "Cambios bruscos en el trabajo.", "Una mujer que va de un esposo a otro y causa pleitos."]}, {"titulo": "Enseñanza principal", "texto": "El hijo sigue el modelo de su padre. Cuando habla la riqueza, cuando habla el rey y cuando habla Ifá, los demás se callan: los tres ofrendaron al venir del cielo, y su palabra tiene autoridad."}, {"titulo": "Relatos reunidos", "puntos": ["El rey del bosque y el rey de la sabana. 'El hijo sigue el modelo de su padre.' A los dos les pidieron una chiva, y solo el del bosque ofreció. Le dijeron que todas las bendiciones estarían en sus manos y la gente se las pediría.", "Ọwá y el inocente. 'Aquel que pensamos que nos ofendió no nos ofendió.' Ọwá miraba a alguien como ladrón y era inocente. Le pidieron dos palomas, una cazuela de ñame asado machacado y 4,400 cauríes para que Èṣù no lo empujara a acusar a un inocente.", "La riqueza, el rey e Ifá. Los tres venían juntos del cielo a la tierra y ofrendaron para que nadie pudiera cambiar lo que dijeran. En la tierra, cuando hay un asunto, preguntan '¿y el dinero?', y al verlo todos se callan; cuando habla el rey, nadie lo contradice; cuando habla Ifá, los que lo imitan se quedan mudos.", "Ère, hija del Òrìṣà. Ère, hija de Òòṣà Ọ̀wújìn, era una mujer madura. Le pidieron al Òrìṣà ofrendar por ella para que los hombres no pelearan a causa suya. No ofreció. Ère se casó con Omú, hijo de Ikúho, y lo dejó; se casó con Ààsà, hijo de Mòkítì, y lo dejó; luego se casó con Líìlí, hijo del rey de Ọ̀yọ́. Los dos primeros, que eran amigos de Líìlí, dijeron que esa mujer los iba a enemistar y le hicieron la guerra. El Òrìṣà fue con Ọ̀rúnmìlà, que le dijo: 'Tú no ofrendaste cuando llegó tu hija'. Los tres respondieron: 'Nunca dijimos que la mataríamos; es el Òrìṣà el que no ofrendó'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El rey del bosque: una chiva.", "Ọwá: dos palomas, una cazuela de ñame asado machacado y 4,400 cauríes.", "Para un negocio de tres: la ofrenda hecha entre los tres."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù puede empujar a acusar a un inocente. Òòṣà Ọ̀wújìn debía ofrendar por su hija."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Chiva, palomas, ñame asado machacado."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 165.1 (yorùbá): Ọ̀sá-Ṣé, orin-ṣẹ. / Asa ti baba omọ ṣẹ li ọmọ i hun: / li o dífá fún Olúigbó, / a bu fún Olúodàn. / Wọ̀n niki àwọn mejeji / lo fi ewúrẹ rúbo. / Oluigbó li o rú. / Wọ̀n ni: / Gbogbo ire lo maa pe si qwọ̀ rẹ̀ / tii wọn maa maa wa gbàá.", "REZO: OSA SHE ORISHELI LODAFUN SHELE LODAFUN OSA INTORI OBONI IWA IRE OMO.", "REZO: OSA SHE ORISHE ADIFAFUN SHELE LODAFUN ASHE FORI TIO NI LARI, EYELE LEBO. ADIFAFUN YEMAYA.", "REZO: OSA SHE IFA NI ORISHA MOSAFUN SHELE MOBASHE SOKO ADIFAFUN BARABANIREGUN, EYELE MENI ELEBO.", "REZO: OSA SHE ONI SHE NI LODAFUN SHELE LORDAFUN OKO ADIFAFUN OBATALA LODAFUN ELEGBA, SHANGO ATI OBINI. MAFEREFUN EYELE.", "REZO: ADIFAFUN EYITE IYA INLE OGUERE, AFOKOYERI, ASHIKUELU LAWAU IYA BERE EGGUN OJOMBELE AKAKU OUMBOWA NI OMOBIRIN OKE IYA OSHA NI OKU ERE ARARA BIOSE BURUKU ASHIKUELU ORUN BAWAO IKU OLELE NI EGGUN IMALE BURUKU LODE IYA INLE OGUERE KAFEREFUN EGGUN.", "REZO: OSA SHE INLE OYIYI INTORI AWANI WAWA ADIFAFUN AWO ASHELE BELE MOBASHE SOKUN OYIYI ADIFAFUN BARABAN NIREGUN ORISHA OSHAFERI TORI ONISHE OYIYI OKE OKUNI AWO YOMELE KAFEREFUN OBATALA."]}]$q$::jsonb),
(166,'25b36d215feb4d7381e142d14708e019',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Òfún pide entender qué es un tabú (èèwọ̀) y que la persona conozca los suyos, para respetar solo los que le corresponden. Hay caos en sus actividades diarias y eso le altera el juicio. Su hijo puede tener una conversación con alguien importante; hay que ofrendar antes para que no cometa errores."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está confundido con sus actividades diarias y eso le nubla el juicio.", "Quiere escapar de un problema que tiene que enfrentar (relato de Ọ̀rúnmìlà sobre por qué huye la gente).", "Debe cuidar a un hijo frente a alguien con más poder.", "Necesita saber qué prohibición le corresponde."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vida larga para los que conocen sus tabúes.", "Ganar una discusión con alguien poderoso.", "Ropa nueva y vida grata hasta el final."]}, {"titulo": "Ibi y advertencias", "puntos": ["Querer huir de todo y no vivir.", "Desorden diario que nubla el juicio.", "Negarse a ofrecer algo nuevo y vestir harapos toda la vida."]}, {"titulo": "Enseñanza principal", "texto": "El que huye de todo en la tierra no tiene placer ni vive mucho: hay que saber de qué huir. Eso es el èèwọ̀, el tabú de cada quien."}, {"titulo": "Relatos reunidos", "puntos": ["De qué hay que huir. 'Huimos de la serpiente porque muerde, del elefante porque aplasta, del búfalo porque embiste, del fuego porque quema, de las deudas porque nos ridiculizan, de lo ajeno para que no nos llamen ladrones, del amuleto que cuida los mercados para que su maldición no nos alcance.' Pero el que dice que huirá de todo no tiene placer ni vive mucho. A los seres humanos les pidieron ofrendar para saber de qué huir: dieciséis caracoles, hojas de ọmọ̀, aceite de palma, sal y 3,200 cauríes. Los que ofrecieron viven largo tiempo.", "Ònjìyàn y el hijo de la Muerte. Àlé, hijo de la Muerte, dijo que al día siguiente aparecería la luna nueva. Ònjìyàn, hijo de Ọ̀rúnmìlà, que a todo le encontraba falta, le contradijo: no aparecería. La gente se asustó, porque si perdía, el hijo de la Muerte lo mataría. Ònjìyàn se lo contó a su padre, consultaron y salió Ọ̀sá Òfún. Le pidieron a Ọ̀rúnmìlà ẹ̀gbo blanco, papilla de maíz blanco, y ponerlo en un cruce de caminos para Èṣù. Lo hizo por la tarde, y Èṣù puso una cortina sobre la luna nueva, como lo hace hasta hoy. La luna no apareció, y Ònjìyàn ganó.", "Wósòwósò y Yórìíyórìí. A los dos les pidieron ofrecer ropa nueva. Yórìíyórìí ofreció una tela nueva; Wósòwósò ofreció los trapos que llevaba y dijo que no podía dar ropa nueva. Èṣù le pegó los trapos al cuerpo, y por eso hasta hoy anda en harapos, mientras Yórìíyórìí siempre estrena ropa."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Dieciséis caracoles, hojas de ọmọ̀, aceite de palma, sal y 3,200 cauríes.", "Por el hijo: ẹ̀gbo blanco (papilla de maíz blanco) en un cruce de caminos para Èṣù.", "Ropa nueva como ofrenda; si son dos, los dos."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù cubre la luna nueva y viste o desviste a quien ofrenda. Ikú, la Muerte, tiene un hijo que discute con el de Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de ọmọ̀ (Cordia millenii), sal, aceite de palma, ẹ̀gbo blanco (maíz blanco), tela nueva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 166.1 (yorùbá): Ọ̀rúnmìlà I: Ọ̀sá-Fú, / Emi i: Ọ̀sá-Fú. / A nṣa fun Ejo / ki ejò ma baa bu'nijẹ, / A nsa fún erin / ki erin ma baa muni. / A nsa fun efon / ki efòn ma le ba'nijà. / A nsa fún iná / ki iná ma le jo'ni. / A nsa fún igbèsè / ki ọmọ aráyé mabaa fi'niṣe Ẹlẹyà. / A nsa fún ohun-olohun / kiama baa di ole, / nijokan airotẹlẹ / kiama baa pariwo le'ni. / A nsa fún Aale / ki orọ buburu Aale ma baa mu'ni. / Àwọn tiowa ti nwipe àwọn / kiisa fún ohunkohun ninu ayé, / Adùn kosi fún wọn, ajẹpẹ ayé kosi. / A daa fún àwọn Eniyàn, / wọ̀n niki awọn Eniyàn wa rúbọ / kiwon le maa mọ ohun / ti aisa fún ti a npe ni Eèwọ̀. / Ẹbọ: İgbín mẹrindilógún, ewé mọ̀, epo, iyọ / ati egbàá mẹrindilógún owó. / 210 igbèsé: s. deuda; onígbèsé: deudor. / 2\"1 Eléyà: burla, mofa, ridículo, desprecio. / Apakan wọn li o rúbọ. / Wọ̀n ni: / Evin ti ẹ rúbọ a pẹ ninu ayé, / ayê a maa dùn fún yin.", "REZO: OSA FUN OBRO YIGUIMORO ERO OLOFIN YEYE ORDUO ERU OLOFIN TETEBERU OMO OLOYA EYI ELE OMO OLOFIN KUKURU OYI ILE AKUKO META ELEBO.", "REZO: OSA FUN ADIFAFUN ALA GUODUN GUO LOPURE OMA OBATALA LORDO; AYA LORU OWO IDA KUDA AWO ISE KUTE ADIFAFUN OBATALA ASHE LEBO UMBATINLO YOLU AYE OMA NUTIEKA EYELE,OÑI IRO LOMPA OMEO.", "REZO: OSA FUN MARIWO YUYETE AWO ORUN ADIFAFUN OLUGOÑI ADIFAFUN OSHANLA EYELE LEBO GUOLA ULOMA ABATAMA PEONATI OSALO FUN OSA FUN ADIFAFUN ELEGBA FUN UMBATILO PULOMA LODO AYALORUN.", "REZO: MARIGUA TULLELE AWO ORUN ADIFAFUN OLOGOÑI ADIFAFUN OSHANLA EYELE LEBO GUOLO ULOMA ABATANA PEONATI OSALO FUN OSA FUN ADIFAFUN ELEGUE DUM UMBATINLO PULONA LODO ALLORUN.", "REZO: OBRO YIGUIMORO EO OLOFIN YEYE ODUDUWA ERU OLOFIN TETE BORU OMO OLOYA EYO ILE OMO OLOFIN KUKURU OYI ILE AKUKO META OWO LA META.", "REZO: OSA FUN ADIFAFUN ALA GUODUN GUO LO PURE OMA OBATALA LORDO ALLA LORU AWO NIDA CUDA AWO NITE KUTE ADIFAFUN OBATALA ACHEREBO UMBATINLO YOLU ALLE COMA MUTIECA EYELE OÑI HIRO LOMPA OMEO.", "REZO: OMO KORIO UNSURO BASADE EMIUI OKO BINI YOWO OWE OGUEDE ISHE OZAIN A ILU OBINI ERU OBORU OPOLOPO OBINI YAL LODAFUN ISHE OZAIN KAFEREFUN ORUNMILA", "+++"]}]$q$::jsonb),
(167,'36db2e44322160a08bb3830bbea736c2',$q$[{"titulo": "Idea central", "texto": "Ìká Ogbè habla de defender los propios derechos y exigir respeto, pero con palabras y actos suaves: la rudeza estropea la razón. Anuncia ascenso a un trono, protege a una mujer embarazada a la que los enemigos le niegan el parto y trae hijos y riqueza a quien llora por descendencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita explicar su postura sin ser grosero.", "Siente que no lo respetan.", "Desea hijos y recursos (relato de Adeiloye).", "Puede llegar un cargo importante; si hay embarazo, le preocupa el parto."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ascender a una posición alta, al trono.", "Parto sin peligro, incluso de gemelos.", "Hijos y riqueza después de mucho esperar.", "Que sus cosas no se desordenen aunque haya enemigos alrededor."]}, {"titulo": "Ibi y advertencias", "puntos": ["La grosería, la impertinencia y la falta de tacto al exponer las propias razones.", "Gente que habla mal y desea que el embarazo no llegue a término.", "Enemigos que planean arruinar sus cosas."]}, {"titulo": "Enseñanza principal", "texto": "Nadie puede envolver ropa seca sobre el fuego ni usar una serpiente como cinturón: hay cosas que no se hacen. Se exige respeto sin faltar al respeto. La maldad recibe el pago de la maldad, y al que no la practica le toca el trono."}, {"titulo": "Relatos reunidos", "puntos": ["La hiena y los gemelos. La hiena estaba pesada con un embarazo de gemelos y había quienes deseaban que no llegara a parir. Preguntó si tendría a sus hijos en la tierra. Le aseguraron que no habría problema si ofrecía, y ofreció. Dio a luz sin peligro a la placenta y a los bebés, y cantó contenta que había parido como el árbol àfòn, que se viste a la vez de hojas secas y de hojas vivas. Por eso se dice: si la maldad no me gana, subiré al trono del rey de Ìlá; el dios de la maldad le paga al malvado.", "Ọ̀rúnmìlà dispara al bosque sagrado. Ọ̀rúnmìlà estaba en medio de enemigos que apuntaban a él a propósito, decididos a estropear sus cosas. Le pidieron ofrendar y le aseguraron que no podrían arruinarlo. Cumplió y ganó. Por eso este Odù dice: quien mira de frente al bosque sagrado y dispara su flecha, si ha de pegarle a una mascarada, que le pegue; si ha de pegarle a un Òrìṣà, que le pegue; pero el que apunta a Ọ̀rúnmìlà no da en el blanco.", "El hijo del jefe del mercado. Uno dijo grosería y el otro dijo impertinencia. Uno dijo que no se puede envolver ropa seca encima del fuego, y el otro que no se puede usar una serpiente como cinturón. Nadie puede ser tan grosero como para golpear en la cabeza al hijo del jefe del mercado. Con este rezo se pide que todos respeten y quieran al consultante.", "Adeiloye y los hijos que la siguen. Adeiloye lloraba porque no tenía descendencia. El adivino del interior del bosque le marcó dos carneros y dinero. Cumplió, se volvió muy rica y tuvo hijos, y cantaba: miren todos esos hijos que vienen detrás de mí, y muchos más."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el parto: la ofrenda que marque Ifá; la mujer embarazada debe ofrecer bien.", "Contra los enemigos: la ofrenda marcada y regalos a Èṣù.", "Para el respeto: polvo iyẹ̀ ìròsùn marcado con Ìká Ogbè, rezado con el verso y frotado en la cabeza.", "Para hijos y riqueza: dos carneros y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù recibe su parte para que la ofrenda llegue. Ọ̀rúnmìlà vence a los enemigos que apuntan contra él. El rey de Ìlá y su trono."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Iyẹ̀ ìròsùn, árbol àfòn, carneros."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 167.1 (yorùbá): 1 afojudi, / Mi afagbadi, / 1 wọ̀n kiifojudi'ná kiwọn fim'aṣo ka, / Mi wọ̀n kiifi ojud'ejo ki wọn fiṣ'ojagba, / wọ̀n kii f'ojudi omo Ọlojà / ki wọn kan ni iko atarí. / Ki wọn bu qwọ / ati bẹẹbẹẹ fun mi loni.", "Verso 167.2 (yorùbá): Orirotẹerẹ awo inú igbó: / li o difá f'Adeiloye / ti nsokun airibi, / ti nsokun àiripon. / Agbo Méjì / ati egbàá méjilèlógún owo / tabi okẹ mẹfà owó li ebọ. / Ó gbọ̀ ó rú. / Ó la'wo, Ó la'mọ. / Orin: / Deiloye, d'opagun / E w'omo yọyọ lehin mi a / E w'omo yoyọ ati beẹbẹẹ.", "REZO: BABA ADELE BABA FOWO NI EMITE MABINU BABA ADELE BABA FAYANI. EMITE BABINU BABA ADELE BABA FOWAO VI EMI LELEL MABINU IRE BOGBO TEE EBA FEE NI LAYE ENITU MABINU.", "REZO: BABA ADELE BABA FOWO NI EMITE MABINU BABA ADELE BABA FAYANI. EMITE BABINU BABA ADELE BABA FOWAO VI EMI LELEL MABINU IRE BOGBO TEE EBA FEE NI LAYE ENITU MABINU.", "REZO: IKA OBA LA CACHE ARO CHICHA COTO BECA AWO NIOBEINTOCHE ABARA AKUKO LEBO.", "REZO: OKA LOGUE IKA ARO GUEMI IFA QUERE ORDAFUN ASHE OMO OLIKA MONI OKUA ARAYA ORUO ESHU OWUNKO QUELE IEBAN OFO METETA OWO LA MEFA.", "REZO: IKA BEMI AWO ENI IFA AYANIALU LOYE ELEGUA AWANI LOYE EGGUN ONI LOYE EWE LANI, AYE EGGUN OMO AYALA UN LOYE ORI WAYENIFA AWO BANICHE AWANI LORUN ELEGBA TORI BAWA ORUNMILA BANI OBATALA JEKUA EGGUN AWANILORUN FILEKUN WEWE LEKUN OBANI TINSHE OTI BABA OBASHE EGGUN ORUN BAYE.", "REZO: IKA BEMI AWO OGBOCHIYI OMO NI SHANGO OMO NI IFA ALUGUE AWO SHONILE BEIYEKU IKI NIWE MOWANILE INLE ELEGUARA, ESHU OGDARA AWO TONIYI AWO ELEGUARA MOKUE OBI UNYEN, OUNKO TINWE OLUO POPO OTA NI ELEGUARA META NI LAYE ESHU AWO BOYEY IKU OSHUN OÑI ESHUN MALOWALODE IKA BEMI AWATOGBA YEYE MAYALOLO ABAWATUMO IKA BEMI FITILA EWE SI OWOSI OLUO POPO OGBALU AYE.", "REZO: IKA BEMI AWO ENI IFA AYANIALU LOYE ELEGUA AWANI LOYE EGGUN ONI LOYE EWE LANI, AYE EGGUN OMO AYALA UN LOYE ORI WAYENIFA AWO BANICHE AWANI LORUN ELEGUA TORI BAWA ORUNMILA BANI OBATALA JEKUA EGGUN AWANI LORUN FILEKUN WEWE LEKUN OBANI TINSHE OTI BABA OBASHE EGGUN ORUN BAYE.", "REZO: IKA BEMI AWO OGBOCHIYI OMO NI SHANGO OMO NI IFA ALUGUE AWO SHONILE BEIYEKU IKI NIWE MOWANILE INLE ELEGUARA, ESHU OGDARA AWO TONIYI AWO ELEGUARA MOKUE OBI UNYEN, OUNKO TINWE OLUO POPO OTA NI ELEGUARA META NI LAYE ESHU AWO BOYEY IKU OSHUN OÑI ESHUN MALOWALODE IKA BEMI AWATOGBA YEYE MAYALOLO ABAWATUMO IKA BEMI FITILA EWE SI OWOSI OLUO POPO OGBALU AYE.", "REZO: IKA BEMI OMI GBOGBO KOANLA BEMI OMI GBOGBO IKA BEMI ONIGBO KIWASA OMIGBO IKALA OLUWO OMI AKAN AKURE OMODE APARO UMBEMI OFI KOKO EGUN LOWARE LODAFUN OGGUN KOKO MAFEREFUN ORUNMILA.", "REZO: IKA BEMI ADIFAFUN BEDU MACHU GBODO AYIDA WEDO OSHOSI ODEMATA KAFEREFUN JUERO LODAFUN ORUNMILA."]}]$q$::jsonb),
(168,'76b3295a25b3ad66b62ec3fb00045f89',$q$[{"titulo": "Idea central", "texto": "Ìká Ọ̀yẹ̀kú trata la esterilidad del hombre y el regreso de la pareja que se fue. Pide recuperar el carácter, el valor y la firmeza propios: quien vive huyendo de los golpes termina despreciado. Promete vida larga, espacio y tiempo para hacer las cosas, y victoria en la casa del que manda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una relación se enfrió o terminó (relato de Onimeri-apala).", "Sufre por no tener hijos.", "Evita los pleitos por miedo y se pregunta cómo defender su dignidad (relato de la cobra y Aiká)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que regrese la relación que terminó o se enfrió.", "Fecundidad para el hombre; hijos con la pareja.", "Valor para defenderse y ser respetado.", "Vida larga, logros, y tiempo y espacio para sus asuntos.", "Ayudar a un superior a ganar sus guerras."]}, {"titulo": "Ibi y advertencias", "puntos": ["Esterilidad y abandono de la pareja.", "Burla por falta de coraje; huir siempre de la pelea.", "Hacer solo la mitad de la ofrenda."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se ofrenda a medias protege a medias. El que entrega su cuchillo a Ifá recibe con qué defenderse; el que se guarda la parte que le toca sufre más tiempo antes de ver el alivio."}, {"titulo": "Relatos reunidos", "puntos": ["Onímẹri y sus mujeres. Onímẹri àpàlà no podía tener hijos y todas sus mujeres lo dejaron solo. Le pidieron dieciséis gallinas, dieciséis palomas, dieciséis caracoles, un hormiguero de hormigas àládìn y las hojas para preparar una medicina de Ifá. Cumplió y se bañó con esa medicina. No quedó una sola mujer suya que no saliera embarazada y diera a luz. Las que lo habían abandonado oyeron la noticia, volvieron a su casa y también tuvieron hijos con él.", "La cobra, el pangolín y el cuchillo. La cobra y el pangolín (àkàká) eran objeto de burla porque no tenían valor: si los retaban, huían; si los amenazaban, se enrollaban sobre sí mismos hasta que pasaba el peligro. Cansados de esa vida, consultaron. Les marcaron una flecha, un cuchillo, una piedra de rayo, un gallo, pimienta de Guinea y dinero. La cobra ofreció, aunque se guardó la flecha; el pangolín no ofreció. Un día, en una pelea, alguien agarró a la cobra para golpearla como de costumbre. Èṣù le recordó a la cobra el cuchillo que había ofrecido, y la cobra atacó: dos cayeron al suelo y los demás huyeron. El pangolín, después de sufrir mucho, volvió y ofreció una parte; su cuerpo se cubrió de escamas duras y ya nadie pudo hacerle daño.", "Olóta Ìkayèkú. Olóta Ìkayèkú venía del cielo a la tierra y preguntó cómo vivir mucho y lograr lo que se proponía. Le pidieron ofrendar y cumplió. Vivió largo, logró sus cosas y alabó a sus sacerdotes.", "Ìká y las tres flechas en casa de Olófin. Ìká llegó a la casa de Olófin cuando todas las guerras se habían levantado contra él. Antes había ofrendado, y le pidió a Olófin que ofreciera tres flechas. Olófin las ofreció y ganó todas sus guerras. Por eso se canta que fue Ìká quien disparó las tres flechas en la casa de Olófin, en la casa de Akíoró."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para que vuelva la pareja y lleguen hijos: dieciséis gallinas, dieciséis palomas, dieciséis caracoles, hormiguero de àládìn y hojas para medicina.", "Medicina: jabón molido con hormigas àládìn, parte de su hormiguero y hojas ojúùsájú, ṣawerepepe y oriji, puesto en una calabaza con tapa nueva, con sangre de una gallina. Se usa para bañarse.", "Para el valor: flecha, cuchillo, piedra de rayo, gallo, pimienta de Guinea y dinero.", "Medicina del valor: sopa con limaduras de hierro y pimienta de Guinea molidas, a la que se le mete la piedra de rayo calentada al rojo, cubierta con hojas de ñame; la bebe el consultante.", "Para ganar guerras: tres flechas."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù recuerda a la cobra la fuerza que ofreció. Olófin gana gracias a Ìká. Ifá devuelve a las mujeres a la casa de Onímẹri."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ojúùsájú (Petiveria alliacea), ṣawerepepe (Cyathula prostrata), oriji, hojas de ñame, pimienta de Guinea, hormigas àládìn y su hormiguero, limaduras de hierro, piedra de rayo, jabón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 168.1 (yorùbá): Akuṣaba-lyanda awo Onimeri-apala / li o dífá f'Onimẹri-apala, / nigbati oun mi rin-rin ágàn, / nigbi ojilelegbeje obirin / lọ titi o kù okanṣosọ. / A niki ó rú: / adiyẹ mẹrindilógún, eyẹlé mẹrindilógún, / igbin mẹrindilógún, ilé aladin ati ewé Ifá. / Ki gbogbo àwọ̀n obirin rẹ / tiotilo le pada bowa sodo rẹ. / Kiwọ̀n maa loyun. / Ki wọn maa bimọ. / Ó gbọ̀ ó rú. / Wọ̀n ṣe ewé Ifá / ti a wi loke fún un kio maa fiwẹ. / Laipẹ obirin kan tiowa pẹlu rẹ loyun, / o bimo. / Awọn ti o ti lọ si tun padawa sile Onimẹri / nigbati wọn gbọ iro rere yi. / Awọn naa loyun wọn si tun nbimọ nibẹ.", "Verso 168.2 (yorùbá): Arisa-iná, Akotagiri-ejò, / a dífá f'Ẹjò-óká, / a bu fun Aiká / nigbi àwọn pmo aráyé / nfi wọn ṣe elẹya nitori iwà-ojo, / bi a pe wọn n'ijà wọn a sa / nitoripe ki wọn ma baa tẹ. / Ki wọn ma baa fi ara pa / ati ki wọn ma baa kú. / Bi àwọn ọmọ aráyé ba mu ijà tọ wọn wa / tabi ikú ni ntọ wọn bọ. / Wọn a kako gbingbi. / Bayi ni wọn nyẹ̀ ijà ayé silẹ ati ikú. / Nipa lwà yi, wọn di eni yeperẹ lowọ ayé. / A ngoe wọn ṣanlẹ a nfi wọn ṣere pwọ̀. / O pẹ titi, ara ta wọn. / Iru ipo bẹẹ̀ ko tẹ wọn lorun mọ. / Wọ̀n pe Babalawo kio waye wọn wo. / Àwọn Babaláwo ni: / biẹbawipe ki ẹ niyi ninu ayé, / afibi ẹ ba rúbọ ki a ṣe ewé Ifa fún yin. / Wọn ni kili ebọ? / Awọn Babaláwo niki wọn rú: / Ofa, obe, ẹdùn-ààrá, / akuko-adiyẹ, ataare, / egbàá mejila owó / ati ewé Ifá. / Qká nikanṣoṣo li o rúbọ ninu wọn. / Sùgbọ̀n ko rú ofa pẹlu. / O wa di ijọ kan tiodi pràn ijà pẹlu / àwọn èniyàn diẹ. / 'nikan ninu wọn gbe Ọ̀ká / lati fi ṣanlẹ bi igba atijo. / Bi o ti diimu, / Eṣú ni nitori kinni o ṣe rúbo obe. / Biobatigbe ọ ṣanlẹ tabi o fi owó kan / ọ ni iru kiomaa ṣa wọn l'abẹ tioti rú. / Ọ̀ká si nṣa wọn. / Biotiṣa eni Méjì ninu wọn / ti wọn ṣubulu lẹ / ni àwọn iyokun ninu wọn ti salo. / Aiká, nigbati iya ko yee jeẹ, / wa rúbọ nikẹhin. / Diẹ ni ebọ ti ó rú / O fi apandi ati bẹẹbẹẹ ṣebo. / Ipẹ wa sujade li ara rẹ. / Ko ya lati da owó iya teẹ / mọ bi igba atẹhinwa. / Ifárapa ko si fún Aika mọ.", "REZO: IKA BIKU IYELERETE KOLEYURE YERU WARA AKUMARA AYE ADIFAFUN OYEKA, ADIFAFUN IKA IKABORUGBO EYEDA AWADO KUKUTO KUKU ADIFAFUN OYEKU UMBATI LOMBA OLOTODE KASHU, OWUNKO LEBO, EKRU, OTA LEBO.", "REZO: IKA BIKU IYELERETE KOLEYURE YERU WARA AKUMARA AYE ADIFAFUN OYEKA, ADIFAFUN IKA IKABORUGBO EYEDA AWADO KUKUTO KUKU ADIFAFUN OYEKU UMBATI LOMBA OLOTODE KASHU, OWUNKO LEBO, EKRU, OTA LEBO.", "REZO: IKA YEKUN IFA ETUTU AWO ABURE UMBO OKUA OKO AWO ADIAFUN AJURE KAFEREFUN ORUMILA.", "REZO: IKA YEKUN YERUPON YERUTETE OGBARI BAYE OGBA ORICEKE OYEKUN IKA IKA YEKUN YERUPON YERUTETE AWA NI IFA OGBA ORI LAYE OMO ORISHAOKO WEWE WERILAYE SHANGO IFA INLE BAYEKUN OMAYEKUN INLE OGBANIRE AWO MATA AWO OGBA OGBANI IKU OMO IFA MOYALE MOYARA IRE AWAREYENI LAYE AWO MELLI IFA. IFA KAFEREFUN ORICHAOCO, IFA KAFEREFUN SHANGO ARA ONU OGBAYI LEYE BERI BAYE OYEKUN MAYEWE NI LAYE OGBARI LAYE OYEKUN AWO LARE IFA LERI BARE OGBAYEGBE LERI IKU OGBA LERI.", "REZO: IKA YEKUN IRIYI ARAYA ADIAFUN AWO ARARA AKITI KUO KO AWO ONA OKA KAYABO.", "REZO: IYELERETE KOLERUYE YERU GUARA ACUMARA AYE ADIFAFUN OYEKUN ADIFAFUN IBA IKABO AYEBA AWADO.", "REZO: KUKU ADIFAFUN KOYEKU UMBATE OLOTIDE CACHE AUCO LEBO EKRU OTA LEBETA.", "REZO: IKA YEKU IFA ABERE JALLU OINABEBERO OKO ADIFAFUN ORUNMILA UN LOTA ADEIFE OBE.", "SUYERE: IKU YERE IKU YERE, MANKIO EYE MAUKIO EYE MANKIO EWE EYE MANKIO, IKU ODDARA.", "REZO: IKA YEKUN YERUPON YERUTETE OGBARI BAYE OGBA ORICEKE OYEKUN IKA IKA YEKUN YERUPON YERUTETE AWA NI IFA OGBA ORI LAYE OMO ORISHAOKO WEWE WERILAYE SHANGO IFA INLE BAYEKUN OMAYEKUN INLE OGBANIRE AWO MATA AWO OGBA OGBANI IKU OMO IFA MOYALE MOYARA IRE AWAREYENI LAYE AWO MELLI IFA. IFA KAFEREFUN ORICHAOCO, IFA KAFEREFUN SHANGO ARA ONU OGBAYI LEYE BERI BAYE OYEKUN MAYEWE NI LAYE OGBARI LAYE OYEKUN AWO LARE IFA LERI BARE OGBAYEGBE LERI IKU OGBA LERI.", "REZO: IKA YEKUN IRIYI ARAYA ADIAFUN AWO ARARA AKITI KUO KO AWO ONA OKA KAYABO.", "SUYERE: IKU YERE IKU YERE, MANKIO EYE MAUKIO EYE MANKIO EWE EYE MANKIO, IKU ODDARA."]}]$q$::jsonb),
(169,'7df2cf757f7b9afaf285ad4fe2fb80ff',$q$[{"titulo": "Idea central", "texto": "Ìká Ìwòrì advierte que el rencor y el daño a otros se vuelven contra quien los hace, y que el mal carácter tiene bloqueado el camino del consultante. Habla también de proteger la casa de una enfermedad contagiosa cuando hay un enfermo grave. Pide ofrenda por los hijos y que tres personas ofrenden juntas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Alguien con rencor está bloqueando una relación o un proyecto (relato de Inükogun).", "Hay un enfermo en la familia y teme por los demás; conviene la atención médica (relato de Ìká).", "Debe separar el pleito moral del asunto de salud.", "Puede venir una mejoría (relato de Oníbàyì dúdú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza, pareja e hijos después de ofrendar.", "Que todo lo que nunca salió bien empiece a salir bien.", "Que la enfermedad de uno no alcance a los demás de la casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Planear un mal contra alguien: el daño regresa.", "Enojo e irritación que cierran el propio camino.", "Contagio dentro de la casa.", "Negarse a ofrendar por soberbia y quedar despojado cada año."]}, {"titulo": "Enseñanza principal", "texto": "El que esparce ceniza termina cubierto de ceniza: el malvado se destruye con sus propias fechorías. Lo que hoy se niega a Ifá, mañana se lo quitan a uno por la fuerza y cada año."}, {"titulo": "Relatos reunidos", "puntos": ["Oníbàyì dúdú y los hijos. Oníbàyì dúdú, de la familia que sacrifica una chiva a sus antepasados para tener hijos, fue a consultar porque nada le salía bien. Le dijeron que desde ese momento todo iría mejor si ofrecía. Cumplió, dio su parte a Èṣù, y le llegó la riqueza, tuvo esposas y tuvo hijos. Cantaba que había traído a casa las buenas fortunas en multitud.", "Apá, Ìrókò y la palma. Apá, Ìrókò y la palma del monte eran tres árboles que venían del cielo a la tierra. A los tres les pidieron ofrecer su tela. Apá se burló: ¿por qué iba a dar su tela? Le advirtieron que quien no ofreciera su tela andaría sin ropa. Ìrókò dijo lo mismo que Apá. La palma se quitó su tela y la ofreció. Pasó el tiempo, y cada año el hombre llega con su cuchillo y les raspa la corteza a Apá y a Ìrókò para hacer medicinas, y los deja desnudos; lo mismo les pasa a los demás árboles del monte. Solo la palma no se marchita y nadie le raspa la corteza. Si tres personas reciben este Odù, deben buscarse y ofrendar juntas para no tener un problema común.", "Inúkogun, que pensaba hacer daño. Inúkogun estaba planeando un mal contra otro. Los adivinos le advirtieron que todo lo malo que hiciera caería sobre él, y le marcaron dos palomas, dinero y medicina de Ifá para que la maldad no se asentara en su corazón.", "Ìká y el enfermo de la casa. Ìká cuidaba en su casa a un enfermo crónico que de seguro iba a morir. Le pidieron ofrecer una chiva, una gallina, aguardiente y medicina de Ifá para que la enfermedad no pasara a nadie más de la casa. Así se protege a la familia cuando hay un enfermo grave; conviene además ir al médico para saber cómo cuidarse del contagio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para hijos y riqueza: la ofrenda marcada y regalos a Èṣù.", "Tres personas que ofrecen juntas una tela.", "Contra el mal propio: dos palomas, dinero y medicina de Ifá.", "Contra el contagio: chiva, gallina, aguardiente y medicina de Ifá.", "Medicina: hojas de cebolla molidas con aceite de palma hasta hacer una crema para frotar el cuerpo."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù recibe su parte de la ofrenda de los hijos. Los antepasados reciben chiva para dar descendencia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Palma del monte, Apá, Ìrókò, hojas de cebolla (Allium cepa), aceite de palma, aguardiente."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 169.1 (yorùbá): Ṣerarẹ-Ṣerarẹ / eniti o da eerú li eerú i tọ, / Ṣerare-Ṣerarẹ / Ṣikàṣikà fi Idáji ṣe'rarẹ: / a difá fún Inúkogun ńgberò ibi. / Wọ̀n nì: / \"ohun buruku tioma ṣeyi / yoo dẹhin bowa baajẹ\". / A niki ó wa rúbọ / kio kọ iwà-Ìká silẹ. / Eyẹlé Méjì, egbejilélógún owó / ati ewé Ifá li ebo.", "Verso 169.2 (yorùbá): Qkakaraka-af'owọ-ti-ikú: / a difá fún Ìká / Ìká nwo olokùnrùn kan ninu ilé, / olokünrün naa yoo kú. / Ki Ìká rúbọ / ki àrùn naa ma le ran / elomiran ninu ilé. / Ewúrẹ, adiyẹ, oti-oyinbo ati ewé Ifá.", "REZO: IKA WORI IKA IBORI IKA ILOGUIFUN . MAFEREFUN YEMAYA. ADIFAFUN ORUNMILA. MAFEREFUN OSHUN.", "REZO: IKA FE IGUAFAFA FENFENA PEYE ECHI IBANE FEFE OBA AMACALLE ARITOMBE AKEKE MAFA OFOFO ODA EYELE ACUO AKUKO LEBO.", "REZO: IKA WORI, IKA FOFE IWORI FEFE FELENA LAFABA FEFE LAPUEYE ESHO BAMIFO BEOBA AMACALLE ORITOMBEO OWO MEFA FOFOROFA FARE OWO FOCA OWO LOYU.", "REZO: IKA IWORI IFA OLOGUIFUN OLOFIN. MAFEREFUN YEMAYA ADIFAFUN ORUNMILA.", "REZO: OMODE LOMA UMBO VA ILE ORONLAUNSORO ELWARA EYELE AKUKO ADIE MELLI ORUNLA AFARIYE YANZA IRE OSHINSHE AYE KOFORIBALE NI ELEWARA FIFUN OUNKO OPOLOPO OWO OKO ELODA DIDE YURE.", "SUYERE: EBBO YERO OBA NI SUYA LERI KUTALE IRE SUYA NI IRE IBERA IRE TBEYA IRE IBECHICHE.", "REZO: IKA FEFE IKAWO AWO ADIFAFUN ELESILE APARO DEGBE AYA APARO MABO FARAYE KURORU ADE OGGUN IKAWAROKOKO ADIFAFUN OGGUN AKINORO EIYE ESE ODO OLORI ORAN OMO OPE ILELE AKOMODE PEKOBA ENUYE OSAN KELEKU YOKOAMARE IRIWO LALO EBEGFA NI WABO OKUE LOKUE OKO ANA GUN ANI TOGUN WA EIYE AKELU ACHA OTI IKU AYA OMO AWALANJADIDI AKINTARO AFOYANYA AKINTARO ATA ALAWE OBATALA EGUNGUN OLUFON ORONIYA OGGUN LODE ILU INA INLE.", "REZO: OMODE LOMA UMBO VA ILE ORONLAUNSORO ELWARA EYELE AKUKO ADIE MELLI ORUNLA AFARIYE YANZA IRE OSHINSHE AYE KOFORIBALE NI ELEWARA FIFUN OUNKO OPOLOPO OWO OKO ELODA DIDE YURE.", "SUYERE: EBBO YERO OBA NI SUYA LERI KUTALE IRE SUYA NI IRE IBERA IRE TBEYA IRE IBECHICHE.", "REZO: IKA FEFE IKAWO AWO ADIFAFUN ELESILE APARO DEGBE AYA APARO MABO FARAYE KURORU ADE OGGUN IKAWAROKOKO ADIFAFUN OGGUN AKINORO EIYE ESE ODO OLORI ORAN OMO OPE ILELE AKOMODE PEKOBA ENUYE OSAN KELEKU YOKOAMARE IRIWO LALO EBEGFA NI WABO OKUE LOKUE OKO ANA GUN ANI TOGUN WA EIYE AKELU ACHA OTI IKU AYA OMO AWALANJADIDI AKINTARO AFOYANYA AKINTARO ATA ALAWE OBATALA EGUNGUN OLUFON ORONIYA OGGUN LODE ILU INA INLE."]}]$q$::jsonb),
(170,'b5fe5632c78fcaac04d2545117969a04',$q$[{"titulo": "Idea central", "texto": "Ìká Ìdí pide respeto para evitar castigos y sufrimientos, y señala carencias espirituales que traban las actividades del consultante. Promete riqueza abundante al que ofrenda, y advierte contra engañar a los sacerdotes y esconder un problema que crece en secreto."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Discute con alguien de experiencia sin escuchar sus razones (relato de Ködunmi-Àgbà).", "Un negocio parece prometedor, pero hay riesgo de engaño.", "Siente que descuidó sus obligaciones espirituales o personales.", "Está sin dinero y espera que lleguen recursos (relato del herrero Alágbède Ìmòbà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza que llega de golpe, tanta que no cabe en las manos.", "Librarse del castigo y la aflicción.", "Que una hija o alguien cercano ayude a tiempo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Engañar o burlar a los propios sacerdotes.", "Esconder una herida o un problema hasta que se pudre.", "Que los secretos propios salgan a la calle.", "La juventud imprudente que no respeta a los mayores."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se tapa en vez de curarse acaba oliendo y todos lo saben. El dinero que se recibe para atender un mal no se gasta en otra cosa. Quien empuja a un anciano que está rezando de rodillas no vivirá mucho."}, {"titulo": "Relatos reunidos", "puntos": ["El herrero de Ìmọ̀bà. El herrero de Ìmọ̀bà lloraba porque no tenía dinero. Le pidieron la ofrenda de la riqueza y cumplió. La riqueza le llegó de repente, como el aguacero que salta y cae rodando por la tierra; le llegó tanta que ya no podía recogerla con las manos y pedía que se la dejaran caer al suelo delante de él. Por eso el herrero no recoge el dinero con las palmas: martilla, el mayor junta el dinero, el menor sopla con el fuelle, y la riqueza cae al suelo a su lado.", "La herida de Olófin y el gallo que habló. Àkùkọ Ìtàn gàjàlà, el sacerdote de Olófin, le había pedido ofrenda. Olófin tenía una herida en la pierna. Su hija le dio dinero para que fuera con sus sacerdotes a curarse, pero Olófin se gastó el dinero y no fue con nadie. La herida se extendió; se puso pantalones gruesos para que nadie la viera, pero empezó a oler y ya nadie quería entrar a su casa. Entonces el sacerdote empezó a divulgar el secreto: la herida de Olófin se infectó y empeora. La hija lo oyó y exclamó que los secretos de su padre habían quedado expuestos. Quien tenga una herida o un mal que empeora no debe esconderlo: conviene ir al médico a tiempo, además de cumplir con Ifá.", "Kódúnmi Àgbà. A Kódúnmi Àgbà le pidieron diez huevos, manteca de cacao, una piedra de rayo, dinero y medicina de Ifá para no sufrir castigo ni aflicción en la vida. Àgbà no quiso ofrecer.", "Los desobedientes. Si un joven imprudente se enfrenta a un adivino viejo, recibe una bofetada; si se enfrenta a un viejo herbolario, recibe castigo severo; si tumba a un viejo sacerdote que reza de rodillas, lo buscarán para ejecutarlo antes de tiempo. Así adivinaron para los desobedientes que decían que nadie podía corregirlos: los gusanos mueren muy rápido."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la riqueza: la ofrenda marcada.", "Para no engañar a Ifá: una tela brillante a Èṣù, y ofrenda contra la difamación.", "Contra el sufrimiento: diez huevos, manteca de cacao, piedra de rayo, dinero y medicina de Ifá.", "Medicina: hojas de oriji y ojúùsájú molidas con pimienta negra, cocidas en sopa con un huevo; se le pone la piedra de rayo y se toma al amanecer."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù recibe la tela brillante. Olófin y su sacerdote Àkùkọ Ìtàn gàjàlà. Ògún, dueño de la herrería."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Oriji, ojúùsájú (Petiveria alliacea), pimienta negra, huevos, manteca de cacao, piedra de rayo, fuelle de herrero."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 170.1 (yorùbá): Biaba-rò-li-aroju, / laiṣè-lairò-bi-ominú-nkọ'ni, / lyà Küigbaijẹ'ni: / a difá fún Kòdùnmi-Agbà. / Wọ̀n niki o wa rúbọ / ki ìyà ma baa jẹẹ l'ayé: / Eyin-adiyẹ méwà, òri, edùn-ààrá, / ẹgbàá méjilélógún owó ati ewé Ifá / Agbà gbọ̀ ko rú.", "Verso 170.2 (yorùbá): Bi omodé ba nṣawo ògbójú, / Bí o ba ko ògbó awo lọna, / kiogbaa l'ojú Bi o ba ko àgbàiṣègùn, / kiojẹẹ ni'yà lọ̀pọ̀lọ̀pò. / Bi o ba bürinbürin tiori àgbà / àlufà nibiti o nfi orí kan'lẹ, / kiod'ojú rẹ̀ de'bẹ: / a daa f'àwọn aláigbóràn, / tiiwipẹ: / Kosi eniti", "REZO: IKA DI ATOTOLA ARINLOLA OSUN LAULAU SOMO ALAUN OTUN LIO BABAMO NIKEDA AKO ORUNMILA APEYA IREYA MI LOYU OTO JEJE KOWA FINU NI SHONA KOWA FINU MULAYE SITIMOBOYA BABA EYA SIMILU. ATORI LONI TORODIMKUN BABA DERE INU OMI ALAYEI MEYI BERANJE DA BI ZA FEFE BA FE INU OKAN ALAYE BO BOGBO UNTI UOBABAGBE KOLA SIMINU.", "REZO: IKA DI OLOFIN OLOWA OLORUN SIMIFUN EYE MAKUE INTORI TIWO TISHE EYI AFI WOBE NIMI BOGBO ERAN ATI NI NU BOGBO ERAN EGBEMURENIWO OUNYEN LEYO AIYARE BOGBO.", "REZO: IKA DI ALABERE APOTI BOCHE NIFA NI SHANGO OROLOYE AGONIYEO SOKUN YOBBI OLOFIN ERIKAN YEBIO ORUNMILA OSHE EBBO KUIKUADA LAYE OSA OLORUN OLONGO MORANI IKU EGUEREYEYE TOKUN YERE KUERE IKU OYO NIFA MOTEFA OPOTI OGBA.", "REZO: ADIFAFUN OBATALA MOWAYE ERILE NILE NI LEKUN UMBOWA ODUDUWA EGGUN SIMEDE ILU EGGUN LESE OKE BELELE ORUNMILA EFE NI OCHANLA MOYENI EKUTE SUYERE AWO AGUEDAI SHE DUDU ACHO PUPUA SAWEDE ILU EGGUN BABA ELEGGUA ATI SHANGO MOFORIBALE BABA NI INYANZA BELEGUN LODAFUN ORUNMILA KAFEREFUN SHANGO.", "REZO: SEREGUN SERE MOIKO MODE MOREO ALADO AWADO YEMAYA ERO MO ALADO AWADO YEMAYA.", "REZO: IKA DI ALABERE APOTI BOCHE NIFA NI SHANGO OROLOYE AGONIYEO SOKUN YOBBI OLOFIN ERIKAN YEBIO ORUNMILA OSHE EBBO KUIKUADA LAYE OSA OLORUN OLONGO MORANI IKU EGUEREYEYE TOKUN YERE KUERE IKU OYO NIFA MOTEFA OPOTI OGBA.", "REZO: ADIFAFUN OBATALA MOWAYE ERILE NILE NI LEKUN UMBOWA ODUDUWA EGGUN SIMEDE ILU EGGUN LESE OKE BELELE ORUNMILA EFE NI OCHANLA MOYENI EKUTE SUYERE AWO AGUEDAI SHE DUDU ACHO PUPUA SAWEDE ILU EGGUN BABA ELEGGUA ATI SHANGO MOFORIBALE BABA NI INYANZA BELEGUN LODAFUN ORUNMILA KAFEREFUN SHANGO.", "REZO: SEREGUN SERE MOIKO MODE MOREO ALADO AWADO YEMAYA ERO MO ALADO AWADO YEMAYA.", "REZO: IFA NI KAFEREFUN WAWASI.", "REZO: IKA DI AKEGEGE LABAGE IKA RUGBE LOBEKUE OUN AFETAN ARINKINKIN AWO ADIFAFUN ARINKINKIN ADIFAFUN OLODUMARE OMO AYAPENDA N’KOMO EKUN LEHIN OGUELE N’KOMO EKUN ONIBA OMO ERIKU EPESHESHE DINU AGBA IMODE KUNASERE DINU RUGBE IMODE OUN NIYE MOYA MOYA AYA LETE OTE OTAN.", "IKA DI TIGBEUN OLODUMARE LAGBAGBE ADIFAFUN APARO NIYE TINLEUN MAMARA MAMURA MOFIYE MAURA LAPARO IKE.", "REZO: IKA DI AKIPI IPEAGU IKA DI BA BABLAWO GBELE AYAGBA ORE FADAKA GAITOBA PENJU OLOWARE YO TOSHE BE GIYAN ERUN BINA BAJE KORIKO ILE ABERE AJA GBORU AWO ADIFAFUN LAPADE KAFEREFUN ORUNMILA LODAFUN IYA.", "REZO: IKA DI ALALAYI NI AYAPA OLOFUN INZA LAYAUN ABEROBOKUN IKA DI SHANGO SAHNGO ALALAYI ORUN IKA DI ORUN LOWA OKUALEYE EKUA LOKUN AYAPA ONATOKUN EÑI AYAPA SHANGO LOWA ESHU NI ELEGBARA OÑA EUREO ELEGBARA UMBATI OBOLOYUN UMBATI SHANGO ARAYE NI LOKUN OBARI ASHE AÑAÑA EUREO IKA DI OFO TOKUN AYAPA NI SHANGO OSHANLA LODERUN OBATI ARUN ERI ÑARI EÑI AYAPA OBARI LEYEBU OMA AYAPA UMBO IBU IKA DI SHANGO MOFORE AYE."]}]$q$::jsonb),
(171,'6fb49f0babd61fd9436efb79388067fe',$q$[{"titulo": "Idea central", "texto": "Ìká Ìrosùn habla de vida larga, de ser querido y de que la fortuna de la casa del padre no se pierda, sino que llegue sola. Las rivalidades de pareja o de familia se resuelven a favor del consultante si ofrenda. Advierte contra dejar pendiente la ofrenda que protege de la muerte."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere que lo respeten y lo aprecien (relato de Ìrosùn entre los árboles).", "Teme por su futuro y necesita reconocer lo que vale.", "Hay competencia dentro de la pareja o la familia.", "Quiere que prosperen su casa, su pareja y sus hijos sin perder lo ganado (relato de Ọ̀rúnmìlà y la casa de su padre).", "Va a empezar a trabajar una tierra o un proyecto nuevo y debe revisar los riesgos antes (relato de Àlàó de Ìgbesà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que la fortuna de la casa paterna regrese y no se pierda.", "Riqueza, pareja e hijos que llegan solos, como el agua busca la malanga.", "Ser el preferido, el más querido entre todos.", "Vida larga.", "Fortuna que viene del extranjero."]}, {"titulo": "Ibi y advertencias", "puntos": ["Escuchar la advertencia y dejar la ofrenda para después.", "Morir lejos de casa, en el trabajo, sin ver la cosecha."]}, {"titulo": "Enseñanza principal", "texto": "El campesino no sabe cuál es la cosecha que no llegará a ver; si lo supiera, vendería su azada, su machete y su calabaza de agua. La ofrenda que se deja para mañana puede llegar tarde."}, {"titulo": "Relatos reunidos", "puntos": ["La fortuna de la casa del padre. Ọ̀rúnmìlà preguntó si la fortuna de la casa de su padre se perdería. Le pidieron ofrecer una paloma madura y dinero, y cumplió. Desde entonces las buenas fortunas no lo esquivaron, y cantaba: la riqueza viene a buscarme wàràwàrà, como el agua sale al encuentro de la malanga; la fortuna de las esposas viene wàràwàrà; la fortuna de los hijos viene wàràwàrà.", "Àlàó de Ìgbẹsà. Àlàó, de la ciudad de Ìgbẹsà, iba a abrir un monte virgen para sembrar y lloraba por todas las cosas buenas que quería tener. Le pidieron ofrenda contra la muerte. Oyó, pero no la hizo. Algo ocurrió de repente y se lo llevó: murió en su campo y usó su azada como almohada. Por eso se dice que la serpiente usa la boca como prensa, el escorpión usa la cola como anillo, y el campesino no sabe cuál cosecha no llegará a ver.", "Ìrosùn, el árbol favorito. Àyìnká, el adivino de Ìrosùn, le marcó una paloma, una gallina blanca y dinero para que fuera el más querido entre todos los árboles. Ìrosùn escuchó y ofreció.", "Ìrosùn y la vida larga. El mismo Àyìnká le marcó a Ìrosùn una carnera, hojas de peperẹku y dinero para vivir mucho sobre la tierra. Cumplió, y el adivino declaró: peperẹku vivirá por mucho tiempo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para que no se pierda la fortuna: una paloma madura y dinero.", "Contra la muerte repentina: la ofrenda que marque Ifá, sin demora.", "Para ser querido: paloma, gallina blanca y dinero.", "Para vida larga: carnera, hojas de peperẹku y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà recupera la fortuna de la casa paterna. Los antepasados del padre sostienen esa herencia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Malanga, árbol ìrosùn (camwood), peperẹku, paloma, gallina blanca."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 171.1 (yorùbá): Ayinká awo Irosù: / a difá fún Irosù. / A niki Irosù wa rúbo / kiwọ̀n lefiṣe aayo laarin àwọn igi. / Eyẹlé, agbẹbo-adiyẹ funfun / ati egbàáfà owó, / Ó gbọ̀ ó rú.", "Verso 171.2 (yorùbá): Ayinká awo Irosù. / a dífá fún Irosù. / A niki Irosù wa rubo. / Aikú li ayé. / Ẹbọ: Agùtàn, pẹpẹrẹku / ati egberindilógún owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Afùwàpẹ niti pepẹrẹku\".", "REZO: IKA ROSO IKARABOLA MONI YEYE IKARABOLA MONI IYA OMI KESESE ADIFAFUN ORUNMILA BARABANIREGUN. BASTON ELEBO", "REZO: IKA ROSUNCA KUKUTE KUKU ADIFAFUN NONICA MOGUO AUCO LEBO EYELE AUCO LEBO.", "REZO: IKA ROSO OSUN KUKUTE KUKU KUKU ADIFAFUN ONIKA MOWO OLE LODAFUN OBATALA."]}]$q$::jsonb),
(172,'c0bc5738b19d88d71f0cc32b4b4b01ae',$q$[{"titulo": "Idea central", "texto": "Ìká Ọ̀wọ́nrín pide no actuar con precipitación ni con malas intenciones para no vivir arrepentido. Los disgustos pueden costar el trabajo o la posición; hay que ofrendar para que los enemigos no desplacen al consultante. Trae fortuna de hijos que viven y hermanos que se reencuentran después de una larga separación."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se arrepiente de algo que hizo con prisa (relato de Alábámo).", "Teme perder respeto, empleo o su lugar en un grupo.", "Se siente agobiado por rivalidades.", "Le preocupan sus hijos (relato de Aláaka)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos que viven, sin muerte prematura ni enfermedad.", "Salir del cautiverio o de la situación que lo tiene atado.", "Reencontrar a la familia separada.", "Conservar la posición frente a los enemigos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Actuar sin medir la propia conducta.", "Perder el puesto o el honor por culpa de los enemigos.", "Que la vida quede en desorden."]}, {"titulo": "Enseñanza principal", "texto": "El extranjero no conoce la historia de la tierra a la que llega. A veces el que parece enemigo es un hermano. La gente malvada no evalúa su conducta antes de actuar; el que sí la evalúa se salva del arrepentimiento."}, {"titulo": "Relatos reunidos", "puntos": ["Àláàkà y la colina. Àláàkà quería tener hijos que vivieran. Le dijeron que había fortuna de hijos para ella, pero que debía llevar a sus bebés a vivir al pie de una colina. Ofreció, se fue a la orilla de la colina, y allí empezó a tener más hijos y a criarlos con éxito.", "Ikúbolájé y sus tres hijos. Ikúbolájé, hija de la ciudad de Òjo, se casó en Òró y tuvo allí a Àkà. Se separó, se casó en Òfà y tuvo a Òòrè gìdìgbà. Se fue de nuevo, se casó en Ifẹ̀ Abùrẹ́ y tuvo a Líìlí, el menor, que llegó a ser rey de esa ciudad. Estalló una guerra: a Àkà lo capturaron en Òró y a Òòrè en Òfà, y los generales de Líìlí los trajeron a los dos prisioneros a Ifẹ̀ Abùrẹ́, atados a los pilares del patio del rey, sin saber que era la casa de su hermano. A medianoche Àkà se despertó y lloró: nuestra madre se casó en esta ciudad, me tuvo primero en Òró, tuvo a Òòrè en Òfà, la guerra nos atrapó y no sabemos dónde está Líìlí, que vive aquí. La madre, que paseaba de noche, oyó el lamento y fue corriendo a llamar a Líìlí. El rey salió al patio, escuchó y dijo: son mis hermanos, desátenlos. Los llevó a vivir con él, y bailaban diciendo que la vida les sonreía porque Líìlí los había desatado.", "Alábámọ̀ y las buenas obras. Alábámọ̀ consultó y le pidieron cuatro caracoles, dinero y medicina de Ifá para poder hacer cosas buenas y honestas. Escuchó y no ofreció.", "La gente de Ifẹ̀ Oòyẹ. Los malos rodeaban a la gente de Ifẹ̀ Oòyẹ y querían bajarla al último lugar. Les marcaron ẹfun, osùn, paloma, carnera y dinero. Ofrecieron, y los sacerdotes declararon: quien diga que Ifẹ̀ no puede crecer ni aumentar su honor será destruido; nosotros viviremos mucho y nuestro camino no se borrará del mundo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para hijos: la ofrenda marcada y vivir cerca de una colina.", "Para salir del cautiverio: la ofrenda que marque Ifá.", "Para hacer el bien: cuatro caracoles, dinero y medicina de Ifá.", "Para conservar el puesto: ẹfun, osùn, paloma, carnera y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Òkè, la colina, cuida a los hijos de Àláàkà. Ifá reúne a los hermanos separados."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹfun (tiza blanca), osùn (polvo rojo), caracoles, paloma, carnera."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 172.1 (yorùbá): Ìká-èniyàn / kiiwòn ohun tire kiotooṣee: / a daa fún Alábámo. / Wọ̀n niki o wa rúbọ / kiolemaa ṣe ohun rere. / Ẹbọ: İgbin mẹrin, / ẹgberindilógún owó ati ewé Ifá. / Ó gbọ̀ ko rú.", "Verso 172.2 (yorùbá): Ìká-npoyinka'wọn, / Ọ̀wọ̀n nrẹrín, / a difá fún wọn ni Ifè-Ooyẹ. / A niki wọ̀n rúbọ, / ki ọ̀tá male ṣi wọn ni'po, / Alábámo: el apenado, persona que se lamenta arrepentido y siente pesar por / las acciones del pasado. / ki òtá wọn male bu (ọlá) wọn kù. / çbọ: Efun, osün, eyẹlé, / àgutàn, egbàáméjila owó. / Wọ̀n goọ̀ wọ̀n ru. / Wọ̀n (àwọn Babaláwo) ni: / \"To, Abariwọn, / Eniti o ba wipe ki lfè ma fè, / a run kuro l'ayé. / Ọ̀rúnmìlà! Awo ko wipe ki Ifẹ ma fè, / K'aṣ'ayé pẹ. / Kiila tiwa ma run ninu ayé\".", "REZO: IKA JUANI IKA WA WA ADIFAFUN IKA ODI OFUNEJO OWUNKO, AKUKO EYELE LEBO IKA WANI LODAFUN ORUNMILA. LORDAFUN YALORDE ATI OMO. ANRU MARORA OBI MEYI KAFEREFUN OLOKUN ATI ESHU."]}]$q$::jsonb),
(173,'330718e9532d17f1e34952b68a5ea100',$q$[{"titulo": "Idea central", "texto": "Ìká Ọ̀bàrà enseña cómo hacerse querido y atractivo para los demás. Advierte con fuerza contra gastar el dinero de Ifá y de la casa en amantes, contra exponer las propias debilidades y contra meterse en discusiones calientes. Hay posibilidad de embarazo: si no se busca, hay que cuidarse; si se busca, agradecerlo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere mejorar una relación de pareja (relato de Aṣa y Awodi).", "La falta de agradecimiento está dañando un vínculo.", "Pregunta por un posible embarazo o por hijos (relato de Lekeleke y su esposa).", "Va a entrar a un grupo donde se comparte y debe cuidar su parte (relato del ñame pilado)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser querido y elogiado por todos.", "Riqueza, buena pareja, hijos y una buena casa.", "Hijos tan bellos como los de quien más se admira."]}, {"titulo": "Ibi y advertencias", "puntos": ["Gastar en amantes el dinero de Ifá o de la familia.", "Mostrar las propias debilidades a quien se burla.", "Acercarse a las peleas ajenas.", "Ser repartido entre todos, como comida de mesa común."]}, {"titulo": "Enseñanza principal", "texto": "Lo que Ifá regala no se lleva a la amante: se usa para la pareja, los hijos y la casa. Quien no ofrenda se convierte en el plato que todos rodean y cortan en pedazos."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y el dinero de las amantes. Ọ̀rúnmìlà advirtió a los suyos que nunca usaran el dinero que Ifá les daba para mantener amantes. Algunos no hicieron caso; lo intentaron una y otra vez y terminaron sin que les alcanzara para nada. Entonces recordaron la advertencia, dejaron de darles a las amantes el dinero de Ifá y la vida empezó a sonreírles. Ifá explicó que ese dinero es para tener riqueza, buenas esposas, hijos y una buena casa, y que todos, al despertar cada mañana, deben quererse en su propio hogar.", "El ñame machacado y la mesa común. Al ñame machacado (iyán) le pidieron ofrenda antes de bajar a la tierra, porque allí nunca lo dejarían en paz. Dijo que no hacía falta y no ofreció. Al llegar a la tierra, en cuanto lo terminan de preparar todos se le acercan, lo rodean y lo cortan en trozos grandes; aunque haya toda clase de comidas en la mesa, se comen primero el ñame hasta acabarlo. Tarde alabó a su sacerdote: el mal de no ofrendar es verse repartido entre todos.", "Los halcones Aṣa y Àwòdì. El que camina rápido escapa a tiempo, el que vuela rápido llega a tiempo. Así adivinaron para los halcones Aṣa y Àwòdì, y les pidieron ocho caracoles, dinero y medicina de Ifá para ser queridos y elogiados por todos. No ofrecieron.", "Lékeléke y los huevos de paloma. El escarabajo kẹ̀kẹ̀ baila y las aves revolotean. Así adivinaron para Lékeléke, el ave blanca, y para su esposa, que querían poner huevos tan bellos como los de la paloma. Les marcaron dos pedazos de ẹfun, dos conos de hilo y dinero. Ofrecieron, y desde entonces se dice que los huevos de Lékeléke son tan bellos como los de la paloma."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra los gastos en amantes: la ofrenda marcada.", "Contra la burla de los enemigos: la ofrenda y regalos a Èṣù.", "Para ser querido: ocho caracoles, dinero y medicina de Ifá.", "Para hijos bellos: dos pedazos de ẹfun, dos conos de hilo y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà cuida el dinero de Ifá y la armonía de la casa. Èṣù recibe su parte."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame machacado, ẹfun, hilo blanco, caracoles."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 173.1 (yorùbá): Ẹ rin kialo were, / Ẹ fo kiabo wara: / a dífa fún Aṣa / a bu fún Awodi. / Wọ̀n ni: kiẹwa rúbọ / ki àwọn ọmọ aráyé le fẹran yin. / Ẹbọ: Igbín méjẹ, / ẹgbàájo owó ati ewé Ifá. / Wọ̀n gbọ̀ wọ̀n ko rú.", "Verso 173.2 (yorùbá): Kẹkẹ mọọ jo, / Eyẹ mọọ ra: / a difa fün Lekeleke, / a bu fún aya rè. / Wọ̀n ni: / \"Lodọ yin li àwọn Eyelé / ti maa wa kọ ara / ti wọn ma maa da bi / wọn ba rúbọ\". / Wọ̀n ni: \"kil'ẹbọ?\" / Ẹbọ: Efün Méjì, kẹkẹ iranwu Méjì, / egbejilá owó (egbẹfàfún ẹnikookan). / Wọ̀n rúbọ. / Akiyesi: Lati ojo naa liati npowé pe: / \"Ṣyin ko ri Lekeleke elẹwà / oun lof'ara ki'yẹle\".", "REZO: IKA BARA MOSHOWE YILE SHIOPE ADIFAFUN. OROBE OROBE EKURE EYERE LEBO IKA AWO EYE OBARA ILE AWO YO ADIE LEBO ESHU EYELE AKUKO LEBO. IKA BARA OÑI BARA LOSORDE ORUNMILA ADIFAFUN ORUNMILA ATI OBATALA.", "REZO: IKA BARA OMO BARA LOSORDE ORUNMILA ADIFAFUN ORUNMILA, ADIFAFUN OBATALA IKA BARA IFA MOCHE YIYASE OFE ADIFAFUN OLOKUN EKURE AICORDIE EYELE OWO MESAN TOKE ORUNMILA IBE OKU KORIE GI LEBO AICORDIE EWO ERIN EYO IKARODE WABARI BARA INTORI OMOLUGU OMO NI IKARODE IRE ASGAGUN OTA ESHU ATI ORUNMILA.", "REZO: IKA BARA MOSHOWE YILE SHIOPE ADIFAFUN. OROBE OROBE EKURE EYERE LEBO IKA AWO EYE OBARA ILE AWO YO ADIE LEBO ESHU EYELE AKUKO LEBO. IKA BARA OÑI BARA LOSORDE ORUNMILA ADIFAFUN ORUNMILA ATI OBATALA.", "REZO: MOCHOGUO YILE SHIOPE ADIFAFUN OROBE OROBE OCURE EYELE LEBO IKA OLLO OBARA ILE ADIE LEBO ESHU EYELE AKUKO LEBO.", "REZO: IKA BARA IFA MOCHE YIYESE OFE ADIFAFUN OLOKUN ECURE AIKORDIE EYELE OWO MESAN TOKE ORUNMILA IBE EKU KORU GUI LEBO AIKORDIE EGUO ENRIN OPOLOPO OWO.", "REZO: IKA BARA ONI BARA LOSORDE ORUNMILA ADIFAFUN ORUNMILA ADIFAFUN OBATALA.", "REZO: IKA BARA OMO BARA LOSORDE ORUNMILA ADIFAFUN ORUNMILA, ADIFAFUN OBATALA IKA BARA IFA MOCHE YIYASE OFE ADIFAFUN OLOKUN EKURE AICORDIE EYELE OWO MESAN TOKE ORUNMILA IBE OKU KORIE GI LEBO AICORDIE EWO ERIN EYO IKARODE WABARI BARA INTORI OMOLUGU OMO NI IKARODE IRE ASGAGUN OTA ESHU ATI ORUNMILA."]}]$q$::jsonb),
(174,'75304cc6a7e38803369fc32c151f3a59',$q$[{"titulo": "Idea central", "texto": "Ìká Ọ̀kànràn pide ofrenda para borrar las consecuencias de las malas acciones y cambiar de carácter. Hay una gran oportunidad esperando que depende de una decisión justa. La persona tiene sabiduría suficiente para vivir; no debe apresurarse ni maldecir a nadie cuando le roben, porque el ladrón está cerca y se delatará solo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una decisión importante depende de actuar con justicia.", "Reconoce una conducta pasada que debe cambiar (relato de Ẹka).", "Quiere controlar todo lo que resulte de sus actos (relato de las manos).", "Tiene una buena idea, pero necesita calma en vez de correr sin rumbo (relato de Ògúngbádé)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Estabilidad y ganancia en el comercio.", "Su propia sabiduría le alcanza para sostenerse.", "Que sus bienes se multipliquen.", "Escapar de la muerte cambiando de conducta."]}, {"titulo": "Ibi y advertencias", "puntos": ["La muerte que viene por los actos malvados.", "Las prisas y el esfuerzo desmedido.", "Un ladrón dentro de la casa.", "Dejar las cosas descuidadas."]}, {"titulo": "Enseñanza principal", "texto": "Un dedo que entra en el aceite mancha a los demás. La mano conoce lo bueno y lo malo; quien quiere solo lo bueno debe ofrendar y cuidar su carácter. Con la propia inteligencia basta: no hace falta forcejear como la gallina sobre la soga."}, {"titulo": "Relatos reunidos", "puntos": ["Ògúngbádé y la gallina en la soga. Ìká dio a luz a uno, Ọ̀kànràn dio a luz a otro: una gallina se posa en una soga, la soga está incómoda, la gallina está incómoda, y las dos se balancean de un lado a otro. Así adivinaron para Ògúngbádé, del clan cuyo lema dice que la sabiduría de uno basta para comer. Preguntó si su vida no se echaría a perder. Le pidieron ofrendar y le dijeron que todo se acomodaría solo. Ofreció, comerció, ganó, no perdió hijos ni vio desgracias. Le dijeron: no te esfuerces de más, Ògúngbádé; tu sabiduría alcanza para darte de comer.", "La mosca y el chicle. La mosca común compró a la goma pegajosa (àtè) como esclava. La goma no hacía otra cosa que robar: no descansaba hasta llevarse algo, y todo lo que veía se le quedaba pegado. La mosca se preguntaba qué clase de esclava había comprado. Ifá le dijo que la dejara en paz, que no la maldijera, que sus bienes se multiplicarían, pero que nunca dejara sus cosas descuidadas. La mosca obedeció y todo lo suyo se multiplicó. Por eso, cuando a este consultante le roban, no debe maldecir: el ladrón es alguien cercano y él mismo se descubrirá.", "Ẹ̀kà y la ropa negra. A Ẹ̀kà le dijeron que la muerte venía por él a causa de todo el mal que había hecho. Si no quería morir, debía ofrecer una carnera y la ropa negra que usaba, cambiar su carácter malvado y vestir de blanco desde entonces. Escuchó y ofreció.", "Las manos. Ito, el adivino que pone cada cosa en su sitio, adivinó para las manos y les pidió paloma blanca, gallina blanca, dinero y medicina de Ifá para que solo lo bueno llegara a ellas. No ofrecieron. Por eso la mano siempre toca lo bueno y también lo malo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para estabilidad: la ofrenda marcada.", "Contra el robo: la ofrenda, y no maldecir al ladrón.", "Contra la muerte: una carnera y la ropa negra que se esté usando; después vestir de blanco.", "Para que llegue lo bueno: paloma blanca, gallina blanca, dinero y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá protege al que cambia su carácter. Los antepasados del clan de la sabiduría."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ropa blanca, paloma blanca, gallina blanca, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 174.1 (yorùbá): Ìká-Konràn: / a dífá fún Ẹka. / Wọ̀n ni: / \"ikú nbọ / nitori gbogbo Ìká tioti nṣe\". / Biabawipe ki wọ̀n ma le pa / Ṣka kio wa rúbọ: / Àgùtàn ati aṣo dúdú ti o nlo. / Kiofi iwà-Ìká silẹ / kiomaa lo aṣo fúnfún. / Ó gbọ̀ ó rú.", "Verso 174.2 (yorùbá): Ito li o difá fún Qwọ̀. / Wọ̀n niki Qwọ̀ wa rúbo / ki ohun rere gbogbo le / maa wa si ikawo re; / ki ohun buburú ma le kan an lara. / Ebọ: Ẹyẹlé fünfün, adiyẹ fúnfún, / egbàawa owó ati ewé Ifá. / Ó gbọ̀ ko rúbọ. / Wọ̀n ni: / Ati ire ati ibi li qwọ maa ma kan.", "REZO: IKA KANA IFA AWO OMO KANA BOGBO OMO A LAYE ELEGBARA OFO LODE AKANA SUAYU MAMAKENA LORDAFUN ORUNMILA.", "REZO: IKA KANA OLI KUN FINU ADIFAFUN ETU TUNSHERU OLOBO EYELE LEBO OSHE ADIE EYELE LEBO.", "REZO: IKA KARAN IFA ONAORDO ANARE ADIFAFUN ETU ERU UN BATIN SHERU OLORDO UN SALOSA.", "REZO: ETU MANO ASHO LOBINI OWO LA MELLO.", "REZO: LA KANA LA MOFIO NOMUE LORDAFUN OBATALA BONI BA UN JAREDA LUGUEORINI SHIGUAFUN NI SHIGUAFUN.", "REZO: IKA KANA AWO IFA OMO KANA BOGBO OMO ALAYE ELEBARA OFO LODE AKAMA SUAYU MAMAKEÑA LODAFUN ORUNMILA.", "REZO: IKA KANA LOYORUN BABA IRE OMO YARE OMO ASHE IGBA ASHE BABA BABA LAYE ORUN ITERUN OBA IKU BABA OMO LAYE WINKOLODE OMO OFO ASGO KANFUN OSUN BILODE APAYUREO FORIBALE OLORUN ÑAÑA KODE IFA ÑAÑA YURE ORUNMILA EBBO EBBO ASHE ASHO TIMBELARA MALAGUIDI ORI EFUN EPO EKU EYA AKUKO LESE EGGUNS EYEBALE ELEBO EGGUN LOYE OKANA YEBE IKU EGGUNS IRE.", "REZO: IKA KANA AWO IFA OMO KANA BOGBO OMO ALAYE ELEBARA OFO LODE AKAMA SUAYU MAMAKEÑA LODAFUN ORUNMILA.", "REZO: IKA KANA LOYORUN BABA IRE OMO YARE OMO ASHE IGBA ASHE BABA BABA LAYE ORUN ITERUN OBA IKU BABA OMO LAYE", "WINKOLODE OMO OFO ASGO KANFUN OSUN BILODE APAYUREO FORIBALE OLORUN ÑAÑA KODE IFA ÑAÑA YURE ORUNMILA EBBO EBBO ASHE ASHO TIMBELARA MALAGUIDI ORI EFUN EPO EKU EYA AKUKO LESE EGGUNS EYEBALE ELEBO EGGUN LOYE OKANA YEBE IKU EGGUNS IRE."]}]$q$::jsonb),
(175,'d5666533871342cb31b49e9b73ca747d',$q$[{"titulo": "Idea central", "texto": "Ìká Ògúndá pide ofrecer a Ògún para que el miedoso gane valor y para defender la inocencia. Viene una celebración y algo digno de alegría, pero el exceso de entusiasmo puede arruinarla: en la fiesta no se dispara al aire ni se provoca alboroto. Pide ofrenda a la cabeza para no morir antes de tiempo. El consultante puede estar inventando un problema que no existe."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme un pleito antes de que pase y debe confirmar si de verdad existe.", "Necesita sostener su postura sin dejarse llevar por la ira (relato de Adetutu).", "Celebra un logro y puede ponerse en riesgo por imprudente (relato de Olónkò-ègì).", "Hay un pleito por cosas de alguien que murió, o alguien las retiene sin derecho (relato de Látalè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una celebración y un motivo de alegría.", "Ser honrado públicamente.", "Establecerse y hacerse conocido en un lugar nuevo.", "Que Ògún pruebe su inocencia."]}, {"titulo": "Ibi y advertencias", "puntos": ["Terminar la fiesta con un disparo: el exceso que espanta a todos.", "Bromas de cortarle la cabeza; peligro sobre la cabeza.", "Morir de miedo antes de la pelea.", "Fingir problemas que no existen."]}, {"titulo": "Enseñanza principal", "texto": "Quien hace el bien recibirá el bien, y a ese lo apoya Ògún. La alegría se goza con medida: el que dispara en medio del baile se queda bailando solo. Cuidar la cabeza es inevitable."}, {"titulo": "Relatos reunidos", "puntos": ["Olónkò ègì y el disparo. A Olónkò ègì le advirtieron que no terminara su fiesta con un tiro; si ofrecía, la vida lo complacería, pero nunca debía disparar al aire. Llegó al lugar donde lo iban a honrar como nunca, bailó y bailó, y al final sacó su arma y disparó al aire. Toda la gente se dispersó y desapareció: nadie se queda alrededor después de oír un tiro. Tarde alabó a sus sacerdotes.", "El quimbombó y su cabeza. El quimbombó (ilá) iba a abrir un campo nuevo. Le desearon que se estableciera y prosperara, pero le advirtieron que ofreciera a su cabeza (Orí) contra alguien que haría la broma de decapitarlo. Contestó que lo importante era llegar y hacerse famoso. Lo sembraron, creció, maduró y se dobló hacia un lado; entonces el hombre llegó a probarlo y le rompió la punta: pònhùn. Por eso, para saber si el quimbombó está tierno, se le rompe la cabeza.", "Adétútù, el hijo del cobarde. Adétútù vivía sumido en el miedo, medio muerto antes de cualquier pelea. Le dijeron que Ògún prueba la inocencia de quien hace el bien, que nadie en problemas deja de pedirle apoyo, y le marcaron un perro, vino de palma, ñame asado y aceite de palma. No ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la celebración: la ofrenda marcada y regalos a Èṣù; no disparar ni provocar alboroto en la fiesta.", "Para la cabeza: ofrenda a Orí.", "Para el valor: un perro, vino de palma, ñame asado y aceite de palma a Ògún."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún da valor y defiende al inocente. Orí debe recibir su ofrenda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Quimbombó, ñame asado, vino de palma, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 175.1 (yorùbá): Ogún-dámil'are, / Ögún jowọ gbe mi, / Kos'ẹniti o ni ejó tabi ijà tikiiwipe, / ki Ogún jowọ gbe òun. / Eni nṣe rere a ri're, / enikan dandan li Ogún yoo gbe: / a daa fún Adetutu, / Ọmọ-Ojokof'okan-balẹmi (eemi), / Akúde'dajikijàtoode. / Wọ̀n niki ó rú: / Ajá kan, ẹmu, ẹsun-iṣu ati epo. / Ó gbọ̀ ko rúbọ.", "REZO: IKA OGUNDA ADIFAFUN OZAIN, AKUKO LEBO. IKA OGUNDA ADIFAFUN ORUNMILA EURE LEBO. KIDI BOGBO BAYE TISHE KIDI OMA ODAGUN ARUKO MEDILOGUN EYELE, IKELE, EWEFA, OLELE, AKUKO LEBO. IFA IKA MIGUNDA IRU OMO ORUNMILA OUN OMO OZAIN KAFEREFUN OGUN, ORUN MILA, YEMAYA ATI INLE.", "REZO: IKA OGUNDA COMBI SAMI ABELE KUAO YEYE IBU LOSA ADIFAFUN OSHUN.", "SUYERE: OKUKU SA NIYEYE TO MA NI IYA OKUKU.", "REZO: IKA OGUNDA OZAIN MAFEREFUN MAWA LODE LOGUE MAGUI MAWA IGUI OZAIN ONIRE OMO OBORI BAYE OZAIN OKUNI WADA OZAIN ABO NI BAWA IKU FARAYE IKA AYO SHANGO ROMI BAWA AYO ROBAKUN ADERI AWO OMO OZAIN IFA KOLIKUN SHANGO IFA KAFEREFUN OZAIN ATI ELEGBARA."]}]$q$::jsonb),
(176,'7f31741e65997cb3b89a8846bf0dfa3b',$q$[{"titulo": "Idea central", "texto": "Ìká Ọ̀sá advierte que no se haga nada deshonesto: el mal carácter vuelve cobarde a uno. Pide a la pareja ofrendar junta para envejecer unida y no separarse, y pide a la persona ofrecer una gallina de Guinea a su cabeza para volverse alguien de peso. Las emociones desordenadas llevan a malas decisiones."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está pensando conseguir algo por un medio deshonesto (relato del ladrón).", "Un conflicto emocional está influyendo en sus decisiones.", "Quiere recuperar la paz en un ambiente alterado (relato de Jókó-jẹ).", "Su buena fortuna depende de atender su cabeza (Orí)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vida larga y en pareja.", "No quedarse solo.", "Volverse una persona importante y respetada.", "Paz y descanso."]}, {"titulo": "Ibi y advertencias", "puntos": ["Divorcio y separación.", "Hacer las cosas con engaño, como el ladrón.", "Decisiones tomadas en medio del desorden emocional."]}, {"titulo": "Enseñanza principal", "texto": "El machete sin mango no sirve, y el mango sin machete tampoco: cada uno vale por el otro. El ladrón nunca es más valiente que el dueño de las cosas. Es la cabeza la que trae la riqueza."}, {"titulo": "Relatos reunidos", "puntos": ["El machete y su mango. El machete iba a tomar por esposa a su mango de madera. A los dos les pidieron ofrendar juntos, porque un machete sin mango no sirve para nada y un mango sin machete tampoco vale. Los dos ofrecieron. Desde entonces el machete es el marido del mango y el mango es la esposa del machete, y su vida juntos está bien asentada.", "Oòni y la gallina de Guinea. Oòni, el rey de Ifẹ̀, quería ser una persona de sustancia y fue a ver a Ọ̀rúnmìlà. Le pidieron conseguir una gallina de Guinea y ofrecerla a su cabeza, y le dijeron que se volvería una gran personalidad. La preparó y la ofreció a su Orí. La vida le sonrió y se volvió un hombre de gran honor. Por eso se dice: es Orí el que produce la riqueza.", "El ladrón. El mal carácter vuelve cobarde a uno. Así adivinaron para el ladrón, y le dijeron que nunca sería más valiente que el dueño de lo que roba. Le pidieron cuatro caracoles, dinero y medicina de Ifá para conseguir las cosas fácil y honestamente. No ofreció.", "Jókójẹ́ y la tela azul. Cuando el mundo está fresco descansamos, y los malos se van del pueblo. Así adivinaron para Jókójẹ́, que quería vivir en paz. Le marcaron tela azul cielo, paloma, carnera y dinero. Ofreció, y desde entonces se viste de azul como protección."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la pareja: la ofrenda marcada, hecha por los dos juntos.", "Para la cabeza: una gallina de Guinea a Orí.", "Para obtener las cosas con honestidad: cuatro caracoles, dinero y medicina de Ifá.", "Medicina: hojas de wọ̀rọ̀ y ẹ̀ṣọ cocidas en sopa con la carne de los caracoles.", "Para la paz: tela azul cielo, paloma, carnera y dinero; vestir de azul."]}, {"titulo": "Relaciones espirituales", "texto": "Orí trae la grandeza. Ọ̀rúnmìlà orienta a Oòni, sacerdote de Odùduwà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Gallina de Guinea, ẹ̀ṣọ (Elytraria marginata), wọ̀rọ̀, jókójẹ́ (Cissampelos owariensis), tela azul cielo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 176.1 (yorùbá): İwàburúkú-nmu'niiṣ'ojo: / a dífá fún Ole, / Wọ̀n ni: / \"Ole komaa l'aya bi Olohun\". / Wọ̀n niki Ole wa rubo / kiobaa lemaa gba ona ẹso ni inkan. / Ẹbọ: İgbin mẹrin, / egbàásàn owó / ati ewé lfa / Ko rubọ.", "Verso 176.2 (yorùbá): Ayé tutu a simi, / Ẹniburúkú lọ (kuro) laarin ilú: / a difá fún Jóko-jé, / wọ̀n ni Jókó-jẹ a simi / wọn niki o wa rúbọ: / Aṣo dúdú ofeefee, ẹyẹle, agutan / ati egbàáwa owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"aṣo ofeefee niki Jókó-jẹ / maa fi bo'ra\".", "REZO: IKA SA ADIFAFUN ORUNMILA ADIFAYOKO MATEKUN AUE TINSHIYAORDIRE TINSHIYA AGUIKO OFI OSILE ONSHEREFA MEOFO, OTA, EPO, EWE, OSA LEBO ORDIRE, OSA LEBO SIEBO AKIKO OSHELE OMO EYELE, OWO, EYA, ABETA OWO.", "REZO: IKA SA IFA ORUNMILA ADIFAYOKO MEDEKUN TINSHILLA QUE TINSHILAORDIRE TINSHELLA AGUIKO OFI OSILE ONSHEREFA MEOFO OTA EPO OSA LEBO SIEVO, ORDIREBE ESA LEBO SIOBO AKIKO OSHELE EYELE AWO EYA EBETA OWO.", "REZO: IKASA IKASA BALLEBEI IFA BABALAWO OMO ORIBOWA ONI AWO ALLA OMO LLALLERI OYA OYA BAGUAORDUZ OBONELLI OGGUN TIGUALLORU GOGOZORA YEIN ONIBUAGUANI OBANI SHANGO GUEGUENIYE ONI OSHUN OMO OYA TIGUA YOROKUN INTORI ONI OYI MOBAGUA ELEGGUA ONI YANZA.", "SUYERE: OBATEKUN LAYE EGUN IBALAWO IKA SA OMO BORONIFE.", "REZO: IKA SA IFA ORUNMILA ADIFAYOKO MEDEKUN TINSHILLA QUE TINSHILAORDIRE TINSHELLA AGUIKO OFI OSILE ONSHEREFA MEOFO OTA EPO OSA LEBO SIEVO, ORDIREBE ESA LEBO SIOBO AKIKO OSHELE EYELE AWO EYA EBETA OWO.", "REZO: ASAN PAPANILLA ORILLE UMBARRIRI UMBA ASHIMBA AWALE ARU EREFUN ATE ADIE LEBO, S6.80.", "REZO: IKASA IKASA BALLEBEI IFA BABALAWO OMO ORIBOWA ONI AWO ALLA OMO LLALLERI OYA OYA BAGUAORDUZ OBONELLI OGGUN TIGUALLORU GOGOZORA YEIN ONIBUAGUANI OBANI SHANGO", "GUEGUENIYE ONI OSHUN OMO OYA TIGUA YOROKUN INTORI ONI OYI MOBAGUA ELEGGUA ONI YANZA.", "REZO: IKA SA IFA ORUNMILA ADIFAYOKO IRE UMBO ILE AKUKO OKAN SHONSHON, OSIADIE OKAN SHONSHON ELEBO.", "REZO: IKA SA ORI TURE RULU OTUPON EMEYELE AFADI ABA TINSHE OMO OLU ODA OSA ORI TURUFAN OMA LERI ADIFAFUN KUAKETE TINSHE OMO OLOBO OMA YEYE OFORI BERE BERE RILE UNYEN OSHON KELE KELE AWO ADIFAFUN ORUNMILA EURE KODA WADA IYESA SI MAMU LAWARA EURE.", "REZO: IFA NI KAFEREFUN SHANGO, ODUDUWA ATI OZAIN. LODAFUN EGGUN."]}]$q$::jsonb),
(177,'476a42fc23a24a5d1f1f10791eacc19f',$q$[{"titulo": "Idea central", "texto": "Ìká Òtúrúpọ̀n habla de la necesidad de una relación espiritual y de una pareja que el consultante viene rechazando aunque le conviene. Promete esposa y descanso al que ofrenda. Advierte contra pelear: hay que soltar a tiempo lo que se tiene agarrado y escuchar consejo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se resiste a una unión que podría convenirle.", "Busca a alguien de confianza que cuide sus bienes (relato de la terrateniente y su casa).", "Pregunta si encontrará pareja (relato de Itú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Esposa y hogar, sin ver morir a la pareja.", "Una relación que trae prosperidad y tranquilidad.", "Alguien digno que cuide la casa por detrás."]}, {"titulo": "Ibi y advertencias", "puntos": ["Rechazar a todos los pretendientes por desconfianza.", "Que le roben lo más valioso mientras duerme confiado.", "Pelear y no soltar: quedar trabado.", "Maldecir a ciegas."]}, {"titulo": "Enseñanza principal", "texto": "La maldición mata al que maldice. Quien se encierra detrás de dieciséis puertas no está más seguro que quien busca buena compañía. El que no suelta la mano ni la pierna a tiempo queda atrapado y no disfruta nada."}, {"titulo": "Relatos reunidos", "puntos": ["Itú y la pimienta de caimán. Itú lloraba porque no tenía esposa. Le dijeron que tendría muchas y que nunca vería morir a ninguna, y le marcaron mucha pimienta de caimán y palomas. Le indicaron masticar la pimienta, escupirla y anunciar: ya ofrecí, tùé. Así lo hizo, dio su parte a Èṣù, y la fortuna de las esposas le llegó como llega a los pies del rey de los Òrìṣà.", "La terrateniente de las dieciséis habitaciones. Una mujer dueña de tierras construyó una casa de dieciséis habitaciones. Le pidieron dieciséis palomas, dos patos, dieciséis caracoles, dinero y medicina para encontrar a alguien digno que le cuidara la casa y para que un ladrón no le robara lo que más le dolería perder. Dijo que no necesitaba a nadie: dormía en la habitación dieciséis y cerraba todas las puertas al caer la tarde. Rechazó a Ọbàlùfọ̀n, a Ọ̀sanyìn, a Ògún y a Ọ̀rúnmìlà. Una noche Ọ̀rúnmìlà, con su irofá en la mano y los encantamientos de Ifá en la boca, abrió todas las puertas sin que nadie despertara y llegó hasta ella. Al día siguiente ella vio lo que había pasado y no sabía quién había sido; los guardias dijeron que habían dormido toda la noche. Mandó a los niños de la casa a salir con campanas maldiciendo al desconocido, y nadie respondió. A la mañana siguiente Ọ̀rúnmìlà salió con sus compañeros tocando la campana y cantando: la maldición mata al que maldice. Al saber que era Ọ̀rúnmìlà, el que antes la había pretendido, lo mandó llamar y le dijo que solo él podía ser su marido. Si este Odù sale para una muchacha en su consagración o al nacer, se aconseja que se case con un Babaláwo: será próspera y tranquila.", "Los perros de Ìhànrín. Ìká no quiso soltar sus manos e Ìpọ̀n no quiso desenredar sus piernas. Así adivinaron para la gente de Ìhànrín, que muerde antes de hablar. Les pidieron soltar, y se negaron. Por eso los perros, cuando se aparean, quedan trabados y nunca lo disfrutan. Este Odù pide no pelear con nadie y ejercer la contención."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para tener pareja: mucha pimienta de caimán y palomas; masticar la pimienta, escupirla y anunciar la ofrenda; regalos a Èṣù.", "Para cuidar la casa: dieciséis palomas, dos patos, dieciséis caracoles, dinero y medicina de Ifá.", "Contra las peleas: la ofrenda que marque Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà, que con el irofá abre todas las puertas. Ọbàlùfọ̀n, Ọ̀sanyìn y Ògún como pretendientes rechazados. Èṣù y el rey de los Òrìṣà, a cuyos pies se encuentra la fortuna de la pareja."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pimienta de caimán (ataare), palomas, patos, caracoles, irofá, campana."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 177.1 (yorùbá): Awun njọla igbá, / Irere f'aya gbẹnkẹn, / Ogbo Airá ni i san irókò lori tewétewé: / a difá fún Onilé Obirin / Kole-kaasẹ mẹrindilógún. / Wọ̀n niki o rúbọ / kiobale ri enirere fi ehin ti, / ki ole ma le ji ohun tiomaa dùn un ju lọ. / Ẹbọ: Ẹyẹlé merindilógún, pẹpẹyẹ Méjì, / igbin mẹrindilógún, egbàá mẹrindilógún owó ati ewé Ifá. / Onilé Obirin kọ ko rú. / Ó ni: Kinni ohun ti òun i ba maa wa / alafẹhin ti ṣe, / nibo li ole yoo ti wa ja / òun ninu yara mẹrindilógún?", "REZO: IKA TRUPON KUKUTE KUKU ADIFAFUN ORUNMILA, ADIFAFUN OLA NIKA, EYELE LEBO. ERU INGUIN ASHO INKI INLA UMBEYA MARORA ENIBI INKA BUTILA KAFEREFUN SHANGO ATI YEMAYA. KAFEREFUN YEMAYA, KAFEREFUN SHANGO.", "REZO: ADIFAFUN OBINI IYA OBO ORUBA INA OPOLOPO OFIKALE TRUPON INDOKO YEMAYA ASESU FOTIFO OFIKALE LOBI ONIGUN ABE OSHIBIRI ABI OWO FUN NI ORUNBI OGBE ISHU OGGUN AYIFO ONYON OFIKALE KOPEKI PUPO AÑARI LEBO ALARO LEBO OSUN LEBO OSHE ABIOMONIBA OGE YEMAYA IKU LODO ONIBODE INDOKO.", "SUYERE: IYA OLO OBO ORUBO UNLO ADE ODO MAPON.", "REZO: ADIFAFUN OBINI IYA OBO ORUBA INA OPOLOPO OFIKALE TRUPON INDOKO YEMAYA ASESU FOTIFO OFIKALE LOBI ONIGUN ABE OSHIBIRI ABI OWO FUN NI ORUNBI OGBE ISHU OGGUN AYIFO ONYON OFIKALE KOPEKI PUPO AÑARI LEBO ALARO LEBO OSUN LEBO OSHE ABIOMONIBA OGE YEMAYA IKU LODO ONIBODE INDOKO.", "SUYERE: IYA OLO OBO ORUBO UNLO ADE ODO MAPON."]}]$q$::jsonb),
(178,'b91ac2dac8f941d0bd694ef942bfd608',$q$[{"titulo": "Idea central", "texto": "Ìká Òtúrá anuncia el fin de los problemas y el comienzo de la buena suerte: lo que los enemigos manden contra la casa terminará en vergüenza para ellos. Trae descanso y paz mental. Pide prudencia, no buscar pleitos y ofrendar para no ver una enfermedad que inmovilice."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que cambie una mala racha.", "Hay oposición a un proyecto y necesita organizarse (relato de los adversarios de Ọ̀rúnmìlà).", "Quiere mejorar su vida material y familiar.", "Necesita pensar con calma antes de decidir."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que la suerte cambie de mala a buena.", "Paz, descanso y una vida bien hecha.", "Dinero, pareja e hijos que llegan a la casa.", "Que el ataque de los enemigos fracase."]}, {"titulo": "Ibi y advertencias", "puntos": ["Provocar problemas sin prudencia.", "Una enfermedad que deja inmóvil.", "Dos que chocan hasta destruirse uno al otro."]}, {"titulo": "Enseñanza principal", "texto": "El anciano camina de noche con cuidado para no caerse. Dos troncos que chocan sin parar terminan hechos polvo. El que medita en silencio no está mudo: sabe esperar su parte."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà en ilédì. Ọ̀rúnmìlà decidió entrar en ilédì, el recogimiento del ikin bajo el plato, sin decírselo a nadie. Le pidieron ofrendar. Mientras él meditaba en casa, sus representantes seguían adivinando; el día de los rituales, Ọ̀rúnmìlà pedía algo en particular y le daban ratas, carne y pescado. La gente pensaba que, tapado bajo el plato, no podía hablar, pero él cantaba: todo se arreglará mejor si me dan carne. La vida les sonrió a todos.", "El gusano de Guinea. El gusano de Guinea traía guerra del cielo a la tierra; llegó buscando gente para dejarla inmóvil. Ifá pide ofrenda para no ver una enfermedad que paralice, y se le canta: por favor, gusano de Guinea, no nos dejes impedidos. Ante cualquier hinchazón, herida que no cierra o debilidad en las piernas, conviene ir al médico.", "Ìká me empujó y no caí. Ìká me empuja, pero no me caigo; Ìká manda espíritus malos a mi casa, pero mi casa no se desordena y se llena de fortuna. Así adivinaron para Ọ̀rúnmìlà, y le dijeron que lo que hicieran sus enemigos terminaría en vergüenza para ellos. Le marcaron seis palomas, dinero, pimienta de Guinea y medicina de Ifá. Ofreció.", "El recolector y el carpintero. Ìká Òtúrá, el recolector, el carpintero: ayúdame a tener dinero, ayúdame a tener esposa, ayúdame a tener hijos; ven y trae todas las cosas buenas a mi casa. Con este rezo se marca el Odù en el iyẹ̀ ìròsùn."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la paz: ratas, carne y pescado para Ifá.", "Contra la enfermedad que inmoviliza: la ofrenda que marque Ifá.", "Contra los enemigos: seis palomas, dinero, pimienta de Guinea y medicina de Ifá.", "Medicina: quemar hojas de kuti y de itọ con pimienta de Guinea, molerlo y mezclarlo con jabón para bañarse.", "Para atraer lo bueno: iyẹ̀ ìròsùn marcado con Ìká Òtúrá y rezado; se unta en la cabeza o se come mezclado con aceite de palma."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà en ilédì, bajo el plato. Ikin, la semilla sagrada de Ifá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Kuti, itọ, pimienta de Guinea, iyẹ̀ ìròsùn, aceite de palma, ratas, pescado, jabón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 178.1 (yorùbá): Ìká ti mi, Emi koṣubu. / Ìká nran ibi sile mi, / Ilé mi ko tú, / gbogbo ire nkojo: / a dífá fún Ọ̀rúnmìlà. / Wọ̀n nì: / \"Ojú a ti gbogbo àwón / ti nba Ọ̀rúnmìlà s'ọ̀tá\". / Wọ̀n niki o rubọ: / Eyelé méfà, egbàá méfà owó, / ataare ati ewé Ifá / Ó gbọ̀ ó rú.", "Verso 178.2 (yorùbá): Ìká-Òtúrá, / Akowonjo, / Lapawonpo: / Bami kowo jo, / bami ko aya jọ, / bami ko qmọ jọ, / kiowa ko gbogbo ire jẹ sile mi.", "REZO: IKA FOGUERO KOMBU KUMBO ADIFAFUN OÑI BINI EYELE LEBO KAFEREFUN OYA, ALA ATI OLORUN.", "REZO: AWO AKUARORO OMOBELE OLORUN EYOBIOCHE INLE KEREKERE OBAYE OLORUN ATEON AKUARORO ARUN EKOKAN BIYE ETIKU SARA AWO BUYOKO ABALELE IFA OMO ADEBI AYE OLOFIN BOGBO ASHE OLORUN OGBA ERUN ONI KAYE ODUDUWA OMO OLOFIN LEKUN OMO OWO IFA OBI OGO ORUN IFA NI KAFEREFUN OLORUN.", "REZO: ADIFAFUN APOHORO AMOFA MEYE KERE LARIN OBAYE OGBA LELE APOHORO ENI ORUN OKOKAN LERIN OFU ARUN TOKU SARA BUYOKO VERA LODI OFO ODARA OMOFA EBBO ODODA LODAFUN ORUNMILA.", "REZO: IFA FOLGUERO ILE OBANI BOKUN OKUE ANALARE LOYE AFEFE OGUEDE, EYA ORUN OSA OSA FOLGUERO OYA BEWAO OMO OBONISHE AWO NIYERE AWO IKA IFA FOLGUERO ERI LAYE ERI LOKUN IYA LOKUN SEWERE.", "REZO: IKA KUARO ABEYENIFU ANIBOSHE OYA INA BOSHE LODE BEWE NI BOSHE BABA KUELE YEKUN IYANI OBONI BOSHE OINO AYEYELE NI IFA OMO WENWEYO OLORUN ASHE BONI LAYE OMO MAYIRE AWO ENI IFA AWO LAYE OINA.", "REZO: AWO AKUARORO OMOBELE OLORUN EYOBIOCHE INLE KEREKERE OBAYE OLORUN ATEON AKUARORO ARUN EKOKAN BIYE ETIKU SARA AWO BUYOKO ABALELE IFA OMO ADEBI AYE OLOFIN BOGBO ASHE OLORUN OGBA ERUN ONI KAYE ODUDUWA OMO OLOFIN LEKUN OMO OWO IFA OBI OGO ORUN IFA NI KAFEREFUN OLORUN.", "REZO: ADIFAFUN APOHORO AMOFA MEYE KERE LARIN OBAYE OGBA LELE APOHORO ENI ORUN OKOKAN LERIN OFU ARUN TOKU SARA", "BUYOKO VERA LODI OFO ODARA OMOFA EBBO ODODA LODAFUN ORUNMILA.", "REZO: IFA FOLGUERO ILE OBANI BOKUN OKUE ANALARE LOYE AFEFE OGUEDE, EYA ORUN OSA OSA FOLGUERO OYA BEWAO OMO OBONISHE AWO NIYERE AWO IKA IFA FOLGUERO ERI LAYE ERI LOKUN IYA LOKUN SEWERE.", "REZO: IKA KUARO ABEYENIFU ANIBOSHE OYA INA BOSHE LODE BEWE NI BOSHE BABA KUELE YEKUN IYANI OBONI BOSHE OINO AYEYELE NI IFA OMO WENWEYO OLORUN ASHE BONI LAYE OMO MAYIRE AWO ENI IFA AWO LAYE OINA."]}]$q$::jsonb),
(179,'3b68009a82c40cc5ffef86f247a51b8f',$q$[{"titulo": "Idea central", "texto": "Ìká Ìrẹtẹ̀ habla de trabajar de manera autónoma: viene un trabajo o negocio nuevo que debe ser solo del consultante, sin socios ni compromisos, y triunfará. Pide ofrecer al padre, vivo o muerto, para que endulce su vida, y ofrendar para no perder sus cosas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa abrir un trabajo o negocio propio (relato de Awofusi).", "Una sociedad comercial le da desconfianza (relato de Atikarẹṣẹtẹ).", "Necesita confiar más en su capacidad.", "Su prosperidad está ligada a atender a su padre, vivo o fallecido."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un negocio propio que prospera.", "Encontrar y apretar en la mano todas las cosas buenas.", "Riqueza por intercesión del padre.", "Que sus pertenencias estén seguras y no se pierdan.", "Una vida dulce como la miel."]}, {"titulo": "Ibi y advertencias", "puntos": ["Asociarse o confiar en otros para el comercio.", "Perder sus cosas por descuido."]}, {"titulo": "Enseñanza principal", "texto": "El padre responde cuando se le ofrece miel. Quien trabaja solo y no confía sus negocios a nadie conserva lo que gana."}, {"titulo": "Relatos reunidos", "puntos": ["Òmùmùyín y la miel del padre. Òmùmùyín, hijo de Aṣéyìn, consultó y le dijeron que fuera a cavar un hoyo pequeño en la tierra, que echara en él sal y miel, que sostuviera un pollo encima e invocara el espíritu de su padre, que se pasara el pollo por todo el cuerpo y que lo matara sobre el hoyo: así todas sus cosas se endulzarían. Lo hizo. Su vida mejoró, le llegó la riqueza, y su padre se puso de su lado. Cantaba: nuestro padre acepta la miel y oímos su respuesta. Si el padre del consultante está vivo, debe llevarle un pollo vivo.", "Òtòtò Èyí, que no pierde nada. Òtòtò Èyí, hijo de Àgbọ̀nnìrègún, preguntó si podría guardar sus cosas de modo que no se perdieran. Le pidieron ofrendar, cumplió, y sus cosas nunca más se perdieron. La ropa del sacerdote se gasta en la rodilla de tanto arrodillarse a ofrecer, y la tela del curandero se rompe en el cuello de tanto luchar; pero lo que está bajo la mirada del ikin no se pierde.", "Awofusi. Ìká Ìrẹtẹ̀ adivinó para Awofusi y le dijo que adonde fuera encontraría todas las cosas buenas y las apretaría en sus manos. Le marcaron paloma, gallina, dinero y medicina de Ifá. Cumplió.", "Atikarẹṣẹtẹ y el comercio sin socios. A Atikarẹṣẹtẹ le aconsejaron no confiar en nadie y no asociarse con nadie para comerciar. Le marcaron una botella de miel, cuatro palomas, un pangolín y dinero. Ofreció, y su vida fue tan agradable como dulce es la miel."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el padre: hoyo con sal y miel, un pollo pasado por el cuerpo y sacrificado allí; si el padre vive, darle un pollo vivo.", "Para no perder las cosas: la ofrenda que marque Ifá.", "Para encontrar lo bueno: paloma, gallina, dinero y medicina de Ifá.", "Medicina: quemar una cabeza de serpiente con hojas de ojúùsájú y de ẹ̀ṣọ, molerlo y mezclarlo con jabón para bañarse.", "Para el comercio propio: una botella de miel, cuatro palomas, un pangolín y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "El espíritu del padre (los antepasados) endulza la vida. Ikin cuida las pertenencias. Àgbọ̀nnìrègún."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Miel, sal, ojúùsájú (Petiveria alliacea), ẹ̀ṣọ (Elytraria marginata), cabeza de serpiente, pangolín, jabón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 179.1 (yorùbá): Ìká-Ìrẹtẹ̀: / a difá fún Awofusi. / Wọ̀n ni: / \"Ibikibi ti Awofusi ba wa / ni ohun rere maamaa teelowg\". / Wọ̀n niki o rúbọ: / Eyẹlé, adiyẹ, ẹgbàá mẹfà owó ati ewé Ifá. / Ó gbọ̀ ó rú.", "Verso 179.2 (yorùbá): Ìká-Ìrẹtẹ̀: / a difá fún Atikarẹṣẹtẹ. / Wọ̀n niki Atikarẹṣẹtẹ / mamaa gbekele èniyan o, / kiomamaa ba ẹnikẹni da owò po o. / Wọ̀n niki o wa rúbọ: / Oyin (igo kan), ẹyẹlé mérin, / Aiká ati ẹgbàáwa owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Ayé Atikarẹṣẹtirẹ a dùn, / Tirimomo li airan'hin oyin\".", "REZO: IKA RETE OMO OLUCHE OMA ILEKE KIRI KIRI BANLA ABANIYE BATITU EURE, EYELE LEBO, KAFEREFUN SHANGO. OGUN ATI OLOFIN. MAFEREFUN YALORDE ATI OLOKUN.", "REZO: IKA RETE OMO OLUCHE OMA ILEKE KIRI KIRI BANLA ABANIYE BATITU EURE, EYELE LEBO, KAFEREFUN SHANGO. OGUN ATI OLOFIN. MAFEREFUN YALORDE ATI OLOKUN.", "REZO: IKA RETE IKA ERI AWO AVILE ALMOVA ORI SHANGO, IFA OWO MATUMBAO MAFARAWO KUMAOSA MONI IFA LOSHEERI OFINA YEYE AWO OMO NIRO IFA ODDUN LAYEO AWORI OFOYU AWO IFA LODUN BIFARUN UNTEFA AWO ODARA ADELE OTUN NI ADELE OSIN AWO OSIN ASHE WELE SHIWELE IFA LODUN KOMO LAYE ORO KANSUOKO AGBA INLE IFA OMA YENI AWO IFA LODUN ERA UNTEFA LODAFUN SHANGO KAFEREFUN ORUNMILA, OLOKUN OFO TOSHU ADELE OLAYE.", "REZO: IKA RETE IKA ERI AWO AVILE ALMOVA ORI SHANGO, IFA OWO MATUMBAO MAFARAWO KUMAOSA MONI IFA LOSHEERI OFINA YEYE AWO OMO NIRO IFA ODDUN LAYEO AWORI OFOYU AWO IFA LODUN BIFARUN UNTEFA AWO ODARA ADELE OTUN NI ADELE OSIN AWO OSIN ASHE WELE SHIWELE IFA LODUN KOMO LAYE ORO KANSUOKO AGBA INLE IFA OMA YENI AWO IFA LODUN ERA UNTEFA LODAFUN SHANGO KAFEREFUN ORUNMILA, OLOKUN OFO TOSHU ADELE OLAYE.", "REZO: IKA RETE OZAIN BAWE BIMOSHEKUN EYEBI SHERAWE OSHINSHIN OZAIN, OLOFIN OWADEWO OLOFIN OMO OSUNIMI EWE BELEKUN OZAIN OMO YEKUN ASHO FUN FUN OROLU AGBA KILE OLOFIN IKAWAYETE OMO OSHA IFA MAYEKUN OBORI NIFA AWO IKAWAYATE IKA EWE IRETE MOYUN IFA OLOFIN AYAKALE ERAN ARALOGUN OLOFIN GBOGBO OMO NIFA OSHE AIBOWOFUN AREWOSHE OZAIN AWO IKAWAYATE LODAFUN OZAIN KAFEREFUN OLOFIN.", "REZO: IKA RETE AWO EYA BOMU ADIFAFUN OLOFIN ATI SHANGO ONIDOLAYE AWO ORI MOBARE IKA RETE INISHE ENI EYIGBA OFEDE EYA ORUN, EYA ONIRE OBA ORUN AYAMORA KUENI OKUNI", "ELEYA BI EYA BASUN EYA MORA AFIYE SHANGO EBEYA NI EYA KUETO NI OSHE GBOGBO ONI TITUNDE EYA TITUN AWO INUN IRE YEMAYA ODADA AYE BABA BONI EGGUN ADEYA AWO LODAFUN ORUNMILA.", "REZO: IKA RETE OYA ABORI MESAN ADIFAFUN OBA KELETU EGGUN OLOYE OMODORUN INLE KIYA EFUFU LELE LOJUN ORUN OKAN NANI ABERE IKUBALELE OLUO POPO ABORI EGGUN SHANGO LOKO IYANZAN LAYA IKA RETE OSHA OYU AWO IFAROBI OSHE OBOLE IRE YEMAYA ALAKANI SHANGO OYA OYISHE OBINI SHANGO AKARAYE ORUN ONIFAYE LODAFUN ORUNMILA LODAFUN IGI."]}]$q$::jsonb),
(180,'d1f8e3efd4e3ebd2d65866c70943a5b1',$q$[{"titulo": "Idea central", "texto": "Ìká Ọ̀ṣẹ́ habla de revertir la pobreza y la mala suerte, que se agravan por cambios emocionales. Pide a la mujer atender y escuchar a su marido, y a la mujer separada no llevar a sus hijos a la casa de su padre por causa de los envidiosos. Promete que las fuerzas de la tierra se tragarán a quienes acusan falsamente."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca salir de una situación económica difícil (relato de Oṣikàlekà).", "Hay una acusación grave que debe comprobarse antes de repetirla (relato de Ọlabosipo).", "El enojo o las ganas de revancha están influyendo en decisiones de dinero.", "Hay una separación de pareja; volver no debe significar quedarse en una relación que hace daño."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Salir de la pobreza.", "Muchos hijos.", "Que el inocente acusado quede limpio y sus acusadores caigan.", "Que la mujer vuelva a la casa de su marido y no se estropee."]}, {"titulo": "Ibi y advertencias", "puntos": ["La terquedad de no escuchar a la pareja.", "Guardar venenos y malas medicinas.", "Envidiosos que no cambian aunque se les dé de todo.", "Ser acusado de algo que no hizo."]}, {"titulo": "Enseñanza principal", "texto": "La maldad trae pobreza. Al envidioso se le puede dar dinero, ropa, comida y sirvientes, y nunca dejará su maldad. Al falso acusador le llega su vengador, aunque tarde."}, {"titulo": "Relatos reunidos", "puntos": ["Oyèbóádé, la esposa que no escuchaba. Oyèbóádé era esposa de Ọ̀rúnmìlà. Él le habló y le habló de un asunto urgente, y ella no quiso escuchar; intentó corregirla, y ella no hizo caso; le pidió que estuviera atenta, y fue inútil. Ifá la encerró. Al cabo del tiempo, desde su encierro, Oyèbóádé cantaba con tristeza: el dedo roto, aplastado y torcido como la base del ìbílẹ̀ àkàká; Ọ̀rúnmìlà, por favor, suéltame; morir a espada es mejor que pasar hambre.", "La gallina madre al otro lado del mar. Àṣá n wéwé, el sacerdote de Ọmọdé, y Èṣù Pànàdà, que ejercía su sacerdocio sin recibir regalos, adivinaron para Òkòkó nìyèlè, la gallina madre, que vivía al otro lado del océano y lloraba por hijos. Le dijeron que tendría muchos, pero que no debía llevarlos a la casa de su padre, por los enemigos que la esperaban. Ofreció y tuvo muchos hijos. Pero quería mostrárselos a todos, y los malvados que viven junto a la laguna se los quitaron. A esos se les puede dar dinero, ropa, comida o sirvientes, y nunca aceptarán otra cosa que su maldad.", "Ọ̀ṣìkàlẹ̀kà y la pobreza. Ìká Ọ̀ṣẹ́ adivinó para Ọ̀ṣìkàlẹ̀kà y le dijo que sería muy pobre. Le marcaron seis palomas, abundante obì (kola), todos los venenos y malas medicinas que guardaba en la ciudad y en el campo, y medicina de Ifá. Se negó a entregarlos.", "Ọlábọ̀sípò, el acusado inocente. Todo el mundo veía a Ọlábọ̀sípò como un hombre malvado, aunque no había cometido ningún crimen. Le pidieron cáscaras de nuez de palma, nueve palomas, un gallo y dinero para que las fuerzas de la tierra se tragaran a sus enemigos. Ofreció. Después de mucho tiempo, el vengador tomó venganza de quienes lo acusaron falsamente."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la mujer: la ofrenda marcada y escuchar al marido.", "Para los hijos: la ofrenda, y no llevarlos a la casa del padre de la madre.", "Contra la pobreza: seis palomas, abundante obì y entregar los venenos y malas medicinas guardadas, con medicina de Ifá.", "Contra la falsa acusación: cáscaras de nuez de palma, nueve palomas, un gallo y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà corrige a su esposa. Èṣù Pànàdà como sacerdote. Las fuerzas de la tierra (Ilẹ̀) castigan al acusador."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Obì (nuez de kola), cáscaras de nuez de palma, palomas, gallo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 180.1 (yorùbá): İkáṣé, / İkáṣé: / a dífá fún Oṣikàlekà. / Wọ̀n ni: / \"İṣẹ a ṣẹ Oṣikàlekà li ayé\". / O ni: / kili ẹbọ ki iṣé ma le ṣé oun li aye? / Wọ̀n niki o rú: / Ẹyẹlé mẹ́fà, ọpọ́lọpọ̀ obi, gbogbo oògùn buburu / tiofi pamo sinu ilé tabi oko ati ewé Ifá. / Ô gbọ̀ ko ma rúbọ o.", "Verso 180.2 (yorùbá): Wọ̀n ndunrunmo koṣẹkoro, / Bopetiti Çlẹsan a maa san / fún àwọn Adunrunmo ni: / a difá fún Ọlabosipo / eni ayé nfi ojú Ìká wo. / Wọ̀n niki o wa rúbọ / ki ilẹ̀ le maa baa mu àwọn ọ̀tá rẹ̀. / Ebọ: Eesan (ekur0308), / eyẹlé mésàn, akuko adiyẹ ati ẹgbàásan owó. / Ô gbọ̀ ó rú.", "REZO: IKA SHE NINSHE IKA MIRU KIRI IKA MU KIRI ADIFAFUN ORUNMILA MIOPEYE OWUNKO, AGUTAN LEBO.", "REZO: IKA BELA LOMIKA ETONTO GOMOGO EWI ABUNKATO OSINTO OSIN IKA KOLOYU OBITA MOLOBU AKAKUNMBELE IKA BELA BOGBO ENIFA AWO LODAFUN IKU EMIRO KAFEREFUN EGGUN.", "REZO: IKA SHE NINSHE IKA MIRU KIRI IKA MU KIRI ADIFAFUN ORUNMILA MIOPEYE OWUNKO, AGUTAN LEBO.", "SUYERE: IKA KOLOJU IKA KOLOJU ADIFAFUN DADA AWO IFA IKA KOLOJU.", "REZO: IKA BELA LOMIKA ETONTO GOMOGO EWI ABUNKATO OSINTO OSIN IKA KOLOYU OBITA MOLOBU AKAKUNMBELE IKA BELA BOGBO ENIFA AWO LODAFUN IKU EMIRO KAFEREFUN EGGUN. EBBO: AKUKO, EYELE , OU DUN DUN, PUPUA ATI FUN FUN, MEDIDAS DE LOS CINCO DEDOS DE LA MANO DERECHA Y DEL PIE DERECHO Y GBOGBO TENUNYEN.", "SUYERE: IKA KOLOJU IKA KOLOJU ADIFAFUN DADA AWO IFA IKA KOLOJU."]}]$q$::jsonb),
(181,'1ea9a8fcf868b67c23576eabc9fea294',$q$[{"titulo": "Idea central", "texto": "Ìká Òfún dice que hay que dar para recibir: quien no hace nada por su propio bien no debe esperar nada de los demás. Viene un regalo o un ascenso, pero sin ofrenda llega poco o nada. Ayuda a cobrar deudas y a vencer el miedo de reclamar lo propio. Pide disciplina y que la pareja no se quede mirando desgracias en la calle por un tiempo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera un ascenso, un regalo o un beneficio sin haber hecho su parte (relato de la tortuga).", "Quiere cobrar una deuda.", "Le cuesta pedir afecto y teme decepcionarse.", "Pregunta si podrá conservar lo que ha recibido (relato de Dèndèré)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un regalo, un ascenso o una posición ventajosa.", "Cobrar lo que le deben.", "Muchos hijos, como las estrellas alrededor de la luna.", "Que la cabeza y Dios lo ayuden.", "Que el que lo estafó sea atrapado y devuelto."]}, {"titulo": "Ibi y advertencias", "puntos": ["Esperar sin haber dado nada.", "Miedo a reclamar lo que le pertenece.", "Indisciplina que se vuelve daño propio.", "Ser espectador de desgracias en la calle."]}, {"titulo": "Enseñanza principal", "texto": "Sea firme o floja la cabeza de uno, es la propia cabeza la que da la buena fortuna. El que huye de su compromiso termina atrapado por la música que más le gusta."}, {"titulo": "Relatos reunidos", "puntos": ["Dèndèrè, la madre de la luna. Dèndèrè, la madre de la luna creciente, preguntó si vería todas las cosas buenas y si se quedarían con ella. Le pidieron ofrendar y cuidar de la tierra. Ofreció, y todas las estrellas se quedaron alrededor de la luna, todas las buenas cosas se quedaron con ella, y regresó de su viaje cargando muchos hijos.", "El cocodrilo y el tambor de Èṣù. El cocodrilo era amigo íntimo de Òòṣà. Òòṣà le aconsejó una y otra vez que fuera disciplinado, y no quiso oír. Un día se enojó, dejó a Òòṣà y se fue a la casa de Olókun, a gozar en el agua. Òòṣà preguntó cómo podría atrapar a ese cocodrilo que lo había burlado. Le pidieron dos chivos; los ofreció, con la piel hicieron un tambor y la ofrenda se le dio a Èṣù. Èṣù tomó una soga, un piano de pulgar y el tambor, llegó a la orilla, preparó el lazo y se puso a tocar y a cantar: cocodrilo, hijo de Olókun, ven a bailar a mi música, muévete en pasitos cortos, ìgbandúrúkú. El cocodrilo oyó la melodía, le gustó y vino nadando rápido hacia la orilla. Cuando salió a la playa a bailar, Èṣù le echó el lazo. Así fue como empezaron a amarrar a los cocodrilos.", "La tortuga y el regalo. Ìká Òfún adivinó para la tortuga, a la que estaba por llegar un gran regalo, y le marcaron diez palomas, dinero y medicina de Ifá. La tortuga no ofreció, y el regalo no llegó: el que no hace nada para su bien no debe recibir nada de los demás.", "La tortuga y sus deudores. Ìká Òfún adivinó otra vez para la tortuga, que quería que le pagaran lo que le debían. Le marcaron paloma, dinero y medicina de Ifá, y así cobró."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la buena fortuna: la ofrenda marcada.", "Para atrapar al estafador: dos chivos; la piel para un tambor y la ofrenda a Èṣù.", "Una soga trenzada.", "Para recibir el regalo: diez palomas, dinero y medicina de Ifá.", "Para cobrar deudas: paloma, dinero y medicina de Ifá.", "Medicina: quemar hojas blancas de èèsin con pimienta de Guinea, guardar el polvo en un àdó cubierto con tela jaspeada y marcarse la frente al ir a cobrar."]}, {"titulo": "Relaciones espirituales", "texto": "Òòṣà y su amigo el cocodrilo. Èṣù atrapa al que huye. Olókun, dueño del mar. Orí y Olódùmarè ayudan al consultante."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Èèsin (Urera mannii, Mucuna pruriens), pimienta de Guinea, piel de chivo, soga, tela jaspeada."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 181.1 (yorùbá): Ìká-Fú: / a difá fún Ọlobahun İjapá, / Wọ̀n niki Ọlobahun İjapá rú: / Eyẹlé mẹwà, egbẹwa owó ati ewé Ifá, / kiwọn baa le maamu ebun (nlá) / wa fun un. / O kọ ko rú. / Wọ̀n ni: / Ṣniti komu (ohun) towọ rè / wa kiiri t'ẹni gba s'ọwọ.", "Verso 181.2 (yorùbá): Ìká-Fú: / a dífá fún Ọlobahun ljapá. / Wọ̀n niki Ọlobahun wa rúbọ / kiobaa le ri owó gba lowo / àwọ̀n tiojẹẹ ni'gbese. / Ẹbọ: Eyẹlé, egbèwá owó ati ewé Ifá", "REZO: IKA FUN LORONI KIYATE ADIFAFUN ABIREGUN AKUKO EYELE LEBO KAFEREFUN OBATALA.", "REZO: IKA FUN LORONI KIYATE ADIFAFUN ABIREGUN AKUKO EYELE LEBO KAFEREFUN OBATALA.", "REZO: IKA FUN ADIFAFUN ESHU LORUGBO OUNKO LAYE KAFURETE VILE ADIFAFUN OBATALA.", "REZO: ONIRE IFA GUI. KAFEREFUN YALORDE, ESHU, ORUNLA, YANZA Y OBATALA.", "REZO: IFANI KAFEREFUN OLOFIN. KAFEREFUN ALA, ELEGBA, ORUNMILA, OGGUN.", "REZO: IKA FUN KAFUN ONI BABALAWO, ADIFAFUN EDU, OWOYI ELESE ILU OMO ANIKE EDU KONIGBO ABEN IÑA IFA EYELE ELEGBO.", "REZO: BIFUN BOBORONI IFA KAFEREFUN OZAIN IKA MAFUNBO ONI OYI OYI OLLA ILEFUN WA ENI LE ONILE IKA ADIFAFUN ORUNMILA, AROYO IFA ONI OSHUN AWO OBBALOSO OLLA KAFEREFUN AFEFE.", "REZO: IKA FUN ADIFAFUN ESHU LORUGBO OUNKO LAYE KAFURETE VILE ADIFAFUN OBATALA.", "REZO: ONIRE IFA GUI. KAFEREFUN YALORDE, ESHU, ORUNLA, YANZA Y OBATALA.", "REZO: IFANI KAFEREFUN OLOFIN. KAFEREFUN ALA, ELEGBA, ORUNMILA, OGGUN.", "REZO: IKA FUN ADIFAFUN ESHU LORUGBO OUNKO LAYE KAFURETE VILE ADIFAFUN OBATALA.", "REZO: IKA FUN KAFUN ONI BABALAWO, ADIFAFUN EDU, OWOYI ELESE ILU OMO ANIKE EDU KONIGBO ABEN IÑA IFA EYELE LEBO.", "REZO: BIFUN BOBORONI IFA KAFEREFUN OZAIN IKA MAFUNBO ONI OYI OYI OLLA ILEFUN WA ENI LE ONILE IKA ADIFAFUN ORUNMILA, AROYO IFA ONI OSHUN AWO OBBALOSO OLLA KAFEREFUN AFEFE.", "+++"]}]$q$::jsonb),
(182,'af0198ff5d9853d1e3e12d97c3f58384',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ogbè anuncia dificultades en el hogar causadas por los hijos: un hijo puede verse metido en problemas por algo que no hizo, o por su propia osadía. Es buen momento para reflexionar, pensar y concebir ideas. Si el hijo no ofrenda, la madre debe hacerlo por él."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La familia ve riesgos en lo que hace un hijo (relato del joven acróbata).", "Hay tensión en casa y conviene hablar antes de que crezca.", "Una relación lo tiene confundido."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que el inocente sea liberado y premiado.", "Tiempo propicio para pensar y formar ideas."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un hijo culpado injustamente.", "Lucirse con una habilidad y quedar como sospechoso.", "Hijos que no escuchan la advertencia."]}, {"titulo": "Enseñanza principal", "texto": "No se mete la cabeza del palo en el fuego ni se habla con la boca llena de espinas. La habilidad que se exhibe sin cuidado puede convertirse en prueba en contra. Lo que el hijo no hace, la madre lo cumple."}, {"titulo": "Relatos reunidos", "puntos": ["El acróbata de la casa de Ọlọ́fin. Un muchacho de la casa de Ọlọ́fin era un acróbata famoso. Le advirtieron que se veía venir un problema y le pidieron dos gallos, dinero y una cuerda. No ofreció. Por esos días alguien entró al cuarto de la esposa de Ọlọ́fin y se acostó con ella, y Ọlọ́fin no entendía cómo alguien se había atrevido si el cuarto tenía una sola puerta. Investigó y no descubrió nada. Entonces reunió a todo el pueblo y ofreció dinero y un chivo a quien lograra saltar su muro y entrar en la casa. Muchos lo intentaron y fallaron; el muchacho acróbata saltó con facilidad. Ọlọ́fin lo atrapó, lo amarró y lo presentó como el culpable. La madre del muchacho, al saberlo, corrió a ofrecer lo que su hijo no había querido. En cuanto terminó, Èṣù puso estas palabras en la boca de uno de los hijos de Ọlọ́fin: tú, Ọlọ́fin, fuiste el que se acostó con tu esposa; ¿cómo vas a amarrar al hijo de otro para matarlo? Ọlọ́fin desató al muchacho y le entregó el dinero y el chivo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Dos gallos, dinero y una cuerda; si el hijo no lo hace, lo ofrece la madre."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù habla por boca de otro para salvar al inocente. Ọlọ́fin."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Gallos, cuerda."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 182.1 (yorùbá): Do'nidoni-o-gbọdo f'orí-okó-ba-iná, / Osgrọ-o-gbọdoyi-wọ'nu-egun-sorọ, / O jopurutuparataniilemokuro-l'alẹde: / o daa fomo ilé Ọlọ̀fin / Atakiti-gba-ẹgbẹwa. / Wọ̀n ni: / \"Ọrọ kan'dasinu\", / nitorinaa ki ó rú: / Akuko-adiyẹ Méjì, egbẹfa owó / ati okun ijara li ebo. / Ó gbọ̀ ebọ sùgbọ̀n ko rúbọ. / lyá ọmọ naa lio lọ rúbọ naa / nigbati ràn de ba ọmọ rẹ.", "REZO: OTROPUN BEKONWA APUPA ADIFAFUN SHANGO KUKUTO KUKU ADIFAFUN ALUN OLOYE TINSHOMA OLOFIN EYELE LEBO. ADIFAFUN IBAN AYAPA AKUKO LEBO. KUAGEFE LELE KOFELE ADO YU OMIGUN ADIFAFUN RERE AWO EURE LEBO, EYELE LEBO. GODO GODO MUA MOFIN KAYA MOFIN KAYA MOFIN KAYA.", "“yo me toco el pecho por shango como el se lo toco por mi”", "REZO: APUPA APALA ADIFAFUN SHANGO KUKUTE KUKU ADIFAFUN ALULOLOYE TINCHOMA OLOFIN EYELE LEBO ADIFAFUN IBAN AYAPA AKUKO LEBO ORUNMILA FEFE LELE KOFELE ADOLLU OMIQUI ADIFAFUN RERE AQUE LEBO EYELE LEBO ABO. OTRUPO OGBE PONLA SE SESE.", "REZO: APUPAPALA ADIFAFUN SHANGO KUKUTE KUKU ADIFAFUN ALU OLOLOYE TINCHOMA OLOFIN EYELE LEBO ADIFAFUN IBAN AYAPA AKUKO LEBO OBE LOBE OGGUN NIAFEFE LELE COFELE ODOYU OMIKI ADIFAFUN RERE AGUE EURE EYELE LEBO ABO. OTRUPO OGBE PONLA SE SESE.", "SUYERE: “ KOKO AGBANI SOKUT KOKO”.", "REZO AL TAMBOR PARA PRESENTAR: AÑA IGI TODOWO AÑA OGA ILU PITIN SHOWO ONIBARA BEYEGBE ONI BEYEGBE OKAN AÑA IBORU, OKAN AÑA IBOYA, OKAN AÑA IBOSHISHE OMO LAKIYO IFA LASHE ONI TEMU TERE OMU BARA, ONI BARA, ONI BARA BEYEGBE AYUGBA OSAWO IWORIWO OBINI IKU. AYUGBA LA DUKUE FOL ONI MODI AYUGBA OBA, AYUGBA ARUN, AYUGBA GBOGBO OLUWO OLUFA ITON BENISALE KOMAYEPO KOMAYEPO KOMAWAO WAYEWE OLOFIN OGBE EKUE BURUKU KOLOYUE.", "SUYERE: KOKO AWANI SOKUT KOKO.", "REZO: ABONIESHIO ONINABILEO NIBE NIBE ONI OLUWO NI OLE OBADE ABAKAN ALA MEYI ABO AUN ADOKO ABO UNSHINSHE OBA", "YEUN YARDRIDI DIESAYE ABO MOTIGUI AKOREDA OLORO DODIESON MAYE MAYE ESUE GUEN MUSHI OBANIKE SHILEKUN ERUN OBA NULETI KULUKULU ASISI MIGUINI.", "REZO: ADAFAN BAUNLLAPA COUBO (AKUKO ETU OBI ORI EFUN ABAN OWO LA MEFA) BERU OBEUN OLEN FIRUBO OLOBELOFIN APAGUN OLOSOCO ORI BUN OLON OPAGUA OBADIDE AUN OSARE BANLAO TESEFUNOUN ALLA QUNGUN MALLA AUN GUN OLOQUO IBA OLESE OPADE DURO OBADE ETUSOLO AUN SALO DIEBO ONI ORUBO ONICHARO TIENE QUE OBORI.", "REZO: ADIFAFUN AWO ARERE NI AWO OLUWOYERE OBA AKABABA INLE NI ISOWI EMIYEYE KUMBEWA YALORDE OBINI BURUKU SHOLA NI IGUI ABAILA ESHU ALESHUYADE OBOYUTE MOWA LELE OTRUPO BEKONWA EGUNGUN BABRI NI SHANGO LABE LERI OFO NI UNLO AYERE YEMAYA INLE NI AKARABA INLE LODAFUN ORUNMILA KAFEREFUN EGGUN KAFEREFUN SHANGO KAFEREFUN ESHU.", "REZO: ADIFAFUN ORUMBOTI AWO TINSHAWO YOBI NI ESHU LALU ORISHAOKO OBARA NIREGUN IGUI ARAGBA WAYEMI ORUN ABOROTELA ODEDE ORUN EGGUN AFEFE LAYE OMO ORISHAOKO OMO OLOFIN ODARA SHANGO IRONKO LAYE EGGUN MOWA YA DE MOWAYE IMAWOLORISHA OBIRIKITI LEWOLE KOSIARETO BABAMI ILE ONA BOGBO ORISHA EWE LELE SHANGO MOKULAYE UMBO ILE OFE OFEKUAN ORISHAOKO OSODE AWO FUSI ODO BABA OGODO OBA WAMALE OSHA LODAFUN ORISHAOKO.", "REZO: AWO ITANA IYA OKETE ENI TOKU IMOYO KOMURE OYO ÑAÑA TORI BORU LAYE INLE OMO OYU OKUN AYE MALOKUO EKETE BAYI NIWARU OBA IFA NILE OTRUPO OMA IFA ADIFAFUN PODA ADIFAFUN FESE KOTO ILU ENI TOBASHE OMO IFA NIREFUN ADE ILU GBOGBO IMOYO AFE EKUTE BARATIYE OTRUPON OGBE AWO POLA EGGUN OMO IFA OMO OLOFIN BEKE LONE EÑAJUN OKAN ORIMI", "AFERE ASAKALEKE AWANI MOYUGBA AWO ILU IBAMI OMATUN OMA ESE ILU, ABAMISHE FUMI OMO OMONIMI ADIFAFUN OLOFIN ADIFAFUN ILU.", "REZO: OBA ALAÑA OLOSA IYIN ONI SHANGO MORI ASHIRI EBURA OBANIADA OFO EDUN ARA OBE ODO ATI ARA ILU OBANI LE ORUN ONI SHANGO IKU INSORO ANA IKU LODAFUN AÑA KAFEREFUN ORUNMILA.", "SUYERE: OBANIKU OBANIKU ARA ILU UNSORO."]}]$q$::jsonb),
(183,'e9a94f24aa70264d751f3faf7af537bf',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ọ̀yẹ̀kú habla de quien sacrificó su alegría persiguiendo el dinero: la firmeza en los negocios lo ha alejado de la familia y lo tiene solo. Pide abrir la casa, compartir comida y juego con la gente y con los niños para espantar la tristeza y la muerte."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Trabaja por dinero y se ha alejado de su familia y sus amigos.", "Tiene recursos, pero se siente solo o con nostalgia (relato del hombre rico sin alegría).", "Necesita tiempo para jugar y convivir."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Recuperar la alegría y el placer de vivir.", "Acercarse de nuevo a la familia.", "Alejar la tristeza y la muerte."]}, {"titulo": "Ibi y advertencias", "puntos": ["Riqueza sin gozo.", "Aislamiento, soledad y nostalgia.", "Tristeza que llama a la muerte."]}, {"titulo": "Enseñanza principal", "texto": "El dinero no sirve si no se disfruta con otros. Jugando con los niños uno encuentra la alegría."}, {"titulo": "Relatos reunidos", "puntos": ["El rico sin alegría y el juego de ayò. Òkèbẹ̀ẹ̀bẹ̀ẹ̀, el adivino del mundo, adivinó para el mundo y para los niños, y dijo que todos debían jugar siempre al ayò, porque jugando con los niños uno disfruta la alegría. Después adivinó para un hombre rico que no tenía placer, diversión ni felicidad. Le pidió una calabaza de ñame machacado, un plato de sopa, otras comidas y golosinas, dinero y las semillas de su tablero de ayò, y que invitara a la gente a una fiesta en su casa para jugar con él. Así espantaría su tristeza, su aflicción y la muerte."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Una calabaza de ñame machacado, un plato de sopa (de pescado àwó), otras comidas y golosinas, dinero y las semillas del tablero de ayò; hacer una fiesta y jugar con la gente."]}, {"titulo": "Relaciones espirituales", "texto": "Los niños y la comunidad devuelven la alegría."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame machacado, pescado àwó seco, semillas de ayò."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 183.1 (yorùbá): Okebẹebẹẹ Awo Aye / li o difáá f'Ayé, / ó dífá f'omodé. / Wọ̀n ni: \"Ere li ao maa ba omo-ayo ṣe. / Biaba nba omodé ṣere a maa fi ayọ̀ / inú rẹ̀ ran'ni. / A dífá f'Onilé-owó ti ko ni idunnú. / Wọ̀n niki ó wa rubo: / Igbá-iyán, awo-obe, oniruuruu ounje, / egbàá méjilá owó pẹlu ayo ninu qpọ̀n. / Ki gbogbo èniyàn maa wa ba q jẹun, / ki wọn maa ba ọ ta ayo ni ilé rè / bi a wipe ki ibànújé rẹ le tan, / ki o ma ba kú.", "REZO: OTRUPON YEKU OYEKUKE IKU YEYE ADIFAFUN IROKO.", "REZO: OTRUPO YEKUN OTRUPON YEKU YEKU YEKU YEKU YEKU YEKUIDI AKOKO ORDIFA OCHACO TOLOSILE ORUBO EYELE ABENEFANECU EYA EPO EBETA OWO.", "REZO: EÑA EÑA QUIÑA ADIFAFUN COLE TINTO IBOMECAN ABO LEBO OCHUBULORIGUO ADIFAFUN OLU BIYI EYELE LEBO AKUKO OWUNKO LEBO.", "REZO: AKUKO ODIFA SHAOKO TOBO SILE AKUKO EYELE AIBONCHA CASCARA DE MANI, KAFEREFUN SHANGO, OBATALA Y OGGUN.", "REZO: OTRUPO YEKUN OTROKON YEKUN YEKU YEKU IDI AKUKO O ORDIFA OCHA OKOTO LOSILEORABO EYELE ABANEFAN EKU EYA EPO EBEFA OWO.", "REZO: EÑA EÑA QUINA ADIFAFUN KOLE TINLO IBOMECANABO LEBO OCHU BULORIGUE ADIFAFUN OLU BILLI EYELE LEBO AKUKO LEBO.", "REZO: AKUKO EDI FA CHACO TOBOSILE AKUKO EYELE AIBONCHA CASCARA DE MANI KAFEREFUN SHANGO OBATALA Y OGGUN.", "REZO: OTRUPON OYEKUN BATUTO BABA OSHERI BAGUA ABORI ABINI NI OBINI QUEYERE QUE NI LEKUN NI OZUN OKUNI AGUAMIRE OBINI ALELE YEYENI AWO AWO BEYEKUN O BOGUANIRE AWO OBANI IRA ILE BORIBOGARA ABINI AWO ABORAR MARQUERE EÑI OSUN FATETI AWO IFA KAFEREFUN OYA, SHANGO, OZAIN, ELEGBA.", "REZO: OTRUPO YEKU OTRUPO YEKU IBI ACESO ORDIFA ECHASO OKATOLO SILERUBO EYELE ABANEFAN EKU EYA EÑEKIÑA ADIFAFUN KULE TIALO IBOMEKALO LEBO SEBO SELERI ADIFAFUN LUE BIYI EYELELE LEBO ADIE FA SHAOKO", "TOBOSILE AKUKO CASCARA DE MANI KAFEREFUN SHANGO OBATALA ATI OGGUN."]}]$q$::jsonb),
(184,'9631404d859a9b79dd34e71891f6fec9',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ìwòrì habla de la desgracia y la muerte que llegan por no hacer la ofrenda indicada. El consultante está demasiado preocupado por un hijo o un negocio nuevo. Pide escuchar el consejo práctico, porque el arrepentimiento siempre llega al final."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está muy preocupado por un hijo o por un negocio nuevo (relato del maíz).", "Va a empezar algo y debe escoger bien sus herramientas (relato del plato de barro en el río).", "Si es la salud de un niño, conviene llevarlo al médico."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Parto seguro y saludable.", "Hijos unidos que no le quitan."]}, {"titulo": "Ibi y advertencias", "puntos": ["Ignorar un consejo sencillo y pagarlo caro.", "Accidentes en el agua.", "Perder parte de los hijos."]}, {"titulo": "Enseñanza principal", "texto": "El arrepentimiento siempre llega detrás. Lo que flota se usa para sacar agua; lo que se hunde arrastra al que intenta rescatarlo."}, {"titulo": "Relatos reunidos", "puntos": ["La gente de Òtù Ifẹ̀ y el plato de barro. La gente de Òtù Ifẹ̀ iba a ir al río por agua llevando un plato de barro. Los adivinos les dijeron que era mejor usar una calabaza, porque flota, y no un plato de barro, porque se hunde. No hicieron caso. Mientras recogían agua a uno se le cayó el plato; quiso agarrarlo mientras se hundía, cayó al río y se ahogó. Dijeron: si hubiéramos traído una calabaza, no se habría hundido. Desde ese día se usa la calabaza para sacar agua del río. Si hubieran ofrecido dieciséis caracoles, dinero y medicina de Ifá, no habrían pasado esa pena.", "El maíz y sus hijos. A Àgbàdo, el maíz, le pidieron una paloma, dinero, una faja y medicina de Ifá para que su parto fuera seguro y para que sus hijos se mantuvieran juntos y nadie se llevara a ninguno. No ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la desgracia: dieciséis caracoles, dinero y medicina de Ifá.", "Medicina: hojas de ẹ̀ṣọ cocidas en sopa con la carne de un caracol para comer; o en infusión con el líquido del caracol, para bañarse y frotarse el cuerpo, y así evitar hacer algo que luego se lamente.", "Para el parto y los hijos: una paloma, dinero, una faja (ọ̀já ìkalẹ̀) y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá aconseja lo práctico; desobedecerlo trae pena."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀ṣọ (Elytraria marginata), calabaza, maíz, caracoles, faja."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 184.1 (yorùbá): Àbámọ̀ ni ngbẹ̀hin ràn, / Igbá li a nmu re eri, / Akimu-àwo-re-ẹri: / li a dá fún wọn ni Otù-lfè / nijọ ti wọ̀n maa mu àwo re eri. / Wọ̀n ni: / Igbá niki a mu lọ, àwo a ri. / Wọ̀n ko fẹẹ gbọ. / Wọ̀n mu àwo lọ, / wọn de eri bi wọn ti nọ̀n omi, / àwo bọ l'owọ wọn sinu omi. / Bi eni naa ti àwo bọ lọwọ rẹ / ti njijadu pe ki oun le muu, / òun naa bọ sinu omi. / O mu omi yo o si kú nipa ewu yi. / Wọ̀n nì: / ha! A ba mọ̀ kiamu igbá ree pòn omi. / Lati ojọ naa ni a ti nmu / igbá lọ pọ̀n omi wa o. / Ibaṣepe wọ̀n rú: / Igbín mẹrindilógún, / egàásan owó ati ewé Ifá, / wọn ki ba tiṣe ohun àbámọ̀. / Nitorinaa bi wọ̀n ba rúbọ / ki a ṣe ewé Ifá yi fún wọn.", "Verso 184.2 (yorùbá): Agberupòn: / a difa fún àgbàdo. / Wọ̀n niki àgbàdo wa rúbọ, / kio baa le sọ omọ / ti oun yoo pòn kalẹ li alaifi arapa / ati aikú pẹlu. / Ebọ: Ṣyẹlé, egberindilógún owó, / qja-ikalẹ ati ewé Ifá. / Ó gbọ̀ ko rú.", "REZO: OTRUPO ADAWENE FUN ALABE TISAYE AWO IPOMEGA GUIDA MEFA ADIFAFUN BABA OLOYO LEBO EYELE AKUKO LEBO. OTRUPON WORI IRE ADAKINO ADIFAFUN IWORI IRE ADAKINO.", "REZO: OTRUPON DAQUENE COLLO BABA EYAYE OGGUN LOGUO OGGUN MOPO LOPO CUCU ADIE FUN FUN ALABE TISALLO OBANICU ARE ECURU EYELE LEBO ABEYO OWO IPO MEFA GUIDA MEFA ADIFAFUN BABA OLOYO AKUKO LEBO EYELE LEBO. OTRUPAN WORI IFA HERDOQUINO.", "REZO: OTRUPON DAQUEÑE COLLO BABA EYELE OGUN LOGUO OGGUN LOPO KUKU ADIE FUN FUN ALABE TISALLO OBANIGUARE EKURE EYELE LEBO ELLO OBA NIKU ARE EKURE EYELE LEBO EBEYO OWO IPO MOFA GUIDA MEFA ADIFAFUN BABA OLOLLO EUKO LEBO AUKO LEBO. MAFEREFUN WORI IFA ADAQUINO. ADIFAFUN OYA DELLERE LLO OBARI GUA ORO OGUN LOGUO.", "SUYERE DE OPARALDO: “OYA LELE ORAN SARAYENYE OYA LELE OUN OBBUN IKU UNLO”.", "REZO: OTRUPON ADAWEÑE IYAFIN IKU OSHA EWE MADE MAYO OMO OBATALA OBANLA LAYE OLOFIN MAYO OKABEYAWO ODUDUWA AWO EYO OBANI IKU OMO ALAWARA OMO DOYE MESAN LEBO. UNYEN OBI LELE IKU ADIE ITANA OYA ILEKE LELEO BORI LELEO ILEKE BOWASHE ADIFAFUN DOYE IFA NI KAFEREFUN ANSAN."]}]$q$::jsonb),
(185,'25bd82f0926b58f0ed1eb73f19ad825e',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ìdí habla de una persona que anda a la deriva en lo espiritual y necesita renovarse. Está demasiado encerrada en sí misma y sufre por eso. Pide quitarse el velo de oscuridad, mirar con respeto al cielo y no quejarse de todo, para que el bien que uno hace no sea recordado como mal."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está retraído y le cuesta convivir con otros.", "Necesita renovarse en lo personal o lo espiritual.", "Siente que malinterpretan sus buenas acciones."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Renovación espiritual.", "Que se aparte el velo de oscuridad.", "Que el bien que hace sea reconocido como bien.", "Bendiciones que bajan del cielo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Ensimismamiento y aislamiento.", "Quejarse de todo y de todos.", "Dudar de lo que llama a uno desde lo alto."]}, {"titulo": "Enseñanza principal", "texto": "Ninguna madre llama a su hijo para hacerlo sufrir. El que hoy se queja de uno, mañana se quejará de otro: el quejoso no queda conforme con nada."}, {"titulo": "Relatos reunidos", "puntos": ["El llamado de Odùduwà. El mundo es hermoso y el cielo es magnífico. Odùduwà pidió a la gente del mundo que regresara a él para volver a nacer. Los niños se negaron, y también los mayores, porque decían que no es fácil ir al cielo y volver. Ọ̀rúnmìlà les dijo que el cielo es bueno, que es la casa de la belleza, que Odùduwà nunca viviría en un lugar despreciable y que a Òrìṣà siempre se le encuentra en lugares decentes; quien es llamado debe responder, porque ninguna madre llama a su hijo para que sufra. Aun así la gente dudaba. Les pidieron ofrecer dieciséis pedazos de ẹfun, una tela blanca, dinero y medicina de Ifá para que se les quitara el velo de oscuridad, mirar con respeto al cielo mientras trabajaban y abstenerse de la sangre. No ofrecieron.", "Ẹ̀là y su cuerda. Hoy te quejas de que Òtúrúpọ̀n Ìdí tiene la culpa; mañana te quejarás de que Ẹ̀là no gobierna bien el mundo. Ẹ̀là hizo al odúndún rey de todas las hojas y al tẹ̀tẹ̀ su delegado, y aun así la gente seguía quejándose. Al final, Ẹ̀là extendió su cuerda y subió al cielo. Ahora le piden: Ẹ̀là, extiende tu cuerda y baja a recibir tus bendiciones. Se ofrecen una paloma y pescado ahumado para que lo bueno que uno hace en el mundo no sea recordado como malo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para quitar la oscuridad: dieciséis pedazos de ẹfun, una tela blanca, dinero y medicina de Ifá; abstenerse de la sangre.", "Para que se reconozca el bien: una paloma, pescado ahumado y medicina de Ifá.", "Medicina: hojas de oriji machacadas con jabón, para lavarse después de la ofrenda."]}, {"titulo": "Relaciones espirituales", "texto": "Odùduwà llama a los suyos. Ọ̀rúnmìlà explica la belleza del cielo. Ẹ̀là, que sube y baja por su cuerda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹfun, tela blanca, odúndún (Kalanchoe), tẹ̀tẹ̀ (amaranto), oriji, pescado ahumado, jabón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 185.1 (yorùbá): Ilé ayé dára. / Orun ma sunwọ̀n o. / Oduduà niki àwọn ọmọ aráyé / maa padawa ki oun maa tún wọn ṣe. / Ọmode ni oun ko lọ. / Agbàlagbà ni oun ko lọ. / A ni: Eetiri? / Wọ̀n ni: / Orun ko ya re'bọ àwọn iba maa lọ. / Ọ̀rúnmìlà I: orun dára. / I: orun ni ilé ewà. / Odùduà ko jẹ gbe ibi ti ko sunwọ̀n. / Ibi rere li aiba Oriṣà. / Eni a ba pe kiojẹ ipe. / Abiamo ki ipe omo wa j'oro. / Sibẹsibẹ omọ aráyé nkọ'di / A niki wọn rúbo / ki òkùnkùn le ka kuro loju wọn. / Bi ẹba nṣiṣe ki ẹ le maa wo orun. / Efun mẹrindilogún, aṣo funfun, / egbaawa owó ati ewé lfa. / Bi eba rúbọ tan / ki ẹ ma dẹ sunmo'tosi ejẹ. / Wọ̀n ko rúbọ.", "Verso 185.2 (yorùbá): Òni ẹ wijọ, / ẹ ni Òtúrúpọ̀n'Dí li o jẹbi. / Ọla ẹ wijo / ẹ ni Elà koṣe ayé rere. / O m'ọ̀dúndún ṣe oba ewé. / O mu tetẹ ṣe osorun rẹ. / Ṣibẹṣibẹ e nwipe Ẹlà koṣeayé rere. / Aṣehinwa-asẹhinbo / Elà ta okun o re ọ̀run. / Njẹ Ẹ̀là takun wa kiowagb'ure, Ṣlà! / Ebọ: eyẹlé, eja-aaro ati ewé Ifá, / Ki àwọn omọ aráyé male / pe iwà rere rẹ ninu ayé ni ibi.", "REZO: OTRUPON DI TAYEEN NINS HAWE AYE NI KANLE KEME ADIFAFUN OYEKE ARERE ADIE LEBO, AKUKO LEBO, ADIFAFUN ORUNMILA, AKUKO, EÑI ADIE, ABO LEBO. OTRUPON DI IFA KEYE LE NINSHAWO AYE NI KINI AUN EYE ASIE EYEKO ABEBOADIE, ABOTA EWE LEBO. ARIRNI ELESAKAN OGUN.", "REZO: KALLEUN NINCHAGUO ELLE NI CANLE COMO ADIFAFUN OLLOCO EYELE ADIE LEBO AKUKO ADIFAFUN ORUNMILA OUNKO ADIE ABO OUNKO LEBO.", "REZO: OTRUPO DI IFA CALLO LENINCHAGUO ALLE NI QUINI A OLLE ASIA OLLOCO ABEBOARDIE EBETA OWO OWO. ARINI ELESECAN OGGUN."]}]$q$::jsonb),
(186,'a1d155831cfc1bdfe3b5efcd63de8928',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ìrosùn advierte contra los pleitos y la falta de armonía en la pareja y en la familia. Llama a cuidar las relaciones íntimas y a hablar más con la pareja. Promete paz en el matrimonio e hijos y nietos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La pareja discute seguido (relato de Delumo).", "Quiere recuperar la calma hablando.", "Pregunta por el futuro de un matrimonio y de los hijos (relato de Òtúrúpọ̀n e Ìrosùn)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Paz con la pareja.", "Muchos hijos y nietos por el matrimonio."]}, {"titulo": "Ibi y advertencias", "puntos": ["Alboroto y discusiones en la casa.", "Falta de comunicación con la pareja."]}, {"titulo": "Enseñanza principal", "texto": "Dos caracoles nunca se pelean. La calma y la suavidad sostienen el matrimonio."}, {"titulo": "Relatos reunidos", "puntos": ["Délùmọ̀ y su esposo. Òtúrúpọ̀n Ìrosùn, el alboroto se escucha: así adivinaron para Délùmọ̀. Le dijeron que su esposo podía molestarla, pero que si ofrecía, él le traería paz. Le marcaron dos caracoles y dinero. Ofreció, y se dijo: dos caracoles nunca se enfrentan.", "Òtúrúpọ̀n se casa con Ìrosùn. Èṣùrú, el adivino del bien, adivinó para Òtúrúpọ̀n cuando iba a casarse con Ìrosùn, y le aseguró que tendría muchos hijos y nietos de ese matrimonio. Le marcaron muchas nueces de kola, una gallina y dinero. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la paz en pareja: dos caracoles y dinero.", "Para hijos y nietos: muchas nueces de kola, una gallina y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Matrimonio de Òtúrúpọ̀n con Ìrosùn."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Caracoles, nuez de kola (obì)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 186.1 (yorùbá): Òtúrúpọ̀n'Rosù, / Ariwo ni, / a difa fún Delumo / Wọ̀n ni: / \"oką koniijẹ ki aya ko simi. / Nitorinaa bii Delumo ba rúbo, / okọ rẹ̀ a jẹki ó simi\". / Ẹbọ: İgbín Méjì ati egbejielógún owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"İgbin Méjì kiiyo'rawọn lẹnu\".", "Verso 186.2 (yorùbá): Esuru awo Ire: / a difá f'Òtúrúpọ̀n / nlọ gbe Irosù ni'yàwó. / Wọ̀n ni: / \"Wọ̀n a bimọ. / Ọmọ wọ̀n a maa ba wọ̀n bi\". / Opolopo obi, adiyẹ / ati egberindilógún owó li ebọ . / Ô gbọ̀ ó rú.", "REZO: OTRUPON KOSO AKO ANEYE KOMADO ADIFAFUN LADUTA EYELE OGUEDE LEBO. AKUKO, EYELE LEBO. KAFEREFUN SHANGO OBATALA ATI ORUNMILA.", "REZO: OTRUPON ROSO IFA ARANI MOLE BIAN QUELLI QUELI HIBI ECHIN SURO KUTA NI CASA IROSO MULEI TORI AYA KUKUA ORCININCAN KUKUA AIKORDIE EBELLO OWO.", "REZO: AKO LE YOKO MADO ADIFAFUN LADO TA EYELE OGUEDE LEBO AKUKO EYELE LEBO KAFEREFUN SHANGO, OBATALA Y ORUNMILA.", "REZO: OTRUPON ROSO IFA ARANI MOLE BINA ORO QUELLI IBI ECHIN CUTA NI CASA IROSO MULEI TORI ALLA KUKUA ORONICAN CUCUA AIKORDIE EBELLO OWO.LODAFUN OBATALA LODAFUN OBITASA LODAFUN OGGUN.", "REZO: ADIFAFUN YEMAYA OKUTE ICHORL CHON UMBOWADIYE LOBI ARA OFIKALE TRUPON ADA KUKUTE ADIFAFUN OGGUN AYABA OMI MAYAFRA LODAFUN ORUNMILA.", "REZO: OTRUPON OKOSUN WELE NI IFA EYELE KUESUNWELE SHANGO AWO WASA EGGUN IGUI OWELE YEMAYA DIDE OBONI INA SHANGO META AYE EYE NIWA AKUKO OBBI LAYERU IRE ARIKU BABAWA OMI MAYAFERA OMODUN BINIBOSHE AWO MEYUN OMASHENIFA ODA BI BORU SHANGO KAFEREFUN ORUNMILA LORDAFUN YEMAYA."]}]$q$::jsonb),
(187,'71e1ea65c38d6a715e1ea95c3a20c15f',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ọ̀wọ́nrín anuncia que viene algo o alguien que traerá alegría, y pide ofrendar para que Èṣù no la eche a perder. También pide proteger los logros, la reputación y el honor alcanzados. Advierte que la infidelidad en la pareja trae problemas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera un acontecimiento feliz (relato de la gente de Ọ̀yọ́).", "Quiere que un logro de trabajo o social le dure (relato de Ọlasimbo).", "Una conducta en su relación de pareja podría dañar su reputación."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una alegría que ya está cerca.", "Dinero, pareja e hijos que lo siguen.", "Conservar el honor y el respeto ganados."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que la alegría se estropee antes de llegar.", "Perder el honor.", "Infidelidad y promiscuidad."]}, {"titulo": "Enseñanza principal", "texto": "Toda alegría que llega necesita ofrenda para quedarse. El honor que se gana también se cuida."}, {"titulo": "Relatos reunidos", "puntos": ["La alegría de Ọ̀yọ́. Òtúrúpọ̀n Ọ̀wọ́nrín, estamos bailando, estamos gozando, estamos jugando: así adivinaron para toda la gente de Ọ̀yọ́. Les dijeron que algo que alegraría sus corazones venía en camino y estaba cerca, pero que todos debían ofrecer cuatro palomas, bastante aceite de palma y dinero. Ofrecieron, y Èṣù no pudo arruinarles la felicidad.", "Ọlásìmbọ̀ y su honor. La fortuna del dinero me ve y me sigue; la fortuna de la esposa me ve y me sigue; la fortuna de los hijos me ve y me sigue. Así adivinaron para Ọlásìmbọ̀, y le pidieron una carnera y dinero para no perder la honra que había ganado. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la alegría: cuatro palomas, bastante aceite de palma y dinero.", "Para el honor: una carnera y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù, que puede estropear la alegría si no recibe su parte. Ọbàlùfọ̀n da otro nombre a este Odù."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, palomas, carnera."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 187.1 (yorùbá): Òtúrúpọ̀n-Ọ̀wọ́nrín / a njó, a nyò, / Òtúrúpọ̀n-Ọ̀wọ́nrín / ere li a nṣe: / a difá fún wọn l'ode Qyọ̀. / Wọ̀n nỉ: / \"ohun ti o (maa) yọ wọn ninú nbọwa\" / \"O de tan, kiwọ̀n rú\": / Eyẹlé mẹrin, epo, / egbàá mérin owó. / Wọ̀n gbọ̀ wọ̀n rú. / Wọ̀n nỉ: / \"Éṣú konii ba ayọ̀ wọn jẹ o\".", "Verso 187.2 (yorùbá): Owó ri mi o tẹle mi, / Òtúrúpọ̀n-Ọ̀wọ́nrín, / Aya ri mi o tẹle mi, / Òtúrúpọ̀n-Ọ̀wọ́nrín. / Ọmọ ri mi o tele mi, / Òtúrúpọ̀n-Ọ̀wọ́nrín: / a dífá f'Ọlasimbo / Atẹpamoṣẹ-Kolamalelo. / A niki Ọlasimbọ wa rubẹ, / ki ọlá ma le lọ. / Ebọ: Agùtàn ati ogbokànlé-lógún owó. / Ô gbọ̀ ó rú.", "REZO: OTRUPON ÑAO DONI MIDI SHENIMUNI OTA KEKE ORUNMILA OLODAFUN ODE, AKUKO, EYELE, ADIE LEBO.", "REZO: OTRUPO WANIDE NI MODI MIDI CHENIMUNI QUINCHE OTA QUE QUE ORUNMILA LODAFUN ADIE ORUBO AKUKO YARAKO OTA META EKU EYA EBEFA OWO.", "REZO: ONI ONINININI ATENICOSIERE ONI ATENICOGUON ALLEN KOLOKOLO OMUCHUBU LODE.", "REZO: OTRUPO JUANIDE NIMODI MIDI CHENIMUNI QUINCHE OTA QUE QUE ORUMILA OLORDAFUN ORDE EBBO AKUKO EYELE ABEBOARDIE MEYI OTA META EBEFA OWO.", "REZO: ONI ONININI ONI ANTENI OPOJOERE ONIONTINI CORBON ALLAN KOLO OFEQUI TOGUERE OWO.", "REZO: ONI IMBENU ODA REGURE CAIBODO CHEOUON CHEGUON ETU.", "REZO: IRENIFA IFA NI KAFEREFUN ESHU, KAFEREFUN OBATALA. NI MODI NI DI CHENI QUIN CHE OTA GUEGUE NI ORUNMILA OLORDAFUN ORDE EBBO AKUKO EYELE ABEBOADIE MEYI OTA META EBETA OWO.", "REZO: NARE RIFA MOLALA NI ABA ORISHAOKO MOLALA EYUN KOKOLE ELEGBA OUNKO BOGBO INIYE AUN BABA YI YOYOZUN OBAIKU MOCHE BOBOSHE NORUN NOWA ISHU IFA AYE TENE OUNYEN BOGBO TENUYEN ESHU SHU INLE OBANI BARA IFA KAFEREFUN OSHUN, ELEGBA, ORISHAOKO."]}]$q$::jsonb),
(188,'2ce117f1d142e158ae0b7379722e7813',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ọ̀bàrà habla de cuidar la salud para asegurar una vida larga. Los hijos pueden oponerse a las nuevas relaciones de sus padres. Pide ofrendar para que el hijo que crece regrese a casa y para no perder pronto a la pareja buena."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un hijo se está alejando de casa al crecer (relato de Iyàmookẹ).", "Padres e hijos no se ponen de acuerdo sobre una relación nueva.", "La pareja quiere cuidar su vínculo (relato de Tenimaasunwọn y Ajémoorin)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos sanos que regresan a la casa.", "Una buena pareja que dura.", "Vida larga con salud."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que el hijo se aleje al hacerse mayor.", "Perder pronto a la pareja.", "Hijos en contra de la nueva relación de su padre o madre."]}, {"titulo": "Enseñanza principal", "texto": "El honor va y el honor regresa. Lo bueno se valora y se cuida, aunque uno no lo diga en voz alta."}, {"titulo": "Relatos reunidos", "puntos": ["Ìyámọ̀ọ́kẹ́ y el hijo que se va. A Ìyámọ̀ọ́kẹ́ le dijeron que su hijo sería sano y no moriría, pero que al crecer podía no querer quedarse a su lado. Le pidieron una pareja de pichones de paloma y dinero para que su hijo regresara a casa. Ofreció.", "Tẹnímáàsùnwọ̀n y Ajẹ́mọ̀ọ́rìn. Los maridos elogian a sus esposas, pero el barquero nunca elogia a la suya. Así adivinaron para Tẹnímáàsùnwọ̀n, esposo de Ajẹ́mọ̀ọ́rìn. Le dijeron que la mujer que quería era buena, pero que debía ofrecer para no perderla pronto. Le marcaron una carnera, un caracol y dinero. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para que el hijo regrese: una pareja de pichones de paloma (macho y hembra) y dinero.", "Para conservar a la pareja: una carnera, un caracol y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "La familia y la pareja como sostén de la vida larga."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pichones de paloma, caracol, carnera."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 188.1 (yorùbá): Ọlaṣilo-nle, Ọladehinde: / a difá fún lyamookẹ. / Wọ̀n ni: / \"omp naa tiobi koniikú, koniirün, / sùgbọ̀n qmọ naa koniigbe odọ rè / nigbati o ba dagba / nitorinaa ebọ nikioṣe / ki ọmọ naa le maa pada wa ilé\". / Ebọ: Ṣyẹlé-ejigbere ati egbefà owó. / Ó gbọ̀ ó rú.", "Verso 188.2 (yorùbá): Qkọ nyin aya wọn, / ọko-oloką nikojẹ yin'ni: / a difá fún Tẹnimaasunwon / ọkọ Ajémoorin. / Wọ̀n ni: / \"Obirin naa ti o maa fẹ yi, / Obirin rere ni, / kiowa rúbọ kiẹma tètè kú\". / Ẹbọ: Agùtàn, igbín / ati egbèrindilógún owó. / Ó gbó ó rú.", "REZO: OTRUPON OBARA IFE EYUQUELE KAÑUA EKU EÑI LODAFUN ORUNMILA LUBA ONLE ILE ONIFE EYE EYA LUDENBEN OKARA INGARA OKAYI AUN BARIN AYE OBE LODA KAFEREFUN ORISHAOKO, SHANGO, ORUNMILA ATI OGGUN.", "REZO: FAKUYA ESA FAKUYE GUERE BA ESHU ERE LIMO TIMO ISA LUEYE ARAMETE ORISHAOKO SELU ERU BABA LADE OGUE SILUFU AYE."]}]$q$::jsonb),
(189,'1748ae5f3595529448f7d2cd5cfa11e3',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ọ̀kànràn pide ofrendas para evitar problemas con los hijos y con los enemigos. El consultante debe cuidar los acuerdos y procedimientos de sus negocios. Promete que los enemigos huirán antes de que él llegue."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Debe revisar un acuerdo o un procedimiento comercial.", "Le preocupa cómo se portará un hijo en el futuro (relato de Efunbunmi).", "Tiene un pleito y necesita pruebas y asesoría legal concreta (relato de los dos adversarios contra Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Muchos hijos.", "Que los enemigos huyan sin pelear.", "Ganar los pleitos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hijos que crecen y se vuelven delincuentes.", "Enemigos que piden a Èṣù que lo destruya.", "Descuido en los tratos y acuerdos."]}, {"titulo": "Enseñanza principal", "texto": "A los hijos hay que cuidarlos desde que van en la espalda. El que llega anunciando su fuerza espanta a los que conspiran."}, {"titulo": "Relatos reunidos", "puntos": ["Ẹfúnbùnmi y los hijos en la espalda. A Ẹfúnbùnmi le dijeron que tendría muchos hijos, pero que debía ofrecer antes para que los niños que cargaba en la espalda no se volvieran malhechores al crecer. Le marcaron una paloma, dinero y medicina de Ifá. No ofreció. Si lo hubiera hecho, le habrían dado la medicina para bañar a sus hijos.", "Ọ̀rúnmìlà y las dos calabazas. Dos enemigos estaban ante el lugar de Èṣù pidiéndole ayuda para acabar con Ọ̀rúnmìlà. A Ọ̀rúnmìlà le pidieron dos calabazas grandes, dos gallinas y dinero. Ofreció, se ató las dos calabazas a los hombros y se fue hacia el lugar de Èṣù pidiendo bendiciones. Mientras caminaba, las calabazas chocaban entre sí y parecían decir: mataré a Òtúrúpọ̀n, mataré a Ọ̀kànràn. Los enemigos oyeron eso y pensaron: si sin habernos visto ya hace esas amenazas, ¿qué pasará cuando nos encuentre aquí? Huyeron antes de que Ọ̀rúnmìlà llegara. Así venció a sus enemigos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para los hijos: una paloma, dinero y medicina de Ifá.", "Medicina: hojas de ojúùsájú y ẹ̀ṣọ trituradas en agua para bañar a los hijos, aun de mayores; o machacadas con jabón negro.", "Contra los enemigos: dos calabazas grandes, dos gallinas y dinero; llevar las calabazas a los hombros hasta el lugar de Èṣù."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù, ante quien se presentan los pleitos. Ọ̀rúnmìlà vence sin pelear."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ojúùsájú (Petiveria alliacea), ẹ̀ṣọ (Elytraria marginata), jabón negro, calabazas grandes (akèrègbè)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 189.1 (yorùbá): Ọmptolamoyo, / Iyowukode-maar'eniṣ'ẹhin-demi: / a difá fún Efunbunmi. / Wọ̀n ni: / Efunbunmi a bimo pupo / sùgbọ̀n ki o wa rúbọ: / ki omọ rẹ (jojolo) tiopòn si èhin yi, / nigbati o ba dagba / ma baajẹ òdáràn qmọ. / Ebọ: Eyẹlé, egbaa mejilélógún owó ati ewé Ifa. / Ô gbọ̀ ko rú. / Biobarúbo kiaṣe / ewé Ifá fún un kiomaa fi wẹ.", "Verso 189.2 (yorùbá): Òtúrúpọ̀n Kọ̀nràn, / Òtúrúpọ̀n Kọ̀nràn: / a difá fOrúnmilà / ọ̀tá Méjì nro ejó rẹ nidi Eṣú, / wọ̀n nbẹ Eṣú kiobawọn paa. / A niki Ọ̀rúnmìlà rúbọ: / Akeregbe Méjì, / Agbebo-adiyẹ Méjì / ati Ọrinlenirinwo owó. / Ó gbọ̀ ó rú. / Q sọ Akeregbe mejiyi kọ apa / nlọ wure nidi Èṣú. / Bioti nlọ Akeregbe Méjì wonyi nlù / ara wọ̀n wọn ndún biipe Maap'Ọ̀kànràn: / Maap'Òtúrúpọ̀n, / Maap'Ọ̀kànràn, / Maap'Òtúrúpọ̀n / bayi li o nse titi o ferẹẹ de Ìdí Èṣú, / nigbati àwọn ptá rè / gbọ iro ọrọ ileri yi wipe: / li airiwon nitosi, / Ọ̀rúnmìlà nleri to bayi, / bawo ni inkan yoo ti ri / biobafi ojú kan wọn? / Bẹẹni wọn salo si, / ki Ọ̀rúnmìlà toode Ìdí Eṣú. / Bayi ni Çrúnmilà ṣe tiofi ṣégun / àwọn Ọtá rẹ̀ wọnyi.", "REZO: OTRUPON KANA CARAN OTRUPON OLOKARAN GUINI BEDI OCHICA TEÑE COBE ACHE ARAI BATA A UN BABALAWO LODAFUN CUOBA TIORA OIBO LERI.", "REZO: IFA AGUI GUASI OMINI GUASA OCHI BOLENE EYA META AWO AGUI GUASU ORUBO EYE OCHERE AIKORDIE EYELE MEYI OWO LA MELLO.", "REZO: ONI ODO NINCHA OBA ADIFAFUN ADEPERIOLLUPAN AKUKO LEBO YARAKO OLOMBOBO APURATAN ACARAN OKARA KINIBO BIGUN MORE LOLA KAKOYE QUIBABA ADIFAFUN AURA ENICAN IMBO CITOBA EYELE LEBO AKUKO EYELE LEBO.", "REZO: IFA AGUI GUASI OMINI GUASA OCHI BOLENE ASA META AWO AGUI GUASU ORUBO ELLEOCHERE AIKORDIE EYELE MEYI OWO LA MELLE.", "REZO: OTRUPON KANA CARAN OTRUPON GUINI BEDI OCHICA TEÑE COBE ACHE ARAI BATA A UN BABALAWO LODAFUN CUOBA TIORA OIBO LERI.", "REZO: OTRUPON KANA (UN GUIRO GUANO IYEFA PRONTO SE RIEGA ELLE).", "REZO: AGGAYU ABANILE ADO SHAGA KAKAFO OZAIN ULOPARODA ELEGBA UMBO WATLE AWO ORUNMILA INSODE NIFA SOTISHE DEDE AWANTOLOKUN KAFEREFUN ORUNMILA LODAFUN FIFETO, ADIFAFUN OGGUN.", "SUYERE: “ TARIFA FIFETO IBAROTA FIFETO FIFETO AWO FIFETO OMO FIFETO ARIKU BABAGUA SOTISHE AWO FIFETO IFA “", "REZO: OTRUPON KANA ADIFAFUN ADE, ADIFAFUN ETU, IFA NI KAFEREFUN ORUMILA.", "REZO: JEKUA OGGUN IRE NIKAN. OTRUPON KANA OGGUN LONI AWO BORI BALERU IFA IBI TOGU UNYEN EKODI ENI OKUA OMO ALIGBORAN ELEGBA LAFERAYE OGGUN ILE FIYEME OGGUN LOLA MOBUSUN ATITI IFA ONILE OGGUN LOWO OYELE IFA NI ABAORI OGUELEMU OZAIN IFA NI KAFEREFUN ELEGBA. ORUNMILA FORE AYE"]}]$q$::jsonb),
(190,'5e8fcca832107cf496bf07f76b28e099',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ògúndá dice que el momento actual no es bueno para concebir, aunque el futuro es prometedor. Puede haber una pérdida reciente de embarazo o de un recién nacido. Pide corregir a los hijos desde pequeños y ofrendar para que la niñez del hijo sea sana para él y para sus padres."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La familia pasa por la pérdida de un embarazo o de un bebé y busca orientación.", "Pregunta por fertilidad o por un embarazo (relato de Ọ̀rúnmìlà).", "Los padres quieren formar buenos hábitos en un niño (relato de Òtú y su hijo)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Embarazo y un hijo que nace bien.", "Una niñez sana para el hijo y salud para los padres.", "Hijos obedientes que escuchan los buenos consejos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Pérdida de un embarazo o de un recién nacido.", "Un hijo que puede volverse ladrón si no se le corrige a tiempo."]}, {"titulo": "Enseñanza principal", "texto": "Las ramas del ìrókò se podan mientras el árbol es joven; cuando crece, ya no se pueden cortar. Al hijo se le corrige de chico."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀tú y el niño en la espalda. Ọ̀tú cargaba a su hijo recién nacido. El adivino le dijo que ese niño podía volverse ladrón al crecer, y les pidió a los padres un caracol, pescado aro, plátanos, una paloma, dinero y medicina de Ifá para que el niño los obedeciera y escuchara los buenos consejos. La medicina solo se hace si se cumple la ofrenda.", "El hijo de Ọ̀rúnmìlà. A Ọ̀rúnmìlà le anunciaron que su esposa quedaría embarazada y daría a luz. Le pidieron una gallina grande, una chiva y dinero para que la niñez del hijo fuera sana y no perdieran ni al hijo ni la salud de los padres. Escuchó y ofreció. Ante una pérdida de embarazo conviene consultar al médico antes de buscar el siguiente."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para que el hijo obedezca: un caracol, pescado aro, plátanos, una paloma, dinero y medicina de Ifá.", "Medicina: hojas de ẹ̀ṣọ trituradas en agua con el líquido del caracol para bañar al niño; ya mayor, las hojas cocidas en sopa con caracol o pescado ahumado, comida con plátanos maduros.", "Para la niñez sana: una gallina grande, una chiva y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà y su esposa; Ògún en el nombre del Odù."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀ṣọ (Elytraria marginata), plátanos, pescado aro, caracol, ìrókò."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 190.1 (yorùbá): Kékeré liatiipeekan irókò / bioba dagba tán a maa gba ẹbọ: / a daa fún Otú, / Òtú Abiyamo. / Wọ̀n ni: / omo kékeré kan tiabi fún un yi / ti a npòn'lẹhin; / wọ̀n ni: / ole ni ọmọ naa yoo maa jà bioba dagba. / Ki wọ̀n wa rúbo, / ki ọmọ naa le maa gb'ọrọ si wọn lẹnu. / Ẹbọ: İgbin, eja-aro, gèdẹ, eyẹlé, / egbẹtalelọ̀gbọ̀n owó ati ewé Ifá.", "Verso 190.2 (yorùbá): Òtúrúpọ̀n-Egúntán: / a difá fún Ọ̀rúnmìlà; / Wọ̀n ni: / \"aya rẹ̀ maa loyun, o maa bimo\". / Wọ̀n niki ó wa rúbọ / ki igba ọmọ naa baa le san wọn. / Ebọ: Agbebo-Adiyẹ, ewúré, / egbàá mẹ̀talélógbọ̀n owó. / Ó gbọ̀ ó rú.", "REZO: OTRUPON ANGUEDE OBINI KAN LENLE, OBINI OKUNI LOFE OPA EKO UMBO MAFEREFUN ORUNMILA ATI YALORDE.LODAFUN OGGUN ATI OBINI.", "REZO: OTRUPON ANGUEDE OBINI KAN LONIO OCLINI OCU OMHE AIKORDIE YARAKO OTA EBETA OWO.", "REZO: OTRUPON OGUNDA OTRUPAN GUEDE MOLE MOLEDE TAPA OMADA ITAQUITI CORIRODI ADIFAFUN CHARA TINCHOBINI ORICHA EYELE AKUKO ANGUEDE OBINI CAN LONLO OBINI OCUNI LOFE OCUA OCO OMBO. MAFEREFUN ORUMILA, MAFEREFUN YALORDE.", "REZO: OTRUPON ANGUEDE OBINI KAN LONIO OCLINI OCU OMHE AIKORDIE YARAKO OTA EBETA OWO.", "REZO: OTRUPON ANGUEDE, OTRUPON ANGUEDE OGUNDA GOO, IFA INTORI IKU."]}]$q$::jsonb),
(191,'85ea4881054c54c1336edc2f85c30e17',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ọ̀sá habla de salvar a un niño del peligro. Un hijo nuevo o nuevas responsabilidades traen disgustos y contratiempos pasajeros. Pide ofrendar para que el recién nacido no traiga intranquilidad a sus padres y para que los niños no tengan que huir en la espalda de sus madres."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["La familia está cansada con la llegada de un hijo (relato de Konkọn).", "Las obligaciones nuevas traen contratiempos pasajeros.", "Hay una amenaza en la comunidad y hace falta un plan realista para proteger a los niños (relato de Ilara)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Tranquilidad y paz mental con el hijo nuevo.", "Que los niños queden a salvo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desasosiego y falta de descanso por un hijo.", "Huidas, guerras o desplazamientos con los niños a cuestas."]}, {"titulo": "Enseñanza principal", "texto": "Lo que sube también baja. Las responsabilidades nuevas se reciben con ofrenda para que no quiten el sueño."}, {"titulo": "Relatos reunidos", "puntos": ["Kọ̀nkọ̀, la rana. Arriba y abajo: así adivinaron para Kọ̀nkọ̀, la rana toro, y le pidieron un mortero de madera, un caracol, mucho aceite de palma, dinero y medicina de Ifá para que su recién nacido no les trajera intranquilidad a los padres. Kọ̀nkọ̀ no ofreció.", "La gente de Ìlara. Ifá les dijo a los de Ìlara que todos los niños nacidos ese año serían cargados en la espalda de sus madres mientras huían de la batalla. Preguntaron cuál era la ofrenda: aceite de palma, plátanos maduros, manteca de karité, hojas de ifen, jókójẹ́ y wọ̀rọ̀, y dinero. No ofrecieron."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la paz con el hijo: un mortero de madera, un caracol, mucho aceite de palma, dinero y medicina de Ifá con hojas de jókójẹ́ y ẹ̀ṣọ.", "Contra la guerra: aceite de palma, plátanos maduros, manteca de karité (òrí), hojas de ifen, jókójẹ́ y wọ̀rọ̀, y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá protege a los niños y a las madres."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Jókójẹ́ (Cissampelos owariensis), ẹ̀ṣọ (Elytraria marginata), ifen, wọ̀rọ̀, plátano maduro, manteca de karité, mortero de madera."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 191.1 (yorùbá): Igbokegbodo: / a difá fún Kọnkọn. / Wọ̀n niki o wa rúbọ / ki omotitun tiabi yi / ma le ko ğràn aisimi wa ba wọn. / Ẹbọ: Odo-igi kan, / igbin, opplopo epo, / egbàá mẹrindilógún owo ati ewé Ifá. / Kọnkọn mayikan ko rúbo. / Ewé Ifá: Ewé Jókó-jẹ ati ewé eso.", "Verso 191.2 (yorùbá): Òtúrúpọ̀n-Ọ̀sá: / a difá fún wọ̀n ni llara. / Wọn ni: / \"iye gmotitun ti ao bi ninu odún yi, / ao pon wọn sare ogun\" / Wọ̀n ni: Kinni ebọ? / Ebọ: Epo, gèdẹ̀ wẹerẹ tiopọ̀n, òrí, / ewé ifen, ewé Jókó-jé, ewé worò / ati egbàá mọ̀kànlélógún owó. / Wọ̀n ko ru u.", "REZO: OTRUPON SA OFUN ELERUKO EYE ARO KELOSO AKITI LEGBO ABIVE MALA MALA ADIFAFUN LOKO TINSHOMA ORISHA KIRIN AUNI SHESHUN OFIDAN EYELE LEBO. KAFEREFUN OMEFA, ORUNMILA ATI ESHU.", "REZO: OFUN OBORUKO OYO ARO KOLESE AKITILEBO ABIYA MALA ADIFAFUN LOKOTINSHOMA ORISHA KIRIN OSHAKUN OFIKANEYELE LEBO KAFEREFUN OMOFA ORUNMILA ESHU."]}]$q$::jsonb),
(192,'adadaa48aef6d9de45425cdbdc830fcf',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ìká habla de gran prosperidad y buena salud: aumento en la casa y aumento en el campo, esposas que dan hijos y árboles cargados de fruta. El consultante está preocupado por una enfermedad; pide ofrendar para curar el mal que viene de hace tiempo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme una enfermedad; conviene revisarse con un médico (relato de Dejugbe).", "La familia pregunta por embarazo o descendencia.", "Un trabajo del campo o de la familia empieza a dar frutos (relato de Otú)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Aumento en la casa y en el campo.", "Hijos de sus esposas y cosechas abundantes.", "Curación de un mal crónico."]}, {"titulo": "Ibi y advertencias", "puntos": ["Una enfermedad larga, un brazo que no sana."]}, {"titulo": "Enseñanza principal", "texto": "Cuando crece la casa, crece también el campo. La abundancia llega a quien la recibe con ofrenda."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀tú y el aumento. Cuando hay aumento en la casa, hay más aumento en el campo: así adivinaron para Ọ̀tú. Le dijeron que sus esposas tendrían hijos en el hogar y que los árboles de su finca darían fruta en abundancia. Le marcaron plátanos, muchas nueces de kola, bastante kola amarga, tierra y medicina de Ifá. Escuchó y ofreció.", "Dejugbe y su brazo enfermo. Dejugbe tenía un brazo enfermo desde hacía tiempo. Le dijeron que si quería sanar debía ofrecer dos palomas, dos gallinas, aceite de palma, dinero y medicina de Ifá. Escuchó y ofreció. Un mal que dura mucho debe verlo también un médico."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el aumento: plátanos, muchas nueces de kola, bastante orógbó, tierra y medicina de Ifá.", "Para la enfermedad: dos palomas, dos gallinas, aceite de palma, dinero y medicina de Ifá.", "Medicina: hojas de itapàrá molidas con jabón y aceite de palma para frotar el cuerpo."]}, {"titulo": "Relaciones espirituales", "texto": "La tierra y los árboles frutales responden a la ofrenda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Plátano, obì (kola), orógbó (kola amarga), itapàrá (Raphiostylis beninensis), aceite de palma, tierra."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 192.1 (yorùbá): Abijọle, / Ire oko animo: / a difá fún Òtú. / Wọ̀n niki Otú wa rúbọ: / Awon aya rẹ̀ a maa bimo nile, / àwọn igi ti a nka l'oko / a maa so eso fún wọ̀n ká. / Ẹbọ: Ôgẹ̀dẹ̀, ppọlọpọ obi, / ati ewé Ifá. / Ó gbọ̀ ó rú.", "Verso 192.2 (yorùbá): Osangẹdẹgbẹ b'okunrin-ja: / a difá fún Dejugbe / Ökùnrùn-tagobolẹ, / Awuwolapa. / Wọ̀n ni: / \"bii Dejugbe ba nfẹ / ki apa ti ndùn òun san, / wọ̀n niki o rúbo\": / Eyẹlé Méjì, adiyẹ Méjì, epo / ati ewé Ifá pelu egbàárin owó. / Ó gbọ̀ ó rú.", "REZO: OTRUPON KA OTRUPANDO OTRUPANKO ADIFAFUN ANA OMO OGGUN KE AKUKO LEBO. KE OTRUPANKA ADIFAFUN OBA OWUNKO. AKUKO LEBO. OTRUPON KA LODAFUN OGGUN, OSHANLA, OMO OLOFIN, ADIFAFUN ABURE OMO OLOFIN.", "REZO: OTRUPANCO ORUPANCO ADIFAFUN ANA OMO ODO AKAMO OGGUN KE AKUKO LEBO QUE OTRUPANCA ADIFAFUN OBA OUNKO ECA AKUKO LEBO. LORDAFUN OGGUN OSHANLA OMO OLOFIN."]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from nuevas v where e.numero=v.numero and md5(e.secciones::text)=v.viejo returning e.numero;
